begin;

create temporary table imported_question_batch1_seed (
  id uuid primary key,
  certification_code text not null,
  lesson_slug text not null,
  question_type text not null,
  question_text text not null,
  difficulty text not null,
  explanation text not null,
  is_published boolean not null,
  source_reference text not null,
  source_order integer not null
) on commit drop;

create temporary table imported_question_option_batch1_seed (
  id uuid primary key,
  question_id uuid not null,
  option_text text not null,
  is_correct boolean not null,
  explanation text not null,
  display_order integer not null
) on commit drop;

insert into imported_question_batch1_seed (
  id, certification_code, lesson_slug, question_type, question_text,
  difficulty, explanation, is_published, source_reference, source_order
)
values
  ('62000000-0000-4000-8000-000000000001', 'az-900', 'what-is-cloud-computing', 'single_choice', 'O que melhor define o conceito de cloud computing?', 'easy', 'Cloud computing e a entrega de recursos de TI sob demanda pela internet, permitindo que empresas usem servidores, armazenamento e outros servicos sem precisar comprar e manter infraestrutura fisica, pagando apenas pelo que consomem.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 1),
  ('62000000-0000-4000-8000-000000000002', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Qual das opcoes a seguir e uma caracteristica essencial da cloud computing?', 'easy', 'O autoatendimento sob demanda e uma das caracteristicas fundamentais da cloud computing: o usuario pode provisionar recursos como poder de processamento e armazenamento automaticamente, sem precisar de interacao humana com o provedor de nuvem.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 2),
  ('62000000-0000-4000-8000-000000000003', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Em cloud computing, o que caracteriza o ''acesso amplo a rede'' (broad network access)?', 'easy', 'Acesso amplo a rede significa que os servicos de nuvem estao disponiveis pela internet e podem ser utilizados a partir de diferentes dispositivos e plataformas, sem exigir hardware especifico do provedor.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 3),
  ('62000000-0000-4000-8000-000000000004', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Uma empresa de medio porte quer reduzir o investimento inicial em servidores fisicos e evitar a manutencao continua desse hardware. Qual abordagem melhor atende a essa necessidade?', 'medium', 'A migracao para cloud computing permite que a empresa utilize recursos de computacao sob demanda, sem necessidade de investimento inicial em hardware nem de manutencao continua, ja que essa responsabilidade passa a ser do provedor de nuvem.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 4),
  ('62000000-0000-4000-8000-000000000005', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Uma startup de tecnologia espera um crescimento imprevisivel no numero de usuarios nos proximos meses e quer evitar comprometer capital em infraestrutura antes de saber sua real necessidade. Qual caracteristica da cloud computing atende diretamente a esse cenario?', 'medium', 'O modelo de consumo sob demanda da cloud computing permite que a startup pague apenas pelos recursos que utiliza, ajustando a capacidade conforme a demanda real, sem precisar prever ou investir antecipadamente em infraestrutura.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 5),
  ('62000000-0000-4000-8000-000000000006', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Um funcionario precisa acessar os sistemas corporativos de sua empresa a partir de casa, de um hotel durante viagem e do escritorio, utilizando diferentes dispositivos. Qual conceito de cloud computing viabiliza esse cenario?', 'medium', 'O acesso amplo a rede e a caracteristica da cloud computing que permite que usuarios se conectem aos servicos a partir de qualquer lugar com conexao a internet, usando diferentes dispositivos, como notebooks e smartphones.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 6),
  ('62000000-0000-4000-8000-000000000007', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Uma empresa de varejo online tem picos de acesso apenas durante datas promocionais, como a Black Friday, e trafego baixo no restante do ano. Ela deseja pagar apenas pela capacidade computacional que realmente utiliza em cada periodo. Qual principio de cloud computing atende a essa necessidade?', 'medium', 'O modelo de consumo baseado no uso permite que a empresa pague apenas pelos recursos utilizados em cada periodo, o que e ideal para cenarios com picos sazonais de demanda, como datas promocionais, evitando desperdicio de capacidade ociosa.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 7),
  ('62000000-0000-4000-8000-000000000008', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Comparando a infraestrutura on-premises tradicional com a cloud computing, qual e uma diferenca correta em relacao ao tempo de provisionamento de novos recursos?', 'medium', 'Uma das vantagens da cloud computing e a rapidez no provisionamento de recursos: novos servidores virtuais podem estar disponiveis em minutos, enquanto no modelo on-premises e necessario comprar, entregar e instalar hardware fisico, um processo que pode levar semanas ou meses.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 8),
  ('62000000-0000-4000-8000-000000000009', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Uma empresa avalia migrar totalmente sua infraestrutura para a nuvem, mas possui um sistema legado com requisitos de hardware muito especificos e baixa demanda de acesso externo. Qual conclusao mais adequada essa empresa deve considerar sobre o uso de cloud computing?', 'hard', 'Cloud computing nao exige uma migracao completa e obrigatoria; e comum adotar uma abordagem hibrida, migrando cargas de trabalho que se beneficiam da elasticidade e do acesso remoto da nuvem, enquanto sistemas legados com requisitos muito especificos podem permanecer on-premises.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 9),
  ('62000000-0000-4000-8000-000000000010', 'az-900', 'what-is-cloud-computing', 'single_choice', 'Uma equipe de TI esta avaliando se deve manter uma aplicacao interna de baixo uso, acessada apenas por 5 funcionarios em horario comercial, totalmente em um servidor local, ou migra-la para a nuvem. Qual fator e mais relevante para essa decisao, considerando os principios de cloud computing?', 'hard', 'Ao decidir migrar uma aplicacao de baixo uso para a nuvem, o fator mais relevante e analisar o custo-beneficio entre manter hardware dedicado, com custos fixos independentemente do uso, e utilizar um modelo de consumo sob demanda, que pode reduzir custos para cargas de trabalho pequenas ou esporadicas.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 10),
  ('62000000-0000-4000-8000-000000000011', 'az-900', 'shared-responsibility-model', 'single_choice', 'O que e o modelo de responsabilidade compartilhada na cloud computing?', 'easy', 'O modelo de responsabilidade compartilhada estabelece uma divisao clara entre o que o provedor de nuvem gerencia (como a seguranca fisica do datacenter e a infraestrutura) e o que o cliente gerencia (como dados, identidades e configuracoes), variando conforme o tipo de servico utilizado.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 11),
  ('62000000-0000-4000-8000-000000000012', 'az-900', 'shared-responsibility-model', 'single_choice', 'No modelo de responsabilidade compartilhada, quem e sempre responsavel pela seguranca fisica dos datacenters, independentemente do tipo de servico contratado?', 'easy', 'A seguranca fisica dos datacenters, incluindo controle de acesso, energia e refrigeracao, e sempre de responsabilidade do provedor de nuvem, independentemente de o cliente utilizar IaaS, PaaS ou SaaS.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 12),
  ('62000000-0000-4000-8000-000000000013', 'az-900', 'shared-responsibility-model', 'single_choice', 'No modelo de responsabilidade compartilhada, o cliente e sempre responsavel por qual dos itens a seguir, independentemente do tipo de servico de nuvem utilizado?', 'easy', 'Independentemente do modelo de servico contratado (IaaS, PaaS ou SaaS), o cliente sempre mantem responsabilidade sobre seus proprios dados, sua classificacao e a gestao de identidades e acessos, pois o provedor nao tem controle sobre esse conteudo.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 13),
  ('62000000-0000-4000-8000-000000000014', 'az-900', 'shared-responsibility-model', 'single_choice', 'Uma empresa utiliza uma maquina virtual (IaaS) na nuvem para hospedar sua aplicacao. Segundo o modelo de responsabilidade compartilhada, de quem e a responsabilidade de aplicar atualizacoes de seguranca no sistema operacional da maquina virtual?', 'medium', 'Em modelos IaaS, o provedor gerencia a infraestrutura fisica, redes e virtualizacao, mas o cliente e responsavel por gerenciar o sistema operacional da maquina virtual, incluindo aplicar atualizacoes e patches de seguranca.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 14),
  ('62000000-0000-4000-8000-000000000015', 'az-900', 'shared-responsibility-model', 'single_choice', 'Uma empresa utiliza um servico SaaS de e-mail corporativo na nuvem. Qual responsabilidade permanece do cliente mesmo nesse modelo, com maior parte da infraestrutura gerenciada pelo provedor?', 'medium', 'Mesmo em SaaS, onde o provedor gerencia quase toda a infraestrutura, aplicativo e plataforma, o cliente continua responsavel pela gestao de identidades, controle de acesso e protecao de seus proprios dados dentro do servico.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 15),
  ('62000000-0000-4000-8000-000000000016', 'az-900', 'shared-responsibility-model', 'single_choice', 'Uma equipe de seguranca esta definindo, com base no modelo de responsabilidade compartilhada, como as tarefas se dividem ao usar um servico PaaS. Qual afirmacao esta correta sobre esse cenario?', 'medium', 'Em PaaS, o provedor assume a gestao de runtime, middleware, sistema operacional e infraestrutura subjacente, mas o cliente ainda e responsavel por proteger os dados, o codigo da aplicacao e o gerenciamento de identidades dos usuarios que a utilizam.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 16),
  ('62000000-0000-4000-8000-000000000017', 'az-900', 'shared-responsibility-model', 'single_choice', 'Uma empresa esta migrando cargas de trabalho de IaaS para SaaS. Como essa mudanca normalmente afeta a divisao de responsabilidades segundo o modelo de responsabilidade compartilhada?', 'medium', 'A medida que uma empresa migra de IaaS para PaaS ou SaaS, o provedor assume progressivamente mais camadas de responsabilidade (sistema operacional, runtime, aplicacao), reduzindo a carga de gerenciamento do cliente, que passa a focar principalmente em dados e identidades.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 17),
  ('62000000-0000-4000-8000-000000000018', 'az-900', 'shared-responsibility-model', 'single_choice', 'Comparando os modelos IaaS, PaaS e SaaS quanto a responsabilidade pela gestao do sistema operacional, qual afirmacao esta correta?', 'medium', 'No modelo IaaS, o cliente tem controle e responsabilidade sobre o sistema operacional das maquinas virtuais. Ja em PaaS e SaaS, o provedor gerencia o sistema operacional, permitindo que o cliente foque na aplicacao ou apenas no uso do software.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 18),
  ('62000000-0000-4000-8000-000000000019', 'az-900', 'shared-responsibility-model', 'single_choice', 'Uma empresa sofreu um incidente de seguranca porque um funcionario utilizou uma senha fraca para acessar um servico SaaS contratado na nuvem. Considerando o modelo de responsabilidade compartilhada, quem deve ser responsabilizado principalmente por essa falha?', 'hard', 'Mesmo em modelos SaaS, a gestao de identidades e o cumprimento de politicas de senha continuam sendo responsabilidade do cliente. Uma senha fraca escolhida por um funcionario representa uma falha na governanca de identidade da empresa, nao do provedor de nuvem.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 19),
  ('62000000-0000-4000-8000-000000000020', 'az-900', 'shared-responsibility-model', 'single_choice', 'Uma organizacao esta analisando qual modelo de servico de nuvem adotar (IaaS, PaaS ou SaaS) para reduzir ao maximo sua carga operacional de seguranca, mesmo sabendo que isso significa menos controle sobre a customizacao do sistema operacional e da infraestrutura. Qual modelo, segundo o principio de responsabilidade compartilhada, transfere a maior parte das responsabilidades de seguranca ao provedor?', 'hard', 'Entre os modelos de servico, o SaaS e o que transfere a maior parte da responsabilidade de seguranca ao provedor, ja que ele gerencia infraestrutura, sistema operacional, runtime e a propria aplicacao, restando ao cliente principalmente a governanca de dados e identidades.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Shared responsibility model'' (AZ-900)', 20),
  ('62000000-0000-4000-8000-000000000021', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'O que caracteriza o modelo de nuvem publica?', 'easy', 'Na nuvem publica, os recursos de computacao sao fornecidos por terceiros, como a Microsoft no caso do Azure, e disponibilizados pela internet, sendo compartilhados entre diversos clientes, o que geralmente reduz custos e aumenta a escalabilidade.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 21),
  ('62000000-0000-4000-8000-000000000022', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Qual das opcoes descreve corretamente a nuvem privada?', 'easy', 'A nuvem privada e um ambiente dedicado a uma unica organizacao, podendo ser hospedado no proprio datacenter da empresa ou por um provedor terceirizado, mas sempre com recursos exclusivos e isolados para aquele cliente.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 22),
  ('62000000-0000-4000-8000-000000000023', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'O que define o modelo de nuvem hibrida?', 'easy', 'A nuvem hibrida combina elementos de nuvem publica e nuvem privada (ou infraestrutura on-premises), permitindo que uma organizacao mova cargas de trabalho e dados entre esses ambientes conforme suas necessidades de custo, seguranca ou desempenho.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 23),
  ('62000000-0000-4000-8000-000000000024', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Uma instituicao financeira precisa manter dados sensiveis de clientes em um ambiente totalmente sob seu controle, devido a exigencias regulatorias rigidas, sem compartilhar infraestrutura com outras empresas. Qual modelo de nuvem melhor atende a essa necessidade?', 'medium', 'Para instituicoes com exigencias regulatorias rigidas sobre isolamento e controle de dados, a nuvem privada e geralmente a mais indicada, pois oferece um ambiente dedicado exclusivamente a organizacao, sem compartilhamento de infraestrutura com terceiros.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 24),
  ('62000000-0000-4000-8000-000000000025', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Uma empresa de e-commerce mantem a maior parte de suas operacoes em servidores on-premises, mas deseja usar a nuvem publica apenas durante periodos de pico de trafego, como a Black Friday, mantendo os dois ambientes conectados. Qual modelo de nuvem essa empresa esta adotando?', 'medium', 'Ao combinar infraestrutura on-premises com recursos de nuvem publica, utilizados de forma flexivel durante picos de demanda, a empresa esta adotando o modelo de nuvem hibrida, que permite essa integracao entre ambientes.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 25),
  ('62000000-0000-4000-8000-000000000026', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Uma agencia governamental precisa disponibilizar um portal de servicos ao publico em geral, com grande variacao de acessos, sem restricoes de compartilhamento de infraestrutura com outros orgaos. Qual modelo de nuvem e mais adequado para esse portal?', 'medium', 'Para um portal de acesso publico com grande variacao de trafego e sem exigencia de isolamento total de infraestrutura, a nuvem publica e adequada, pois oferece escalabilidade elastica para absorver picos de acesso sem grande investimento fixo.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 26),
  ('62000000-0000-4000-8000-000000000027', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Uma empresa de saude precisa manter registros medicos sensiveis em um ambiente altamente controlado, mas tambem deseja usar aplicacoes de analise de dados hospedadas em nuvem publica para gerar relatorios nao sensiveis. Qual modelo de nuvem permite atender a essas duas necessidades simultaneamente?', 'medium', 'A nuvem hibrida e indicada nesse cenario, pois permite manter dados sensiveis em um ambiente privado controlado, enquanto aplicacoes de analise de dados nao sensiveis podem aproveitar a escalabilidade e o custo-beneficio da nuvem publica.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 27),
  ('62000000-0000-4000-8000-000000000028', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Comparando nuvem publica e nuvem privada, qual afirmacao sobre controle de infraestrutura esta correta?', 'medium', 'Na nuvem privada, a organizacao tem maior controle sobre a infraestrutura, pois os recursos sao dedicados a ela. Ja na nuvem publica, parte significativa do controle da infraestrutura fisica fica sob responsabilidade do provedor terceirizado.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 28),
  ('62000000-0000-4000-8000-000000000029', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Uma multinacional opera em diversos paises com legislacoes diferentes sobre armazenamento de dados. Ela decide manter dados de clientes europeus em um ambiente privado local devido a regulamentacoes especificas, enquanto usa nuvem publica para cargas de trabalho de marketing sem dados sensiveis em outras regioes. Qual conclusao melhor descreve essa estrategia?', 'hard', 'Ao combinar um ambiente privado para dados sujeitos a regulamentacoes especificas com nuvem publica para cargas de trabalho sem dados sensiveis, a multinacional adota uma estrategia de nuvem hibrida, equilibrando conformidade regulatoria com flexibilidade e custo-beneficio.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 29),
  ('62000000-0000-4000-8000-000000000030', 'az-900', 'public-private-hybrid-cloud', 'single_choice', 'Uma empresa de midia deseja lancar um servico de streaming com demanda extremamente variavel e imprevisivel, sem exigencias regulatorias de isolamento de dados, priorizando custo-beneficio e velocidade de escalonamento. Qual modelo de implantacao de nuvem e o mais indicado para esse cenario?', 'hard', 'Para um servico com demanda extremamente variavel, sem exigencias regulatorias de isolamento, a nuvem publica e geralmente a escolha mais adequada, pois oferece escalabilidade elastica sob demanda e melhor custo-beneficio em comparacao a manter infraestrutura propria.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 30),
  ('62000000-0000-4000-8000-000000000031', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Ao escolher um modelo de implantacao de nuvem (publica, privada ou hibrida), qual fator e considerado fundamental na decisao?', 'easy', 'A escolha do modelo de implantacao de nuvem deve considerar fatores como requisitos de seguranca, conformidade regulatoria, controle desejado sobre a infraestrutura e orcamento disponivel, pois esses aspectos impactam diretamente qual modelo melhor atende as necessidades da organizacao.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 31),
  ('62000000-0000-4000-8000-000000000032', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma empresa sem exigencias regulatorias especificas busca o menor custo inicial possivel e nao se importa em compartilhar infraestrutura fisica com outras organizacoes. Qual modelo de nuvem tende a ser mais adequado?', 'easy', 'Para organizacoes sem exigencias regulatorias rigidas, que priorizam menor custo inicial e nao se importam em compartilhar infraestrutura, a nuvem publica costuma ser a opcao mais adequada, ja que reduz investimentos iniciais e oferece escalabilidade.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 32),
  ('62000000-0000-4000-8000-000000000033', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Qual das opcoes a seguir representa um criterio valido ao decidir entre nuvem publica, privada ou hibrida?', 'easy', 'Criterios tecnicos como o nivel de controle necessario sobre a infraestrutura, requisitos de conformidade regulatoria e o perfil de carga de trabalho sao fundamentais para escolher entre nuvem publica, privada ou hibrida.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 33),
  ('62000000-0000-4000-8000-000000000034', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma empresa de tecnologia financeira (fintech) precisa atender a rigidas exigencias de auditoria e armazenar dados de transacoes em um ambiente altamente controlado, mas tambem deseja aproveitar a escalabilidade da nuvem publica para seu site institucional. Qual modelo de nuvem melhor equilibra essas necessidades?', 'medium', 'A nuvem hibrida permite que a fintech mantenha os dados de transacoes financeiras, sujeitos a rigida auditoria, em um ambiente privado controlado, enquanto aproveita a escalabilidade e o custo-beneficio da nuvem publica para cargas de trabalho menos criticas, como o site institucional.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 34),
  ('62000000-0000-4000-8000-000000000035', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma empresa em fase de testes de um novo produto digital quer validar a ideia rapidamente, com o menor investimento possivel, sem se comprometer com infraestrutura de longo prazo. Qual modelo de nuvem melhor atende a essa fase inicial do projeto?', 'medium', 'Na fase de validacao de um novo produto, a nuvem publica e geralmente a mais indicada, pois permite testar rapidamente com baixo investimento inicial, sem compromissos de longo prazo, e ajustar ou descontinuar recursos conforme os resultados dos testes.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 35),
  ('62000000-0000-4000-8000-000000000036', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma industria de manufatura possui sistemas de controle de producao que precisam de baixissima latencia e operacao mesmo sem conexao constante a internet, mas tambem quer usar a nuvem publica para analise de dados historicos. Qual modelo de nuvem melhor atende a essa combinacao de necessidades?', 'medium', 'A nuvem hibrida e adequada nesse cenario, pois permite manter sistemas criticos de controle de producao localmente, com baixa latencia e independencia de conexao constante, enquanto a analise de dados historicos pode aproveitar a escalabilidade da nuvem publica.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 36),
  ('62000000-0000-4000-8000-000000000037', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma organizacao sem fins lucrativos possui orcamento limitado e deseja hospedar seu site e sistema de doacoes online, sem exigencias regulatorias especificas sobre isolamento de dados. Qual modelo de nuvem tende a ser o mais economico e adequado?', 'medium', 'Para uma organizacao com orcamento limitado e sem exigencias regulatorias especificas, a nuvem publica tende a ser a opcao mais economica, pois evita investimentos iniciais elevados e permite pagar apenas pelos recursos utilizados.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 37),
  ('62000000-0000-4000-8000-000000000038', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Comparando os criterios de decisao para nuvem publica versus nuvem privada, qual afirmacao esta correta em relacao ao custo?', 'medium', 'De forma geral, a nuvem publica tende a apresentar menor custo inicial, ja que os recursos sao compartilhados entre diversos clientes, enquanto a nuvem privada normalmente exige maior investimento devido a infraestrutura dedicada a uma unica organizacao.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 38),
  ('62000000-0000-4000-8000-000000000039', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma empresa de saude precisa decidir entre nuvem publica e nuvem hibrida para armazenar prontuarios eletronicos de pacientes, considerando exigencias de conformidade com legislacoes de protecao de dados de saude. Qual analise e mais adequada para essa decisao?', 'hard', 'A decisao entre nuvem publica e hibrida para dados sensiveis de saude deve considerar se as exigencias regulatorias de protecao de dados sao plenamente atendidas pela nuvem publica; quando ha necessidade de controle adicional, um modelo hibrido pode oferecer o equilibrio necessario entre conformidade e flexibilidade.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 39),
  ('62000000-0000-4000-8000-000000000040', 'az-900', 'choosing-a-cloud-model', 'single_choice', 'Uma empresa de logistica opera em multiplas regioes geograficas com legislacoes diferentes, possui alguns sistemas legados que nao podem ser facilmente migrados e deseja modernizar gradualmente sua infraestrutura, aproveitando escalabilidade quando possivel. Qual estrategia de modelo de implantacao melhor atende a essa realidade complexa?', 'hard', 'Diante de sistemas legados que nao podem ser facilmente migrados e da necessidade de modernizacao gradual, a estrategia de nuvem hibrida e a mais adequada, permitindo migrar progressivamente as cargas de trabalho compativeis para a nuvem publica, enquanto os sistemas legados permanecem on-premises ate serem modernizados.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' - unidade ''Cloud deployment models'' (AZ-900)', 40),
  ('62000000-0000-4000-8000-000000000041', 'az-900', 'consumption-based-model', 'single_choice', 'O que caracteriza o modelo de consumo baseado no uso (consumption-based model) da cloud computing?', 'easy', 'O modelo de consumo baseado no uso e uma caracteristica central da cloud computing, na qual o cliente paga apenas pelos recursos que efetivamente utiliza, como poder de processamento, armazenamento e largura de banda, sem necessidade de investimento inicial em hardware fisico.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 41),
  ('62000000-0000-4000-8000-000000000042', 'az-900', 'consumption-based-model', 'single_choice', 'Qual e uma vantagem direta do modelo de consumo baseado no uso para uma empresa com demanda sazonal?', 'easy', 'Uma das principais vantagens do modelo de consumo baseado no uso e a flexibilidade de custos: empresas com demanda sazonal pagam menos durante periodos de baixa utilizacao e podem aumentar o consumo, e o custo correspondente, apenas quando necessario.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 42),
  ('62000000-0000-4000-8000-000000000043', 'az-900', 'consumption-based-model', 'single_choice', 'No modelo de consumo baseado no uso, o que geralmente determina o valor cobrado do cliente?', 'easy', 'No modelo de consumo baseado no uso, a cobranca e baseada na quantidade de recursos computacionais efetivamente utilizados pelo cliente, como poder de processamento, armazenamento em disco e trafego de rede, e nao em fatores administrativos da empresa.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 43),
  ('62000000-0000-4000-8000-000000000044', 'az-900', 'consumption-based-model', 'single_choice', 'Uma empresa de analise de dados executa processos pesados de processamento apenas durante a madrugada, ficando praticamente ociosa durante o dia. Qual beneficio do modelo de consumo baseado no uso e mais relevante para essa empresa?', 'medium', 'O modelo de consumo baseado no uso permite que a empresa pague apenas pelos recursos utilizados durante o processamento intenso na madrugada, reduzindo custos durante os periodos de baixa ou nenhuma utilizacao ao longo do dia.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 44),
  ('62000000-0000-4000-8000-000000000045', 'az-900', 'consumption-based-model', 'single_choice', 'Um desenvolvedor independente cria um aplicativo que, no inicio, tera poucos usuarios, mas pode crescer rapidamente se for bem-sucedido. Ele nao quer investir dinheiro em servidores antes de saber se o aplicativo tera sucesso. Qual caracteristica do modelo de consumo baseado no uso atende diretamente a essa necessidade?', 'medium', 'O modelo de consumo baseado no uso permite que o desenvolvedor comece com poucos recursos, sem investimento inicial significativo, e aumente o consumo, e consequentemente o custo, apenas se o aplicativo realmente crescer em numero de usuarios.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 45),
  ('62000000-0000-4000-8000-000000000046', 'az-900', 'consumption-based-model', 'single_choice', 'Uma equipe de desenvolvimento cria um ambiente de testes na nuvem apenas durante o horario comercial, desligando os recursos a noite e nos finais de semana. Qual efeito direto isso tem no modelo de consumo baseado no uso?', 'medium', 'Ao desligar os recursos fora do horario comercial, a equipe reduz o tempo de utilizacao efetiva do ambiente de testes, o que, no modelo de consumo baseado no uso, resulta em menor custo, ja que a cobranca e proporcional ao tempo e a quantidade de recursos utilizados.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 46),
  ('62000000-0000-4000-8000-000000000047', 'az-900', 'consumption-based-model', 'single_choice', 'Uma empresa de eventos utiliza recursos de nuvem intensamente apenas durante a organizacao de grandes eventos, que ocorrem poucas vezes ao ano. Qual abordagem, alinhada ao modelo de consumo baseado no uso, e mais economica para essa empresa?', 'medium', 'A abordagem mais economica, alinhada ao modelo de consumo baseado no uso, e provisionar recursos adicionais apenas durante os periodos de maior demanda, como a organizacao de eventos, e reduzi-los logo depois, pagando apenas pelo uso efetivo em cada periodo.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 47),
  ('62000000-0000-4000-8000-000000000048', 'az-900', 'consumption-based-model', 'single_choice', 'Comparando o modelo de consumo baseado no uso com o modelo de compra antecipada de hardware, qual afirmacao esta correta em relacao ao risco financeiro?', 'medium', 'No modelo de consumo baseado no uso, a empresa paga apenas pelo que utiliza, reduzindo o risco financeiro de investir em capacidade que pode ficar ociosa, ao contrario da compra antecipada de hardware, em que o investimento e feito antes de conhecer a real necessidade de uso.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 48),
  ('62000000-0000-4000-8000-000000000049', 'az-900', 'consumption-based-model', 'single_choice', 'Uma empresa comparou dois cenarios: no primeiro, comprou servidores fisicos dimensionados para o pico maximo de demanda esperado; no segundo, utilizou recursos de nuvem no modelo de consumo baseado no uso, ajustando a capacidade conforme a demanda real. Qual conclusao e mais precisa sobre a eficiencia financeira desses cenarios?', 'hard', 'Comprar hardware dimensionado para o pico maximo de demanda frequentemente resulta em capacidade ociosa durante periodos de baixa utilizacao, enquanto o modelo de consumo baseado no uso ajusta os custos a demanda real, tendendo a ser mais eficiente financeiramente em cenarios de demanda variavel.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 49),
  ('62000000-0000-4000-8000-000000000050', 'az-900', 'consumption-based-model', 'single_choice', 'Uma empresa de tecnologia percebe que seus custos de nuvem tem aumentado significativamente, mesmo sem crescimento proporcional de usuarios. Ao investigar, descobre que diversos ambientes de teste ficam ativos continuamente, mesmo fora do horario de uso da equipe. Qual acao, alinhada ao modelo de consumo baseado no uso, melhor resolve esse problema?', 'hard', 'A solucao mais alinhada ao modelo de consumo baseado no uso e implementar rotinas automaticas para desligar ou reduzir a capacidade dos ambientes de teste fora do horario de uso, garantindo que a empresa pague apenas pelos recursos efetivamente necessarios.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 50),
  ('62000000-0000-4000-8000-000000000051', 'az-900', 'capex-vs-opex', 'single_choice', 'O que significa a sigla CapEx no contexto de investimentos em TI?', 'easy', 'CapEx (Capital Expenditure) refere-se a despesas de capital, geralmente investimentos iniciais significativos em ativos fisicos, como a compra de servidores e equipamentos, que sao registrados no balanco patrimonial e depreciados ao longo do tempo.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 51),
  ('62000000-0000-4000-8000-000000000052', 'az-900', 'capex-vs-opex', 'single_choice', 'O que significa a sigla OpEx no contexto de custos de TI?', 'easy', 'OpEx (Operational Expenditure) refere-se a despesas operacionais recorrentes, como o pagamento por servicos de nuvem conforme o consumo, sendo tratadas como custos do periodo corrente, e nao como investimento em ativos de longo prazo.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 52),
  ('62000000-0000-4000-8000-000000000053', 'az-900', 'capex-vs-opex', 'single_choice', 'Qual das opcoes a seguir representa um exemplo tipico de despesa classificada como CapEx?', 'easy', 'A compra de servidores fisicos e um exemplo classico de CapEx, pois representa um investimento inicial significativo em um ativo de longo prazo, que sera depreciado ao longo dos anos, diferente de despesas recorrentes baseadas em consumo.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 53),
  ('62000000-0000-4000-8000-000000000054', 'az-900', 'capex-vs-opex', 'single_choice', 'Uma empresa esta decidindo entre comprar servidores fisicos (CapEx) ou utilizar servicos de nuvem pagos conforme o uso (OpEx). Ela tem fluxo de caixa limitado no curto prazo e prefere evitar grandes desembolsos iniciais. Qual modelo tende a ser mais adequado para essa situacao?', 'medium', 'Para empresas com fluxo de caixa limitado no curto prazo, o modelo OpEx tende a ser mais adequado, pois distribui os custos ao longo do tempo, conforme o uso dos servicos, evitando o grande desembolso inicial caracteristico do CapEx.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 54),
  ('62000000-0000-4000-8000-000000000055', 'az-900', 'capex-vs-opex', 'single_choice', 'Uma empresa optou por utilizar exclusivamente servicos de nuvem publica, pagando mensalmente conforme o consumo de recursos, sem qualquer compra de hardware fisico. Como essas despesas sao tipicamente classificadas do ponto de vista financeiro?', 'medium', 'Despesas com servicos de nuvem pagos conforme o consumo mensal, sem compra de ativos fisicos, sao tipicamente classificadas como OpEx (despesas operacionais), pois representam custos recorrentes do periodo, e nao investimentos em ativos de capital.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 55),
  ('62000000-0000-4000-8000-000000000056', 'az-900', 'capex-vs-opex', 'single_choice', 'O departamento financeiro de uma empresa quer melhorar a previsibilidade orcamentaria, evitando grandes picos de investimento em um unico periodo, e prefere distribuir os custos de TI de forma mais uniforme ao longo do ano. Qual modelo de despesa tende a favorecer esse objetivo?', 'medium', 'O modelo OpEx tende a favorecer uma distribuicao mais uniforme dos custos ao longo do tempo, ja que os pagamentos ocorrem de forma recorrente conforme o consumo dos servicos, ao contrario do CapEx, que concentra grandes investimentos em momentos especificos.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 56),
  ('62000000-0000-4000-8000-000000000057', 'az-900', 'capex-vs-opex', 'single_choice', 'Uma empresa decide migrar da compra de servidores fisicos para o uso de servicos de nuvem pagos por consumo. Do ponto de vista contabil, como essa mudanca normalmente reclassifica os gastos de TI da empresa?', 'medium', 'Ao migrar da compra de servidores fisicos (CapEx) para servicos de nuvem pagos por consumo, a empresa normalmente passa a ter uma parcela maior de suas despesas de TI classificadas como OpEx, ja que os pagamentos passam a ser recorrentes e vinculados ao uso.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 57),
  ('62000000-0000-4000-8000-000000000058', 'az-900', 'capex-vs-opex', 'single_choice', 'Comparando CapEx e OpEx quanto a flexibilidade para ajustar os gastos conforme mudancas na demanda, qual afirmacao esta correta?', 'medium', 'O modelo OpEx costuma oferecer maior flexibilidade, pois os gastos podem ser ajustados conforme o consumo real dos servicos, aumentando ou reduzindo conforme a demanda. Ja o CapEx representa um investimento fixo, ja realizado, dificil de ajustar rapidamente.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 58),
  ('62000000-0000-4000-8000-000000000059', 'az-900', 'capex-vs-opex', 'single_choice', 'Uma empresa esta avaliando os impactos financeiros de longo prazo entre manter um datacenter proprio (CapEx elevado, com depreciacao ao longo dos anos) e migrar totalmente para a nuvem (OpEx recorrente). Qual analise financeira e mais adequada para embasar essa decisao?', 'hard', 'Uma analise financeira robusta deve comparar o custo total de propriedade (TCO) de cada modelo ao longo do tempo, considerando fatores como depreciacao, manutencao, obsolescencia tecnologica no caso do CapEx, frente a flexibilidade e previsibilidade dos custos recorrentes do OpEx.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 59),
  ('62000000-0000-4000-8000-000000000060', 'az-900', 'capex-vs-opex', 'single_choice', 'Uma empresa em rapido crescimento precisa decidir sua estrategia de investimento em TI para os proximos anos, equilibrando a necessidade de preservar caixa para expansao do negocio com a busca por previsibilidade de custos operacionais. Qual estrategia financeira melhor atende a esses objetivos simultaneos?', 'hard', 'Para uma empresa em rapido crescimento que precisa preservar caixa e busca previsibilidade, priorizar o modelo OpEx, utilizando servicos de nuvem, e geralmente a estrategia mais adequada, pois evita grandes desembolsos iniciais e distribui os custos de forma recorrente e previsivel.', true, 'Microsoft Learn - Modulo ''Describe cloud computing'' (Percurso: Describe cloud concepts, AZ-900)', 60),
  ('62000000-0000-4000-8000-000000000061', 'az-900', 'serverless-computing', 'single_choice', 'O que caracteriza a computacao sem servidor (serverless computing)?', 'easy', 'A computacao sem servidor (serverless) e um modelo em que o provedor de nuvem gerencia toda a infraestrutura subjacente, incluindo provisionamento e escalonamento de servidores, permitindo que o desenvolvedor foque apenas em escrever e executar o codigo da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 61),
  ('62000000-0000-4000-8000-000000000062', 'az-900', 'serverless-computing', 'single_choice', 'Qual e uma das principais vantagens do modelo de computacao sem servidor para desenvolvedores?', 'easy', 'Uma das principais vantagens do serverless computing e eliminar a necessidade de o desenvolvedor provisionar, configurar e gerenciar servidores, ja que o provedor de nuvem cuida dessa infraestrutura automaticamente, permitindo foco total na logica da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 62),
  ('62000000-0000-4000-8000-000000000063', 'az-900', 'serverless-computing', 'single_choice', 'Como normalmente e cobrado o uso de recursos em um modelo de computacao sem servidor?', 'easy', 'No modelo serverless, a cobranca geralmente e baseada na execucao real do codigo, considerando fatores como o tempo de execucao e a quantidade de recursos consumidos durante cada chamada da funcao, e nao em uma taxa fixa independente do uso.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 63),
  ('62000000-0000-4000-8000-000000000064', 'az-900', 'serverless-computing', 'single_choice', 'Uma empresa precisa processar imagens enviadas por usuarios apenas quando um upload ocorre, sem previsao de horarios fixos, podendo haver longos periodos sem nenhum upload. Qual modelo de computacao e mais adequado para essa funcao de processamento?', 'medium', 'O modelo serverless e ideal para funcoes acionadas por eventos esporadicos e imprevisiveis, como o processamento de imagens no momento do upload, pois os recursos sao utilizados e cobrados apenas durante a execucao real da funcao, sem custos durante periodos de inatividade.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 64),
  ('62000000-0000-4000-8000-000000000065', 'az-900', 'serverless-computing', 'single_choice', 'Uma equipe de desenvolvimento quer criar uma API que responde a poucas requisicoes por dia, mas ocasionalmente pode receber picos de milhares de requisicoes em minutos, sem previsao. Qual caracteristica do serverless computing atende diretamente a esse cenario?', 'medium', 'O escalonamento automatico e uma caracteristica central do serverless computing: o provedor de nuvem ajusta automaticamente a capacidade de execucao conforme o volume de requisicoes, sem necessidade de intervencao manual da equipe, atendendo tanto periodos de baixa quanto de alta demanda.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 65),
  ('62000000-0000-4000-8000-000000000066', 'az-900', 'serverless-computing', 'single_choice', 'Uma empresa deseja executar uma pequena rotina de validacao de dados que e acionada apenas quando um novo arquivo e adicionado a um servico de armazenamento na nuvem, sem qualquer previsao de frequencia. Qual abordagem, baseada em serverless computing, melhor atende a essa necessidade?', 'medium', 'Uma funcao serverless acionada por eventos, como a adicao de um novo arquivo em um servico de armazenamento, e a abordagem mais eficiente para rotinas esporadicas e imprevisiveis, pois executa a logica apenas quando o evento ocorre, sem custos durante a inatividade.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 66),
  ('62000000-0000-4000-8000-000000000067', 'az-900', 'serverless-computing', 'single_choice', 'Uma startup de tecnologia esta desenvolvendo um prototipo e quer minimizar custos operacionais enquanto testa a viabilidade do produto, evitando pagar por capacidade computacional ociosa durante os periodos sem uso. Qual modelo de computacao melhor atende a essa fase inicial?', 'medium', 'Para uma startup testando a viabilidade de um produto, o modelo serverless e geralmente o mais adequado, pois cobra apenas pela execucao real do codigo, evitando custos com capacidade ociosa durante os periodos sem uso, o que e ideal para uma fase inicial de testes.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 67),
  ('62000000-0000-4000-8000-000000000068', 'az-900', 'serverless-computing', 'single_choice', 'Comparando serverless computing com o uso de maquinas virtuais (IaaS) tradicionais, qual afirmacao esta correta em relacao ao gerenciamento de infraestrutura?', 'medium', 'No modelo serverless, o provedor de nuvem gerencia toda a infraestrutura, incluindo o escalonamento automatico, enquanto em maquinas virtuais tradicionais (IaaS) o cliente ainda e responsavel por gerenciar o sistema operacional e parte da configuracao do ambiente.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 68),
  ('62000000-0000-4000-8000-000000000069', 'az-900', 'serverless-computing', 'single_choice', 'Uma empresa esta avaliando se deve usar serverless computing ou maquinas virtuais tradicionais para uma aplicacao com carga de trabalho constante e previsivel, funcionando 24 horas por dia, com utilizacao estavel de recursos. Qual analise e mais adequada para essa decisao?', 'hard', 'Embora o serverless computing seja vantajoso para cargas de trabalho esporadicas e imprevisiveis, para cargas constantes e previsiveis, com utilizacao estavel 24 horas por dia, o custo proporcional do modelo serverless pode ser maior do que o de maquinas virtuais reservadas, tornando essencial uma analise comparativa de custos antes da decisao.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 69),
  ('62000000-0000-4000-8000-000000000070', 'az-900', 'serverless-computing', 'single_choice', 'Uma equipe de engenharia esta migrando uma arquitetura monolitica para um conjunto de pequenas funcoes independentes, cada uma acionada por eventos especificos, como upload de arquivos, mensagens em filas e requisicoes HTTP esporadicas. Qual abordagem de computacao melhor se alinha a essa nova arquitetura orientada a eventos?', 'hard', 'Para uma arquitetura orientada a eventos, composta por pequenas funcoes independentes acionadas por gatilhos especificos, o serverless computing e a abordagem mais adequada, pois cada funcao pode ser executada automaticamente apenas quando o evento correspondente ocorre, com escalonamento sob demanda.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 70),
  ('62000000-0000-4000-8000-000000000071', 'az-900', 'high-availability', 'single_choice', 'O que significa alta disponibilidade (high availability) em cloud computing?', 'easy', 'Alta disponibilidade refere-se a capacidade de um sistema permanecer operacional e acessivel pelo maior tempo possivel, minimizando interrupcoes e falhas, sendo geralmente medida por um percentual de tempo de atividade (uptime) ao longo de um periodo.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 71),
  ('62000000-0000-4000-8000-000000000072', 'az-900', 'high-availability', 'single_choice', 'Como a alta disponibilidade de um servico em nuvem costuma ser expressa contratualmente?', 'easy', 'A alta disponibilidade costuma ser expressa por meio de um Acordo de Nivel de Servico (SLA), documento em que o provedor de nuvem estabelece um percentual minimo garantido de tempo de atividade (uptime) para o servico contratado.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 72),
  ('62000000-0000-4000-8000-000000000073', 'az-900', 'high-availability', 'single_choice', 'Qual estrategia e comumente utilizada para aumentar a alta disponibilidade de uma aplicacao na nuvem?', 'easy', 'Uma estrategia comum para aumentar a alta disponibilidade e distribuir a aplicacao em multiplas instancias redundantes, frequentemente localizadas em diferentes zonas de disponibilidade ou regioes, reduzindo o risco de que uma unica falha interrompa todo o servico.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 73),
  ('62000000-0000-4000-8000-000000000074', 'az-900', 'high-availability', 'single_choice', 'Uma aplicacao de e-commerce sofre uma falha em um unico servidor durante um horario de grande movimento, mas os usuarios nao percebem qualquer interrupcao, pois o trafego e automaticamente redirecionado para outro servidor saudavel. Qual principio de alta disponibilidade esta sendo demonstrado nesse cenario?', 'medium', 'O cenario demonstra o principio de redundancia com failover automatico, em que multiplas instancias do servico existem simultaneamente e, ao detectar uma falha, o trafego e redirecionado automaticamente para uma instancia saudavel, mantendo a disponibilidade da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 74),
  ('62000000-0000-4000-8000-000000000075', 'az-900', 'high-availability', 'single_choice', 'Uma empresa de servicos financeiros precisa garantir que sua aplicacao de pagamentos permaneca acessivel mesmo durante uma falha completa em uma zona de disponibilidade especifica. Qual abordagem melhor garante esse nivel de alta disponibilidade?', 'medium', 'Distribuir a aplicacao entre multiplas zonas de disponibilidade dentro da mesma regiao e uma pratica recomendada para garantir alta disponibilidade, pois isola a aplicacao de falhas que afetem uma unica zona, mantendo o servico acessivel mesmo diante de uma interrupcao localizada.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 75),
  ('62000000-0000-4000-8000-000000000076', 'az-900', 'high-availability', 'single_choice', 'Uma equipe de operacoes percebe que, sempre que realiza uma atualizacao de software em producao, o servico fica temporariamente indisponivel para os usuarios. Qual pratica, alinhada aos principios de alta disponibilidade, poderia reduzir esse impacto?', 'medium', 'Adotar implantacoes graduais, atualizando um subconjunto de instancias por vez enquanto outras permanecem ativas atendendo aos usuarios, e uma pratica recomendada para reduzir ou eliminar a indisponibilidade durante atualizacoes, mantendo a alta disponibilidade do servico.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 76),
  ('62000000-0000-4000-8000-000000000077', 'az-900', 'high-availability', 'single_choice', 'Uma aplicacao critica de monitoramento de saude precisa estar disponivel 24 horas por dia, com o minimo de interrupcoes possivel, mesmo diante de falhas de hardware ou picos inesperados de trafego. Qual combinacao de praticas melhor contribui para atingir esse objetivo?', 'medium', 'Para uma aplicacao critica que exige disponibilidade continua, a combinacao de redundancia em multiplas instancias, monitoramento continuo de saude do sistema e failover automatico e essencial para minimizar interrupcoes diante de falhas de hardware ou picos inesperados de trafego.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 77),
  ('62000000-0000-4000-8000-000000000078', 'az-900', 'high-availability', 'single_choice', 'Comparando uma arquitetura com uma unica instancia de servidor e uma arquitetura com multiplas instancias redundantes, qual afirmacao sobre alta disponibilidade esta correta?', 'medium', 'Uma arquitetura com multiplas instancias redundantes tende a oferecer maior disponibilidade, pois, caso uma instancia falhe, as demais podem continuar atendendo as requisicoes, ao contrario de uma arquitetura com uma unica instancia, que representa um ponto unico de falha.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 78),
  ('62000000-0000-4000-8000-000000000079', 'az-900', 'high-availability', 'single_choice', 'Uma empresa avalia dois designs de arquitetura para sua aplicacao: o primeiro utiliza uma unica instancia em uma unica zona de disponibilidade; o segundo distribui a aplicacao em multiplas zonas de disponibilidade dentro da mesma regiao. Qual conclusao e mais precisa sobre a resiliencia desses dois designs diante de uma falha regional?', 'hard', 'Embora distribuir a aplicacao em multiplas zonas de disponibilidade aumente significativamente a resiliencia contra falhas localizadas, nenhum dos dois designs protege totalmente contra uma falha que afete a regiao inteira; para esse nivel de protecao, seria necessario considerar redundancia entre regioes diferentes.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 79),
  ('62000000-0000-4000-8000-000000000080', 'az-900', 'high-availability', 'single_choice', 'Uma empresa global precisa garantir que sua aplicacao permaneca disponivel mesmo diante de uma falha completa em uma regiao inteira do provedor de nuvem, incluindo desastres naturais que afetem um datacenter inteiro. Qual estrategia de arquitetura melhor atende a esse nivel extremo de exigencia de disponibilidade?', 'hard', 'Para proteger contra a falha completa de uma regiao inteira, incluindo desastres naturais, a estrategia mais adequada e implementar redundancia entre multiplas regioes geograficamente distantes, garantindo que a aplicacao continue operando mesmo que uma das regioes fique totalmente indisponivel.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 80),
  ('62000000-0000-4000-8000-000000000081', 'az-900', 'scalability', 'single_choice', 'O que significa escalabilidade (scalability) em cloud computing?', 'easy', 'Escalabilidade e a capacidade de um sistema aumentar ou diminuir sua capacidade de processamento, armazenamento ou outros recursos para atender as variacoes de demanda, seja por meio da adicao de recursos a uma instancia existente ou pela adicao de novas instancias.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 81),
  ('62000000-0000-4000-8000-000000000082', 'az-900', 'scalability', 'single_choice', 'O que e escalabilidade vertical (scale up) em cloud computing?', 'easy', 'Escalabilidade vertical (scale up) refere-se ao aumento da capacidade de uma unica instancia existente, como adicionar mais memoria, processamento ou armazenamento a um servidor, em vez de adicionar novas instancias separadas.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 82),
  ('62000000-0000-4000-8000-000000000083', 'az-900', 'scalability', 'single_choice', 'O que e escalabilidade horizontal (scale out) em cloud computing?', 'easy', 'Escalabilidade horizontal (scale out) refere-se a adicao de novas instancias identicas de um recurso, distribuindo a carga de trabalho entre multiplos servidores, o que e comum em arquiteturas de nuvem para lidar com aumentos de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 83),
  ('62000000-0000-4000-8000-000000000084', 'az-900', 'scalability', 'single_choice', 'Uma aplicacao web esta enfrentando lentidao porque um unico servidor nao consegue processar todas as requisicoes recebidas durante horarios de pico. A equipe decide adicionar mais servidores identicos para dividir a carga entre eles. Qual tipo de escalabilidade esta sendo aplicado nesse cenario?', 'medium', 'Ao adicionar mais servidores identicos para dividir a carga de trabalho entre eles, a equipe esta aplicando escalabilidade horizontal (scale out), uma abordagem comum para lidar com aumentos de demanda distribuindo o processamento entre multiplas instancias.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 84),
  ('62000000-0000-4000-8000-000000000085', 'az-900', 'scalability', 'single_choice', 'Uma empresa percebe que seu banco de dados esta enfrentando lentidao devido ao aumento no volume de consultas, mas decide resolver o problema aumentando a capacidade de processamento e memoria do servidor existente, em vez de adicionar novos servidores. Qual tipo de escalabilidade esta sendo aplicado?', 'medium', 'Ao aumentar a capacidade de processamento e memoria de um unico servidor existente, em vez de adicionar novos servidores, a empresa esta aplicando escalabilidade vertical (scale up), uma abordagem alternativa a escalabilidade horizontal para lidar com aumentos de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 85),
  ('62000000-0000-4000-8000-000000000086', 'az-900', 'scalability', 'single_choice', 'Uma equipe de TI precisa decidir entre aumentar a capacidade de um unico servidor de banco de dados (scale up) ou distribuir os dados entre multiplos servidores menores (scale out), sabendo que ha um limite maximo de capacidade que um unico servidor pode atingir. Qual consideracao e mais relevante para essa decisao?', 'medium', 'Uma consideracao central nessa decisao e avaliar os limites tecnicos de capacidade de uma unica maquina (escalabilidade vertical) frente a necessidade de crescimento futuro que pode ultrapassar esses limites, o que tornaria a escalabilidade horizontal necessaria a longo prazo.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 86),
  ('62000000-0000-4000-8000-000000000087', 'az-900', 'scalability', 'single_choice', 'Uma aplicacao de streaming de video precisa suportar um crescimento continuo no numero de usuarios ao longo dos proximos anos, sem um limite claro de quantos usuarios podera atingir. Qual abordagem de escalabilidade tende a oferecer maior capacidade de crescimento no longo prazo?', 'medium', 'Para suportar um crescimento continuo e sem limite claro, a escalabilidade horizontal tende a ser mais adequada no longo prazo, pois permite adicionar novas instancias conforme necessario, sem ficar restrita aos limites fisicos de capacidade de uma unica maquina.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 87),
  ('62000000-0000-4000-8000-000000000088', 'az-900', 'scalability', 'single_choice', 'Comparando escalabilidade vertical e escalabilidade horizontal, qual afirmacao esta correta em relacao aos limites de crescimento?', 'medium', 'A escalabilidade vertical e limitada pela capacidade maxima que uma unica maquina pode oferecer, como limites de processamento e memoria, enquanto a escalabilidade horizontal pode, em teoria, continuar adicionando novas instancias, oferecendo maior potencial de crescimento no longo prazo.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 88),
  ('62000000-0000-4000-8000-000000000089', 'az-900', 'scalability', 'single_choice', 'Uma empresa de tecnologia enfrenta um crescimento acelerado e imprevisivel no numero de usuarios, ultrapassando repetidamente a capacidade maxima de seu servidor principal, mesmo apos diversos upgrades de hardware. Qual conclusao e mais adequada sobre a estrategia de escalabilidade a ser adotada?', 'hard', 'Diante de um crescimento acelerado que ultrapassa repetidamente os limites da escalabilidade vertical, mesmo apos diversos upgrades, a estrategia mais adequada e migrar para escalabilidade horizontal, distribuindo a carga entre multiplas instancias, superando os limites fisicos de uma unica maquina.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 89),
  ('62000000-0000-4000-8000-000000000090', 'az-900', 'scalability', 'single_choice', 'Uma equipe de arquitetura esta projetando um novo sistema que precisa suportar tanto picos subitos de trafego quanto um crescimento constante ao longo dos anos, sem previsao exata do limite maximo de usuarios. Qual estrategia de escalabilidade melhor atende a essa combinacao de requisitos?', 'hard', 'Para atender tanto a picos subitos de trafego quanto ao crescimento constante ao longo dos anos, sem limite claro, a estrategia mais adequada e projetar o sistema com escalabilidade horizontal desde o inicio, permitindo adicionar novas instancias conforme necessario, sem ficar restrita aos limites de uma unica maquina.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 90),
  ('62000000-0000-4000-8000-000000000091', 'az-900', 'elasticity', 'single_choice', 'O que e elasticidade (elasticity) em cloud computing?', 'easy', 'Elasticidade e a capacidade de um sistema em nuvem ajustar automaticamente sua capacidade de recursos, aumentando durante periodos de alta demanda e reduzindo durante periodos de baixa demanda, geralmente sem intervencao manual, otimizando custos e desempenho.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 91),
  ('62000000-0000-4000-8000-000000000092', 'az-900', 'elasticity', 'single_choice', 'Qual e a principal diferenca entre elasticidade e escalabilidade em cloud computing?', 'easy', 'Embora relacionados, elasticidade e escalabilidade tem nuances diferentes: a elasticidade enfatiza o ajuste automatico e frequente da capacidade conforme a demanda muda em tempo real, enquanto a escalabilidade se refere a capacidade geral do sistema de crescer (ou diminuir) para suportar diferentes niveis de carga.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 92),
  ('62000000-0000-4000-8000-000000000093', 'az-900', 'elasticity', 'single_choice', 'Qual mecanismo e comumente utilizado para implementar elasticidade em servicos de nuvem?', 'easy', 'O escalonamento automatico (auto-scaling) e o mecanismo mais comum para implementar elasticidade, ajustando automaticamente a quantidade de recursos com base em metricas de uso predefinidas, como utilizacao de CPU ou numero de requisicoes, sem necessidade de intervencao manual.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 93),
  ('62000000-0000-4000-8000-000000000094', 'az-900', 'elasticity', 'single_choice', 'Uma plataforma de venda de ingressos online enfrenta picos extremos de acesso nos primeiros minutos apos a abertura das vendas de um show popular, retornando a niveis normais de trafego logo em seguida. Qual configuracao melhor aproveita o conceito de elasticidade para esse cenario?', 'medium', 'Configurar regras de escalonamento automatico que aumentem rapidamente a capacidade durante os picos e a reduzam logo depois e a abordagem que melhor aproveita o conceito de elasticidade, otimizando custos e desempenho para cenarios de picos extremos e breves de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 94),
  ('62000000-0000-4000-8000-000000000095', 'az-900', 'elasticity', 'single_choice', 'Uma aplicacao de delivery de comida enfrenta aumento de pedidos durante o horario de almoco e jantar, com queda significativa de trafego durante a madrugada. A equipe configura regras de auto-scaling baseadas no numero de requisicoes por minuto. Qual beneficio direto essa configuracao traz para a empresa?', 'medium', 'Ao configurar regras de auto-scaling baseadas em metricas como numero de requisicoes por minuto, a aplicacao otimiza custos, aumentando os recursos durante os horarios de pico (almoco e jantar) e reduzindo-os automaticamente durante periodos de baixo trafego, como a madrugada.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 95),
  ('62000000-0000-4000-8000-000000000096', 'az-900', 'elasticity', 'single_choice', 'Uma empresa configurou regras de escalonamento automatico para sua aplicacao, mas percebe que, mesmo durante picos de trafego, novos recursos demoram muito tempo para serem adicionados, causando lentidao para os usuarios nesse periodo. Qual ajuste poderia melhorar a resposta elastica do sistema?', 'medium', 'Ajustar os limites (thresholds) das metricas que disparam o escalonamento automatico, antecipando a adicao de recursos antes que o pico afete significativamente o desempenho, e uma pratica comum para melhorar a capacidade de resposta elastica do sistema diante de aumentos de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 96),
  ('62000000-0000-4000-8000-000000000097', 'az-900', 'elasticity', 'single_choice', 'Uma plataforma de streaming ao vivo transmite eventos esportivos ocasionais que geram picos massivos de audiencia por poucas horas, com trafego minimo no restante do tempo. Qual caracteristica da elasticidade e mais relevante para o sucesso tecnico e financeiro dessa plataforma?', 'medium', 'Para uma plataforma com picos massivos e esporadicos de audiencia, a caracteristica mais relevante da elasticidade e a capacidade de aumentar rapidamente os recursos durante o evento e reduzi-los automaticamente logo depois, evitando custos desnecessarios durante os longos periodos sem transmissoes.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 97),
  ('62000000-0000-4000-8000-000000000098', 'az-900', 'elasticity', 'single_choice', 'Comparando um sistema com capacidade fixa e um sistema com elasticidade automatica, qual afirmacao esta correta sobre o comportamento diante de uma queda repentina no trafego?', 'medium', 'Diante de uma queda repentina no trafego, um sistema com elasticidade automatica tende a reduzir os recursos utilizados, diminuindo os custos correspondentes, enquanto um sistema com capacidade fixa mantem a mesma quantidade de recursos e, consequentemente, os mesmos custos, independentemente da reducao de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 98),
  ('62000000-0000-4000-8000-000000000099', 'az-900', 'elasticity', 'single_choice', 'Uma empresa configurou elasticidade automatica para sua aplicacao, mas percebe que os custos mensais aumentaram significativamente, mesmo com o trafego permanecendo relativamente estavel ao longo do tempo. Qual analise e mais adequada para investigar essa situacao?', 'hard', 'Diante de um aumento significativo de custos com trafego relativamente estavel, a analise mais adequada e revisar as metricas e os limites configurados para o escalonamento automatico, pois configuracoes inadequadas podem causar adicao excessiva e desnecessaria de recursos, mesmo sem um aumento real de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 99),
  ('62000000-0000-4000-8000-000000000100', 'az-900', 'elasticity', 'single_choice', 'Uma empresa de tecnologia percebe que sua aplicacao enfrenta variacoes de trafego tanto previsiveis, como aumento diario no horario comercial, quanto imprevisiveis, como picos causados por campanhas de marketing virais. Qual estrategia melhor combina os conceitos de elasticidade e escalabilidade para atender a ambos os padroes de variacao?', 'hard', 'A estrategia mais adequada para atender tanto a variacoes previsiveis quanto a picos imprevisiveis de trafego e combinar uma arquitetura escalavel horizontalmente com regras de escalonamento automatico, permitindo que o sistema se ajuste dinamicamente a diferentes padroes de demanda, sejam eles esperados ou nao.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 100),
  ('62000000-0000-4000-8000-000000000101', 'az-900', 'reliability', 'single_choice', 'O que significa confiabilidade (reliability) em cloud computing?', 'easy', 'Confiabilidade refere-se a capacidade de um sistema se recuperar de falhas e continuar funcionando conforme o esperado ao longo do tempo, envolvendo praticas como redundancia, recuperacao de desastres e monitoramento continuo para garantir a continuidade do servico.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 101),
  ('62000000-0000-4000-8000-000000000102', 'az-900', 'reliability', 'single_choice', 'Qual pratica esta diretamente relacionada a melhoria da confiabilidade de um sistema em nuvem?', 'easy', 'A implementacao de planos de recuperacao de desastres e uma pratica fundamental para melhorar a confiabilidade de um sistema, garantindo que ele possa ser restaurado apos falhas graves, como desastres naturais ou falhas criticas de infraestrutura, minimizando a perda de dados e o tempo de inatividade.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 102),
  ('62000000-0000-4000-8000-000000000103', 'az-900', 'reliability', 'single_choice', 'Como a confiabilidade de um sistema em nuvem geralmente e avaliada ao longo do tempo?', 'easy', 'A confiabilidade de um sistema em nuvem e frequentemente avaliada por meio de metricas como o tempo medio entre falhas (MTBF) e o tempo medio de recuperacao apos uma interrupcao (MTTR), que ajudam a medir a robustez e a capacidade de recuperacao do sistema ao longo do tempo.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 103),
  ('62000000-0000-4000-8000-000000000104', 'az-900', 'reliability', 'single_choice', 'Uma aplicacao critica de uma seguradora sofreu uma falha grave que resultou em perda de dados recentes, pois nao havia backups regulares configurados. Qual medida deveria ter sido implementada previamente para melhorar a confiabilidade e evitar essa perda de dados?', 'medium', 'A implementacao de uma rotina de backups regulares e testados e uma medida essencial para melhorar a confiabilidade de sistemas criticos, garantindo que os dados possam ser restaurados em caso de falhas graves, evitando perdas significativas como a ocorrida na seguradora.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 104),
  ('62000000-0000-4000-8000-000000000105', 'az-900', 'reliability', 'single_choice', 'Uma empresa de logistica implementou monitoramento continuo de sua aplicacao de rastreamento de entregas, configurando alertas automaticos para a equipe tecnica sempre que uma metrica critica ultrapassa um limite pre-definido. Qual beneficio direto essa pratica traz para a confiabilidade do sistema?', 'medium', 'O monitoramento continuo com alertas automaticos permite que a equipe tecnica identifique e corrija problemas rapidamente, antes que eles evoluam para interrupcoes graves no servico, contribuindo diretamente para a melhoria da confiabilidade do sistema ao longo do tempo.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 105),
  ('62000000-0000-4000-8000-000000000106', 'az-900', 'reliability', 'single_choice', 'Uma equipe de engenharia realiza testes periodicos simulando falhas em componentes criticos do sistema, como a queda repentina de um servidor, para verificar se os mecanismos de recuperacao funcionam corretamente. Qual conceito essa pratica ajuda a validar diretamente?', 'medium', 'Testes periodicos que simulam falhas em componentes criticos, como a queda de um servidor, ajudam a validar diretamente a confiabilidade do sistema, verificando se os mecanismos de recuperacao, como failover automatico e restauracao de dados, funcionam corretamente quando necessario.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 106),
  ('62000000-0000-4000-8000-000000000107', 'az-900', 'reliability', 'single_choice', 'Uma aplicacao de e-commerce sofreu diversas interrupcoes ao longo do ultimo ano devido a falhas nao detectadas rapidamente, resultando em longos periodos de indisponibilidade ate que a equipe percebesse o problema manualmente. Qual mudanca de pratica melhoraria diretamente a confiabilidade do sistema nesse cenario?', 'medium', 'Implementar monitoramento automatizado com alertas em tempo real reduz significativamente o tempo entre a ocorrencia de uma falha e sua deteccao pela equipe tecnica, permitindo uma resposta mais rapida e, consequentemente, melhorando a confiabilidade geral do sistema.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 107),
  ('62000000-0000-4000-8000-000000000108', 'az-900', 'reliability', 'single_choice', 'Comparando um sistema sem qualquer mecanismo de recuperacao automatica e um sistema com failover automatico configurado, qual afirmacao sobre confiabilidade esta correta?', 'medium', 'Um sistema com failover automatico configurado tende a ser mais confiavel, pois consegue se recuperar rapidamente de falhas, redirecionando o trafego para componentes saudaveis sem depender de intervencao manual imediata, reduzindo o tempo de indisponibilidade.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 108),
  ('62000000-0000-4000-8000-000000000109', 'az-900', 'reliability', 'single_choice', 'Uma empresa esta comparando dois sistemas: o primeiro possui alta disponibilidade, com multiplas instancias redundantes, mas nunca passou por testes de recuperacao de desastres; o segundo possui menos redundancia, mas realiza testes regulares de recuperacao de desastres e possui planos bem documentados. Qual conclusao e mais adequada sobre a confiabilidade real desses sistemas?', 'hard', 'Ter redundancia, como multiplas instancias, e importante, mas nao garante confiabilidade completa por si so; testes regulares de recuperacao de desastres sao essenciais para validar que os mecanismos de recuperacao realmente funcionam na pratica, quando uma falha grave de fato ocorre.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 109),
  ('62000000-0000-4000-8000-000000000110', 'az-900', 'reliability', 'single_choice', 'Uma equipe de TI esta definindo a estrategia de confiabilidade para um novo sistema critico de saude, que nao pode ficar indisponivel por mais do que poucos minutos em caso de falha grave. Qual combinacao de praticas melhor garante esse nivel elevado de confiabilidade?', 'hard', 'Para um sistema critico de saude com exigencia de minima indisponibilidade, a combinacao de redundancia entre multiplas instancias e regioes, monitoramento continuo com alertas automaticos e testes regulares de recuperacao de desastres e essencial para garantir um alto nivel de confiabilidade.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 110),
  ('62000000-0000-4000-8000-000000000111', 'az-900', 'predictability', 'single_choice', 'O que significa previsibilidade (predictability) em cloud computing?', 'easy', 'Previsibilidade em cloud computing refere-se a capacidade de prever o comportamento de desempenho e os custos de um sistema, permitindo que as organizacoes planejem adequadamente seus recursos e orcamentos, mesmo diante de variacoes de demanda.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 111),
  ('62000000-0000-4000-8000-000000000112', 'az-900', 'predictability', 'single_choice', 'A previsibilidade em cloud computing geralmente e dividida em quais duas dimensoes principais?', 'easy', 'A previsibilidade em cloud computing e geralmente dividida em duas dimensoes principais: previsibilidade de desempenho, relacionada a consistencia do comportamento do sistema sob diferentes cargas, e previsibilidade de custos, relacionada a capacidade de estimar e planejar os gastos com os servicos utilizados.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 112),
  ('62000000-0000-4000-8000-000000000113', 'az-900', 'predictability', 'single_choice', 'Qual ferramenta e comumente utilizada em plataformas de nuvem para ajudar organizacoes a estimar e prever custos futuros de utilizacao de recursos?', 'easy', 'Provedores de nuvem geralmente oferecem calculadoras de precos e ferramentas de orcamento e alertas de custo, que ajudam as organizacoes a estimar previamente e monitorar continuamente os gastos com os servicos utilizados, contribuindo para a previsibilidade financeira.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 113),
  ('62000000-0000-4000-8000-000000000114', 'az-900', 'predictability', 'single_choice', 'Uma empresa configurou alertas de orcamento em sua conta de nuvem, que notificam automaticamente a equipe financeira sempre que os gastos mensais se aproximam de um limite predefinido. Qual dimensao da previsibilidade essa pratica ajuda a reforcar diretamente?', 'medium', 'Configurar alertas de orcamento que notificam a equipe financeira sempre que os gastos se aproximam de um limite predefinido e uma pratica que reforca diretamente a previsibilidade de custos, ajudando a monitorar e controlar os gastos com servicos de nuvem antes que ultrapassem o planejado.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 114),
  ('62000000-0000-4000-8000-000000000115', 'az-900', 'predictability', 'single_choice', 'Uma empresa de tecnologia relata que o desempenho de sua aplicacao varia significativamente e de forma imprevisivel, mesmo sob cargas de trabalho semelhantes, dificultando o planejamento de capacidade. Qual pratica poderia ajudar a melhorar a previsibilidade de desempenho nesse cenario?', 'medium', 'Realizar testes de carga consistentes e monitorar metricas de desempenho ao longo do tempo permite identificar e corrigir gargalos que causam variacoes inesperadas, contribuindo diretamente para melhorar a previsibilidade de desempenho da aplicacao sob diferentes condicoes de carga.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 115),
  ('62000000-0000-4000-8000-000000000116', 'az-900', 'predictability', 'single_choice', 'Uma organizacao sem fins lucrativos precisa apresentar ao seu conselho diretor uma previsao confiavel dos custos de TI para o proximo ano, ja que o orcamento anual e fixo e aprovado com antecedencia. Qual pratica, relacionada a previsibilidade de custos, melhor auxilia nessa apresentacao?', 'medium', 'Utilizar ferramentas de estimativa e calculadoras de precos do provedor de nuvem, combinadas com a analise do historico de consumo de recursos, e a pratica mais adequada para projetar os custos futuros com maior precisao, auxiliando a organizacao a apresentar uma previsao confiavel ao conselho diretor.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 116),
  ('62000000-0000-4000-8000-000000000117', 'az-900', 'predictability', 'single_choice', 'Uma equipe de operacoes percebe que, embora o custo mensal de sua infraestrutura em nuvem seja relativamente estavel, o desempenho da aplicacao varia bastante durante certos horarios, causando lentidao inesperada para os usuarios. Qual dimensao da previsibilidade esta sendo prejudicada nesse cenario?', 'medium', 'O cenario descrito, em que o desempenho da aplicacao varia de forma inesperada e inconsistente durante certos horarios, mesmo com custo mensal estavel, indica um problema relacionado a previsibilidade de desempenho, e nao a previsibilidade de custos ou a outros conceitos como elasticidade ou responsabilidade compartilhada.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 117),
  ('62000000-0000-4000-8000-000000000118', 'az-900', 'predictability', 'single_choice', 'Comparando previsibilidade de desempenho e previsibilidade de custos, qual afirmacao esta correta sobre esses dois conceitos?', 'medium', 'Embora relacionados, os dois conceitos tem focos diferentes: previsibilidade de desempenho trata da consistencia do comportamento tecnico do sistema sob diferentes cargas, enquanto previsibilidade de custos trata da capacidade de estimar e controlar os gastos financeiros associados ao uso dos servicos de nuvem.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 118),
  ('62000000-0000-4000-8000-000000000119', 'az-900', 'predictability', 'single_choice', 'Uma empresa percebe que, embora seus custos mensais de nuvem estejam dentro do orcamento planejado, o desempenho de sua aplicacao se torna imprevisivel durante periodos de manutencao nao anunciada pelo provedor. Qual analise e mais adequada para lidar com essa situacao, considerando o conceito de previsibilidade?', 'hard', 'Como previsibilidade de custos e previsibilidade de desempenho sao dimensoes distintas, a empresa deve revisar os Acordos de Nivel de Servico (SLAs) do provedor quanto a janelas de manutencao e comunicacao previa, alem de considerar arquiteturas mais resilientes a essas variacoes, em vez de assumir que uma dimensao garante automaticamente a outra.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 119),
  ('62000000-0000-4000-8000-000000000120', 'az-900', 'predictability', 'single_choice', 'Uma equipe de arquitetura esta projetando um sistema financeiro que precisa apresentar tanto custos previsiveis para fins de orcamento anual quanto desempenho consistente durante todo o horario comercial, mesmo diante de variacoes moderadas de carga. Qual estrategia combinada melhor atende a essas duas dimensoes de previsibilidade simultaneamente?', 'hard', 'Para atender simultaneamente as exigencias de previsibilidade de custos e de desempenho, a estrategia mais adequada combina ferramentas de estimativa e alertas de orcamento, que garantem previsibilidade financeira, com testes de carga regulares e monitoramento continuo de desempenho, permitindo ajustes na arquitetura conforme necessario.', true, 'Microsoft Learn - Modulo ''Describe the benefits of using cloud services'' (Percurso: Describe cloud concepts, AZ-900)', 120);

insert into imported_question_option_batch1_seed (
  id, question_id, option_text, is_correct, explanation, display_order
)
values
  ('73000000-0000-4000-8000-000000000001', '62000000-0000-4000-8000-000000000001', 'A entrega de recursos de computacao, como servidores, armazenamento e banco de dados, sob demanda pela internet, com pagamento conforme o uso.', true, 'Correta. Essa e a definicao central de cloud computing segundo a Microsoft: recursos sob demanda, entregues pela internet, com cobranca baseada no consumo.', 1),
  ('73000000-0000-4000-8000-000000000002', '62000000-0000-4000-8000-000000000001', 'A compra antecipada de servidores fisicos para serem instalados no datacenter da empresa.', false, 'Incorreta. Comprar servidores fisicos antecipadamente e caracteristica do modelo on-premises, o oposto do consumo sob demanda da nuvem.', 2),
  ('73000000-0000-4000-8000-000000000003', '62000000-0000-4000-8000-000000000001', 'A contratacao de uma equipe terceirizada para administrar servidores locais.', false, 'Incorreta. Terceirizar a administracao de servidores locais nao elimina a necessidade de infraestrutura propria, o que difere do conceito de cloud computing.', 3),
  ('73000000-0000-4000-8000-000000000004', '62000000-0000-4000-8000-000000000001', 'A instalacao de softwares diretamente nos computadores dos usuarios finais.', false, 'Incorreta. Instalar softwares localmente nos dispositivos dos usuarios nao envolve entrega de recursos via internet, nao caracterizando cloud computing.', 4),
  ('73000000-0000-4000-8000-000000000005', '62000000-0000-4000-8000-000000000002', 'Necessidade de aprovacao manual de um tecnico para cada novo recurso provisionado.', false, 'Incorreta. Exigir aprovacao manual contraria o principio de autoatendimento sob demanda, que elimina a necessidade de intervencao humana.', 1),
  ('73000000-0000-4000-8000-000000000006', '62000000-0000-4000-8000-000000000002', 'Autoatendimento sob demanda, permitindo que o usuario provisione recursos computacionais sem intervencao humana do provedor.', true, 'Correta. O autoatendimento sob demanda permite provisionar recursos automaticamente, sem depender de um atendente do provedor.', 2),
  ('73000000-0000-4000-8000-000000000007', '62000000-0000-4000-8000-000000000002', 'Obrigatoriedade de contratos de longo prazo para acesso aos recursos.', false, 'Incorreta. A cloud computing normalmente oferece flexibilidade contratual, incluindo modelos sem compromisso de longo prazo.', 3),
  ('73000000-0000-4000-8000-000000000008', '62000000-0000-4000-8000-000000000002', 'Limitacao do acesso aos recursos apenas a partir de uma unica localizacao fisica.', false, 'Incorreta. Um dos beneficios da nuvem e justamente o acesso amplo pela rede, de multiplos dispositivos e localizacoes.', 4),
  ('73000000-0000-4000-8000-000000000009', '62000000-0000-4000-8000-000000000003', 'Os recursos so podem ser acessados dentro da rede interna da empresa.', false, 'Incorreta. Restringir o acesso a rede interna vai contra o principio de acesso amplo, que e justamente pela internet, de qualquer lugar.', 1),
  ('73000000-0000-4000-8000-000000000010', '62000000-0000-4000-8000-000000000003', 'O acesso e restrito a computadores com um sistema operacional especifico.', false, 'Incorreta. O acesso amplo a rede nao depende de um sistema operacional especifico; funciona em diversas plataformas.', 2),
  ('73000000-0000-4000-8000-000000000011', '62000000-0000-4000-8000-000000000003', 'Os recursos ficam disponiveis pela rede e podem ser acessados por diversos tipos de dispositivo, como notebooks, tablets e smartphones.', true, 'Correta. O acesso amplo a rede permite conectar-se aos servicos de nuvem por meio de diferentes dispositivos e locais, via internet.', 3),
  ('73000000-0000-4000-8000-000000000012', '62000000-0000-4000-8000-000000000003', 'E necessario instalar um hardware especial fornecido pelo provedor para acessar os servicos.', false, 'Incorreta. Nao e necessario hardware especial do provedor; o acesso ocorre por meio de navegadores ou aplicativos padrao.', 4),
  ('73000000-0000-4000-8000-000000000013', '62000000-0000-4000-8000-000000000004', 'Comprar um novo datacenter proprio com servidores redundantes.', false, 'Incorreta. Construir um datacenter proprio aumenta o investimento inicial e a responsabilidade de manutencao, o oposto do que a empresa deseja.', 1),
  ('73000000-0000-4000-8000-000000000014', '62000000-0000-4000-8000-000000000004', 'Contratar um servico de manutencao anual para os servidores ja existentes na empresa.', false, 'Incorreta. Manter e apenas dar suporte a infraestrutura existente nao elimina os custos de manutencao continua do hardware fisico.', 2),
  ('73000000-0000-4000-8000-000000000015', '62000000-0000-4000-8000-000000000004', 'Expandir o datacenter atual adicionando mais racks de servidores fisicos.', false, 'Incorreta. Expandir o datacenter fisico aumenta ainda mais o investimento em hardware, nao reduzindo custos iniciais.', 3),
  ('73000000-0000-4000-8000-000000000016', '62000000-0000-4000-8000-000000000004', 'Migrar as cargas de trabalho para a cloud computing, utilizando recursos sob demanda do provedor.', true, 'Correta. A cloud computing elimina a necessidade de comprar e manter hardware fisico, pois os recursos sao fornecidos sob demanda pelo provedor.', 4),
  ('73000000-0000-4000-8000-000000000017', '62000000-0000-4000-8000-000000000005', 'O modelo de consumo sob demanda, que permite pagar apenas pelos recursos efetivamente utilizados, sem investimento inicial.', true, 'Correta. O consumo sob demanda evita investimento antecipado e permite ajustar os recursos conforme a necessidade real da startup.', 1),
  ('73000000-0000-4000-8000-000000000018', '62000000-0000-4000-8000-000000000005', 'A obrigatoriedade de assinar contratos fixos de capacidade computacional por varios anos.', false, 'Incorreta. Contratos fixos de longo prazo contradizem a flexibilidade que a startup precisa diante de um crescimento imprevisivel.', 2),
  ('73000000-0000-4000-8000-000000000019', '62000000-0000-4000-8000-000000000005', 'A necessidade de prever com exatidao a demanda futura antes de contratar qualquer recurso.', false, 'Incorreta. Um dos beneficios da nuvem e justamente nao exigir previsao exata da demanda, pois os recursos podem ser ajustados dinamicamente.', 3),
  ('73000000-0000-4000-8000-000000000020', '62000000-0000-4000-8000-000000000005', 'A exigencia de adquirir servidores fisicos proporcionalmente ao crescimento esperado.', false, 'Incorreta. Comprar servidores fisicos proporcionalmente ao crescimento mantem o investimento antecipado que a startup quer evitar.', 4),
  ('73000000-0000-4000-8000-000000000021', '62000000-0000-4000-8000-000000000006', 'Elasticidade automatica de recursos computacionais.', false, 'Incorreta. Elasticidade se refere ao ajuste automatico da capacidade de recursos, nao ao acesso remoto de usuarios a partir de diferentes locais.', 1),
  ('73000000-0000-4000-8000-000000000022', '62000000-0000-4000-8000-000000000006', 'Modelo de responsabilidade compartilhada entre cliente e provedor.', false, 'Incorreta. O modelo de responsabilidade compartilhada trata da divisao de tarefas de seguranca entre cliente e provedor, nao do acesso remoto.', 2),
  ('73000000-0000-4000-8000-000000000023', '62000000-0000-4000-8000-000000000006', 'Acesso amplo a rede, permitindo conectar-se aos servicos pela internet a partir de diversos dispositivos e locais.', true, 'Correta. O acesso amplo a rede permite que o funcionario use os sistemas corporativos de qualquer lugar e dispositivo com conexao a internet.', 3),
  ('73000000-0000-4000-8000-000000000024', '62000000-0000-4000-8000-000000000006', 'Modelo de capital fixo (CapEx) aplicado a infraestrutura de TI.', false, 'Incorreta. CapEx refere-se ao modelo de investimento em ativos fisicos, sem relacao direta com o acesso remoto a sistemas.', 4),
  ('73000000-0000-4000-8000-000000000025', '62000000-0000-4000-8000-000000000007', 'Investimento fixo em capital (CapEx) para garantir capacidade maxima o ano todo.', false, 'Incorreta. Investir em capital fixo (CapEx) para manter capacidade maxima o ano todo gera desperdicio de recursos fora dos periodos de pico.', 1),
  ('73000000-0000-4000-8000-000000000026', '62000000-0000-4000-8000-000000000007', 'Modelo de consumo baseado no uso (pay-as-you-go), que cobra de acordo com os recursos efetivamente utilizados.', true, 'Correta. O modelo pay-as-you-go permite pagar apenas pelo que e consumido, ajustando os custos aos picos e vales de demanda.', 2),
  ('73000000-0000-4000-8000-000000000027', '62000000-0000-4000-8000-000000000007', 'Contratacao de um datacenter proprio dimensionado para o pico maximo esperado.', false, 'Incorreta. Um datacenter proprio dimensionado para o pico maximo ficaria subutilizado na maior parte do ano, gerando custo desnecessario.', 3),
  ('73000000-0000-4000-8000-000000000028', '62000000-0000-4000-8000-000000000007', 'Uso exclusivo de hardware dedicado sem possibilidade de ajuste de capacidade.', false, 'Incorreta. Hardware dedicado sem possibilidade de ajuste nao permite adaptar a capacidade aos periodos de baixa demanda.', 4),
  ('73000000-0000-4000-8000-000000000029', '62000000-0000-4000-8000-000000000008', 'Ambos os modelos levam, em media, o mesmo tempo para provisionar novos servidores.', false, 'Incorreta. Os tempos de provisionamento sao significativamente diferentes entre os dois modelos, nao sendo equivalentes.', 1),
  ('73000000-0000-4000-8000-000000000030', '62000000-0000-4000-8000-000000000008', 'Na infraestrutura on-premises, novos recursos ficam disponiveis em poucos minutos, assim como na nuvem.', false, 'Incorreta. No modelo on-premises, o provisionamento de novos recursos depende da aquisicao e instalacao de hardware fisico, o que nao ocorre em poucos minutos.', 2),
  ('73000000-0000-4000-8000-000000000031', '62000000-0000-4000-8000-000000000008', 'Na cloud computing, e necessario aguardar a compra e instalacao fisica de novos servidores antes de utiliza-los.', false, 'Incorreta. Na cloud computing nao e necessario comprar e instalar hardware fisico; os recursos sao provisionados virtualmente e rapidamente.', 3),
  ('73000000-0000-4000-8000-000000000032', '62000000-0000-4000-8000-000000000008', 'Na cloud computing, novos recursos podem ser provisionados em minutos, enquanto no modelo on-premises esse processo costuma levar semanas ou meses, devido a compra e instalacao de hardware.', true, 'Correta. A cloud computing permite provisionamento rapido de recursos virtuais, enquanto o modelo on-premises depende de processos de compra e instalacao fisica mais demorados.', 4),
  ('73000000-0000-4000-8000-000000000033', '62000000-0000-4000-8000-000000000009', 'A cloud computing pode ser adotada de forma seletiva, migrando as cargas de trabalho que se beneficiam de elasticidade e acesso remoto, mantendo o sistema legado on-premises se ele nao se adaptar bem a nuvem.', true, 'Correta. A adocao de cloud computing pode ser gradual e seletiva, migrando o que faz sentido e mantendo sistemas legados on-premises quando necessario.', 1),
  ('73000000-0000-4000-8000-000000000034', '62000000-0000-4000-8000-000000000009', 'A empresa deve necessariamente migrar 100% de sua infraestrutura para a nuvem, pois a cloud computing sempre substitui totalmente o modelo on-premises.', false, 'Incorreta. Nao existe obrigatoriedade de migracao total; empresas podem adotar modelos hibridos conforme suas necessidades especificas.', 2),
  ('73000000-0000-4000-8000-000000000035', '62000000-0000-4000-8000-000000000009', 'Sistemas legados com requisitos de hardware especificos nunca podem coexistir com ambientes de cloud computing em nenhuma hipotese.', false, 'Incorreta. Sistemas legados podem, em muitos casos, coexistir com ambientes de nuvem por meio de arquiteturas hibridas.', 3),
  ('73000000-0000-4000-8000-000000000036', '62000000-0000-4000-8000-000000000009', 'A adocao de cloud computing e incompativel com qualquer empresa que possua sistemas legados, independentemente de suas caracteristicas.', false, 'Incorreta. A existencia de sistemas legados nao torna a adocao de cloud computing impossivel; ela apenas exige uma analise cuidadosa de quais cargas migrar.', 4),
  ('73000000-0000-4000-8000-000000000037', '62000000-0000-4000-8000-000000000010', 'O tipo de teclado utilizado pelos funcionarios que acessam a aplicacao.', false, 'Incorreta. O tipo de teclado utilizado pelos funcionarios nao tem relacao com a decisao sobre migracao de infraestrutura para a nuvem.', 1),
  ('73000000-0000-4000-8000-000000000038', '62000000-0000-4000-8000-000000000010', 'A cor da interface grafica da aplicacao interna.', false, 'Incorreta. A cor da interface grafica e um detalhe estetico e nao influencia a analise de custo-beneficio de infraestrutura.', 2),
  ('73000000-0000-4000-8000-000000000039', '62000000-0000-4000-8000-000000000010', 'O custo-beneficio entre manter um servidor fisico dedicado versus pagar apenas pelo consumo sob demanda de um recurso de baixa utilizacao.', true, 'Correta. Avaliar o custo-beneficio entre manter hardware dedicado e pagar por consumo sob demanda e essencial para decidir sobre a migracao para a nuvem.', 3),
  ('73000000-0000-4000-8000-000000000040', '62000000-0000-4000-8000-000000000010', 'O numero de monitores conectados aos computadores dos funcionarios.', false, 'Incorreta. O numero de monitores conectados aos computadores dos funcionarios nao e um fator relevante para a decisao de infraestrutura.', 4),
  ('73000000-0000-4000-8000-000000000041', '62000000-0000-4000-8000-000000000011', 'Um modelo em que o provedor de nuvem e o unico responsavel por toda a seguranca, incluindo dados do cliente.', false, 'Incorreta. O provedor nao e responsavel por tudo; dados, identidades e certas configuracoes permanecem sob responsabilidade do cliente.', 1),
  ('73000000-0000-4000-8000-000000000042', '62000000-0000-4000-8000-000000000011', 'Um modelo que define quais responsabilidades de seguranca e conformidade cabem ao provedor de nuvem e quais cabem ao cliente.', true, 'Correta. O modelo de responsabilidade compartilhada divide claramente as obrigacoes de seguranca entre provedor e cliente.', 2),
  ('73000000-0000-4000-8000-000000000043', '62000000-0000-4000-8000-000000000011', 'Um modelo em que o cliente e o unico responsavel por toda a infraestrutura fisica do datacenter.', false, 'Incorreta. O cliente nao e responsavel pela infraestrutura fisica; essa e uma responsabilidade do provedor de nuvem.', 3),
  ('73000000-0000-4000-8000-000000000044', '62000000-0000-4000-8000-000000000011', 'Um modelo aplicavel apenas a servicos de armazenamento de arquivos na nuvem.', false, 'Incorreta. O modelo de responsabilidade compartilhada se aplica a todos os tipos de servicos de nuvem, nao apenas ao armazenamento de arquivos.', 4),
  ('73000000-0000-4000-8000-000000000045', '62000000-0000-4000-8000-000000000012', 'O provedor de nuvem.', true, 'Correta. O provedor de nuvem mantem total controle e responsabilidade sobre a seguranca fisica de seus datacenters.', 1),
  ('73000000-0000-4000-8000-000000000046', '62000000-0000-4000-8000-000000000012', 'O cliente que contrata o servico.', false, 'Incorreta. O cliente nao tem acesso fisico aos datacenters do provedor, portanto nao pode ser responsavel por essa camada.', 2),
  ('73000000-0000-4000-8000-000000000047', '62000000-0000-4000-8000-000000000012', 'Uma empresa terceirizada contratada separadamente pelo cliente.', false, 'Incorreta. Nao e necessario contratar uma empresa terceirizada separada; a seguranca fisica ja e responsabilidade do provedor.', 3),
  ('73000000-0000-4000-8000-000000000048', '62000000-0000-4000-8000-000000000012', 'Um orgao regulador governamental externo ao provedor.', false, 'Incorreta. Orgaos reguladores podem fiscalizar, mas nao sao responsaveis operacionalmente pela seguranca fisica dos datacenters.', 4),
  ('73000000-0000-4000-8000-000000000049', '62000000-0000-4000-8000-000000000013', 'A manutencao fisica dos servidores do datacenter.', false, 'Incorreta. A manutencao fisica dos servidores e responsabilidade exclusiva do provedor de nuvem em qualquer modelo de servico.', 1),
  ('73000000-0000-4000-8000-000000000050', '62000000-0000-4000-8000-000000000013', 'A climatizacao e o fornecimento de energia do datacenter.', false, 'Incorreta. Climatizacao e energia do datacenter fazem parte da infraestrutura fisica, sob responsabilidade do provedor.', 2),
  ('73000000-0000-4000-8000-000000000051', '62000000-0000-4000-8000-000000000013', 'A seguranca da rede fisica entre os datacenters do provedor.', false, 'Incorreta. A seguranca da rede fisica entre os datacenters e gerenciada internamente pelo provedor de nuvem.', 3),
  ('73000000-0000-4000-8000-000000000052', '62000000-0000-4000-8000-000000000013', 'A classificacao e a protecao dos dados armazenados e das identidades de acesso.', true, 'Correta. A protecao dos dados e das identidades de acesso e sempre responsabilidade do cliente, independentemente do servico contratado.', 4),
  ('73000000-0000-4000-8000-000000000053', '62000000-0000-4000-8000-000000000014', 'Do provedor de nuvem, pois ele controla toda a infraestrutura de hardware.', false, 'Incorreta. Em IaaS, o provedor cuida da infraestrutura fisica, mas nao do sistema operacional das maquinas virtuais do cliente.', 1),
  ('73000000-0000-4000-8000-000000000054', '62000000-0000-4000-8000-000000000014', 'De um terceiro contratado exclusivamente para esse fim, obrigatoriamente.', false, 'Incorreta. Nao ha obrigatoriedade de contratar terceiros; a responsabilidade pelo sistema operacional e do proprio cliente.', 2),
  ('73000000-0000-4000-8000-000000000055', '62000000-0000-4000-8000-000000000014', 'Do cliente, ja que em IaaS o sistema operacional da maquina virtual esta sob sua responsabilidade.', true, 'Correta. Em IaaS, o cliente e responsavel por gerenciar e atualizar o sistema operacional das maquinas virtuais que utiliza.', 3),
  ('73000000-0000-4000-8000-000000000056', '62000000-0000-4000-8000-000000000014', 'Nao e necessario aplicar atualizacoes de seguranca em ambientes de IaaS.', false, 'Incorreta. Atualizacoes de seguranca sao essenciais em qualquer ambiente, incluindo IaaS, para proteger contra vulnerabilidades.', 4),
  ('73000000-0000-4000-8000-000000000057', '62000000-0000-4000-8000-000000000015', 'A manutencao dos servidores fisicos que hospedam o servico de e-mail.', false, 'Incorreta. A manutencao dos servidores fisicos e sempre responsabilidade do provedor de nuvem, mesmo em modelos SaaS.', 1),
  ('73000000-0000-4000-8000-000000000058', '62000000-0000-4000-8000-000000000015', 'A gestao de identidades dos usuarios e a definicao de politicas de acesso as contas de e-mail.', true, 'Correta. Mesmo em SaaS, o cliente e responsavel por gerenciar identidades de usuarios e definir politicas de acesso as contas.', 2),
  ('73000000-0000-4000-8000-000000000059', '62000000-0000-4000-8000-000000000015', 'A atualizacao do sistema operacional dos servidores do provedor.', false, 'Incorreta. A atualizacao do sistema operacional dos servidores do provedor cabe exclusivamente ao provedor em modelos SaaS.', 3),
  ('73000000-0000-4000-8000-000000000060', '62000000-0000-4000-8000-000000000015', 'A instalacao de patches de seguranca na infraestrutura de rede do datacenter.', false, 'Incorreta. A seguranca da infraestrutura de rede do datacenter e gerenciada pelo provedor, nao pelo cliente, em SaaS.', 4),
  ('73000000-0000-4000-8000-000000000061', '62000000-0000-4000-8000-000000000016', 'O cliente e responsavel por gerenciar o hardware fisico do provedor mesmo em PaaS.', false, 'Incorreta. O cliente nunca gerencia o hardware fisico do provedor, independentemente do modelo de servico.', 1),
  ('73000000-0000-4000-8000-000000000062', '62000000-0000-4000-8000-000000000016', 'O provedor e responsavel por proteger os dados de aplicacao inseridos pelo cliente no sistema.', false, 'Incorreta. A protecao dos dados de aplicacao inseridos pelo cliente continua sendo responsabilidade do proprio cliente, mesmo em PaaS.', 2),
  ('73000000-0000-4000-8000-000000000063', '62000000-0000-4000-8000-000000000016', 'Nenhuma responsabilidade de seguranca recai sobre o cliente quando se utiliza PaaS.', false, 'Incorreta. O cliente sempre mantem alguma responsabilidade de seguranca, como a protecao de dados e da aplicacao, mesmo em PaaS.', 3),
  ('73000000-0000-4000-8000-000000000064', '62000000-0000-4000-8000-000000000016', 'O provedor gerencia o runtime, middleware e sistema operacional, enquanto o cliente permanece responsavel pelos dados e pela aplicacao que desenvolve.', true, 'Correta. Em PaaS, o provedor cuida do runtime e da plataforma, enquanto o cliente e responsavel pelos dados e pela aplicacao desenvolvida.', 4),
  ('73000000-0000-4000-8000-000000000065', '62000000-0000-4000-8000-000000000017', 'A parcela de responsabilidade do provedor aumenta, ja que ele passa a gerenciar mais camadas, como sistema operacional e aplicacao.', true, 'Correta. Em SaaS, o provedor gerencia praticamente toda a pilha, aumentando sua parcela de responsabilidade em comparacao a IaaS.', 1),
  ('73000000-0000-4000-8000-000000000066', '62000000-0000-4000-8000-000000000017', 'A parcela de responsabilidade do cliente aumenta proporcionalmente ao migrar para SaaS.', false, 'Incorreta. A responsabilidade do cliente tende a diminuir, nao aumentar, ao migrar de IaaS para SaaS.', 2),
  ('73000000-0000-4000-8000-000000000067', '62000000-0000-4000-8000-000000000017', 'A divisao de responsabilidades permanece exatamente igual entre IaaS e SaaS, sem nenhuma alteracao.', false, 'Incorreta. A divisao de responsabilidades muda significativamente entre IaaS e SaaS, nao permanecendo igual.', 3),
  ('73000000-0000-4000-8000-000000000068', '62000000-0000-4000-8000-000000000017', 'O cliente passa a ser o unico responsavel por toda a pilha de tecnologia apos a migracao.', false, 'Incorreta. Mesmo em SaaS, o provedor continua responsavel pela maior parte da infraestrutura e da aplicacao.', 4),
  ('73000000-0000-4000-8000-000000000069', '62000000-0000-4000-8000-000000000018', 'Em todos os tres modelos, a gestao do sistema operacional e sempre do cliente.', false, 'Incorreta. A gestao do sistema operacional varia conforme o modelo de servico; nao e sempre do cliente.', 1),
  ('73000000-0000-4000-8000-000000000070', '62000000-0000-4000-8000-000000000018', 'Em todos os tres modelos, a gestao do sistema operacional e sempre do provedor.', false, 'Incorreta. Em IaaS, o cliente e responsavel pelo sistema operacional das maquinas virtuais, nao o provedor.', 2),
  ('73000000-0000-4000-8000-000000000071', '62000000-0000-4000-8000-000000000018', 'Em IaaS, o cliente gerencia o sistema operacional; ja em PaaS e SaaS, essa responsabilidade e do provedor.', true, 'Correta. Em IaaS o cliente gerencia o sistema operacional, enquanto em PaaS e SaaS essa tarefa e do provedor.', 3),
  ('73000000-0000-4000-8000-000000000072', '62000000-0000-4000-8000-000000000018', 'Em PaaS, o cliente gerencia o sistema operacional; em IaaS e SaaS, essa responsabilidade e do provedor.', false, 'Incorreta. Essa e a divisao invertida; em PaaS o provedor gerencia o sistema operacional, nao o cliente.', 4),
  ('73000000-0000-4000-8000-000000000073', '62000000-0000-4000-8000-000000000019', 'O provedor de nuvem, pois ele e sempre o unico responsavel por qualquer incidente de seguranca, independente da causa.', false, 'Incorreta. O provedor nao e responsavel por falhas relacionadas a gestao de identidades e senhas dos usuarios do cliente.', 1),
  ('73000000-0000-4000-8000-000000000074', '62000000-0000-4000-8000-000000000019', 'A empresa cliente, pois a gestao de identidades e das politicas de senha dos usuarios e responsabilidade do cliente, mesmo em SaaS.', true, 'Correta. A gestao de identidades e politicas de senha e sempre responsabilidade do cliente, independentemente do modelo de servico contratado.', 2),
  ('73000000-0000-4000-8000-000000000075', '62000000-0000-4000-8000-000000000019', 'Nenhuma das partes, ja que incidentes de seguranca em SaaS nunca podem ser atribuidos a falhas humanas.', false, 'Incorreta. Incidentes causados por falhas humanas, como senhas fracas, podem e devem ser atribuidos a responsabilidades especificas dentro do modelo compartilhado.', 3),
  ('73000000-0000-4000-8000-000000000076', '62000000-0000-4000-8000-000000000019', 'Exclusivamente um fornecedor terceiro de antivirus, mesmo que nao tenha relacao contratual com o servico utilizado.', false, 'Incorreta. Um fornecedor terceiro sem relacao contratual com o servico nao tem qualquer responsabilidade sobre esse incidente.', 4),
  ('73000000-0000-4000-8000-000000000077', '62000000-0000-4000-8000-000000000020', 'IaaS, pois o cliente mantem controle total sobre o sistema operacional e a infraestrutura.', false, 'Incorreta. Em IaaS, o cliente mantem mais responsabilidades, incluindo o sistema operacional, o que aumenta sua carga operacional de seguranca.', 1),
  ('73000000-0000-4000-8000-000000000078', '62000000-0000-4000-8000-000000000020', 'Uma combinacao apenas de servidores on-premises com backup em fitas fisicas.', false, 'Incorreta. Servidores on-premises com backup fisico mantem toda a responsabilidade de seguranca com o proprio cliente, o oposto do que se busca.', 2),
  ('73000000-0000-4000-8000-000000000079', '62000000-0000-4000-8000-000000000020', 'PaaS, mas apenas quando combinado obrigatoriamente com hardware dedicado do cliente.', false, 'Incorreta. PaaS nao exige hardware dedicado do cliente, e essa combinacao nao reduz a carga de seguranca da forma descrita.', 3),
  ('73000000-0000-4000-8000-000000000080', '62000000-0000-4000-8000-000000000020', 'SaaS, pois o provedor gerencia praticamente toda a pilha tecnologica, restando ao cliente principalmente a gestao de dados e identidades.', true, 'Correta. O modelo SaaS concentra a maior parte da responsabilidade de seguranca no provedor, reduzindo a carga operacional do cliente.', 4),
  ('73000000-0000-4000-8000-000000000081', '62000000-0000-4000-8000-000000000021', 'Os recursos de computacao sao fornecidos por um provedor terceirizado e compartilhados entre multiplos clientes pela internet.', true, 'Correta. Na nuvem publica, o provedor terceirizado disponibiliza recursos compartilhados entre varios clientes via internet.', 1),
  ('73000000-0000-4000-8000-000000000082', '62000000-0000-4000-8000-000000000021', 'Os recursos ficam localizados exclusivamente no datacenter interno de uma unica empresa.', false, 'Incorreta. Recursos localizados exclusivamente no datacenter interno de uma empresa caracterizam a nuvem privada, nao a publica.', 2),
  ('73000000-0000-4000-8000-000000000083', '62000000-0000-4000-8000-000000000021', 'Os recursos sao acessiveis apenas por meio de uma rede privada isolada, sem conexao a internet.', false, 'Incorreta. A nuvem publica e acessada pela internet, e nao restrita a uma rede privada isolada.', 3),
  ('73000000-0000-4000-8000-000000000084', '62000000-0000-4000-8000-000000000021', 'Os recursos sao de propriedade exclusiva do cliente e mantidos fisicamente por ele.', false, 'Incorreta. Na nuvem publica, os recursos pertencem ao provedor, nao ao cliente que os utiliza.', 4),
  ('73000000-0000-4000-8000-000000000085', '62000000-0000-4000-8000-000000000022', 'Um ambiente de nuvem obrigatoriamente compartilhado entre multiplas organizacoes nao relacionadas.', false, 'Incorreta. A nuvem privada e exclusiva de uma unica organizacao, e nao compartilhada entre multiplas organizacoes nao relacionadas.', 1),
  ('73000000-0000-4000-8000-000000000086', '62000000-0000-4000-8000-000000000022', 'Um ambiente de computacao em nuvem dedicado exclusivamente a uma unica organizacao, seja hospedado internamente ou por um provedor terceirizado.', true, 'Correta. A nuvem privada oferece recursos dedicados a uma unica organizacao, com maior controle e isolamento.', 2),
  ('73000000-0000-4000-8000-000000000087', '62000000-0000-4000-8000-000000000022', 'Um ambiente de nuvem que so pode ser acessado sem qualquer tipo de autenticacao.', false, 'Incorreta. Ambientes de nuvem privada exigem autenticacao e controles de acesso, assim como outros modelos.', 3),
  ('73000000-0000-4000-8000-000000000088', '62000000-0000-4000-8000-000000000022', 'Um ambiente que combina obrigatoriamente recursos publicos e privados de diferentes provedores.', false, 'Incorreta. A combinacao de recursos publicos e privados caracteriza a nuvem hibrida, nao a privada.', 4),
  ('73000000-0000-4000-8000-000000000089', '62000000-0000-4000-8000-000000000023', 'Um ambiente que utiliza exclusivamente recursos de um unico datacenter privado.', false, 'Incorreta. Utilizar exclusivamente um datacenter privado caracteriza a nuvem privada, nao a hibrida.', 1),
  ('73000000-0000-4000-8000-000000000090', '62000000-0000-4000-8000-000000000023', 'Um ambiente que utiliza exclusivamente recursos de multiplos provedores publicos, sem infraestrutura propria.', false, 'Incorreta. Utilizar exclusivamente provedores publicos, sem qualquer infraestrutura propria, caracteriza a nuvem publica, nao a hibrida.', 2),
  ('73000000-0000-4000-8000-000000000091', '62000000-0000-4000-8000-000000000023', 'Um ambiente que combina recursos de nuvem publica e privada (ou infraestrutura on-premises), permitindo que dados e aplicacoes se movam entre eles.', true, 'Correta. A nuvem hibrida combina recursos publicos e privados, permitindo flexibilidade na movimentacao de dados e aplicacoes.', 3),
  ('73000000-0000-4000-8000-000000000092', '62000000-0000-4000-8000-000000000023', 'Um ambiente restrito exclusivamente a aplicacoes moveis, sem suporte a servidores.', false, 'Incorreta. A nuvem hibrida nao e restrita a aplicacoes moveis; ela abrange diversos tipos de cargas de trabalho.', 4),
  ('73000000-0000-4000-8000-000000000093', '62000000-0000-4000-8000-000000000024', 'Nuvem publica, pois e o modelo mais barato disponivel no mercado.', false, 'Incorreta. O custo nao e o principal criterio nesse cenario; a exigencia e isolamento e controle total sobre a infraestrutura.', 1),
  ('73000000-0000-4000-8000-000000000094', '62000000-0000-4000-8000-000000000024', 'Nuvem comunitaria compartilhada entre diversas instituicoes financeiras concorrentes.', false, 'Incorreta. Compartilhar infraestrutura entre instituicoes concorrentes nao atende a exigencia de isolamento total dos dados.', 2),
  ('73000000-0000-4000-8000-000000000095', '62000000-0000-4000-8000-000000000024', 'Qualquer modelo de nuvem, ja que exigencias regulatorias nao influenciam essa escolha.', false, 'Incorreta. Exigencias regulatorias influenciam diretamente a escolha do modelo de nuvem mais adequado para o cenario.', 3),
  ('73000000-0000-4000-8000-000000000096', '62000000-0000-4000-8000-000000000024', 'Nuvem privada, pois oferece um ambiente dedicado e maior controle sobre a infraestrutura, atendendo as exigencias regulatorias de isolamento.', true, 'Correta. A nuvem privada oferece isolamento e controle dedicado, atendendo as exigencias regulatorias de instituicoes financeiras.', 4),
  ('73000000-0000-4000-8000-000000000097', '62000000-0000-4000-8000-000000000025', 'Nuvem hibrida, combinando infraestrutura on-premises com recursos de nuvem publica conforme a demanda.', true, 'Correta. A combinacao de infraestrutura on-premises com nuvem publica, usada sob demanda, caracteriza o modelo hibrido.', 1),
  ('73000000-0000-4000-8000-000000000098', '62000000-0000-4000-8000-000000000025', 'Nuvem privada pura, sem qualquer conexao com provedores publicos.', false, 'Incorreta. Nuvem privada pura nao envolveria o uso de recursos de um provedor publico durante picos de trafego.', 2),
  ('73000000-0000-4000-8000-000000000099', '62000000-0000-4000-8000-000000000025', 'Nuvem publica pura, sem qualquer infraestrutura on-premises envolvida.', false, 'Incorreta. Nuvem publica pura nao envolveria a manutencao de servidores on-premises pela empresa.', 3),
  ('73000000-0000-4000-8000-000000000100', '62000000-0000-4000-8000-000000000025', 'Um modelo que nao existe dentro das categorias de implantacao de cloud computing.', false, 'Incorreta. O cenario descrito corresponde exatamente ao modelo de nuvem hibrida, uma categoria reconhecida de implantacao.', 4),
  ('73000000-0000-4000-8000-000000000101', '62000000-0000-4000-8000-000000000026', 'Nuvem privada, pois o portal exige isolamento total de qualquer outro usuario externo.', false, 'Incorreta. Nao ha, no cenario descrito, exigencia de isolamento total que justifique optar necessariamente pela nuvem privada.', 1),
  ('73000000-0000-4000-8000-000000000102', '62000000-0000-4000-8000-000000000026', 'Nenhum modelo de nuvem e adequado para portais governamentais de acesso publico.', false, 'Incorreta. Diversos portais governamentais utilizam cloud computing publica com sucesso para atender ao publico em geral.', 2),
  ('73000000-0000-4000-8000-000000000103', '62000000-0000-4000-8000-000000000026', 'Nuvem publica, pois oferece escalabilidade para lidar com grandes variacoes de acesso e nao ha exigencia de isolamento de infraestrutura.', true, 'Correta. A nuvem publica oferece a escalabilidade necessaria para lidar com grandes variacoes de acesso, sem exigencia de isolamento de infraestrutura.', 3),
  ('73000000-0000-4000-8000-000000000104', '62000000-0000-4000-8000-000000000026', 'Nuvem hibrida obrigatoriamente combinada com um segundo provedor publico redundante.', false, 'Incorreta. Nao ha necessidade obrigatoria de combinar dois provedores publicos redundantes para esse cenario especifico.', 4),
  ('73000000-0000-4000-8000-000000000105', '62000000-0000-4000-8000-000000000027', 'Nuvem publica pura para armazenar tanto os registros medicos sensiveis quanto as aplicacoes de analise.', false, 'Incorreta. Armazenar registros medicos sensiveis em nuvem publica pura pode nao atender as exigencias de controle e conformidade necessarias.', 1),
  ('73000000-0000-4000-8000-000000000106', '62000000-0000-4000-8000-000000000027', 'Nuvem hibrida, mantendo os registros medicos sensiveis em ambiente privado e utilizando a nuvem publica para as aplicacoes de analise nao sensiveis.', true, 'Correta. A nuvem hibrida permite combinar um ambiente privado controlado para dados sensiveis com a nuvem publica para aplicacoes nao sensiveis.', 2),
  ('73000000-0000-4000-8000-000000000107', '62000000-0000-4000-8000-000000000027', 'Nuvem privada pura, incluindo as aplicacoes de analise de dados nao sensiveis.', false, 'Incorreta. Manter as aplicacoes de analise em nuvem privada pura pode gerar custos e limitacoes desnecessarias para uma carga de trabalho nao sensivel.', 3),
  ('73000000-0000-4000-8000-000000000108', '62000000-0000-4000-8000-000000000027', 'Um modelo sem conexao entre os ambientes, exigindo duplicacao manual de todos os dados.', false, 'Incorreta. Modelos de nuvem hibrida geralmente permitem integracao entre ambientes, sem exigir duplicacao manual constante de dados.', 4),
  ('73000000-0000-4000-8000-000000000109', '62000000-0000-4000-8000-000000000028', 'A nuvem publica sempre oferece mais controle sobre a infraestrutura fisica do que a nuvem privada.', false, 'Incorreta. E a nuvem privada, e nao a publica, que geralmente oferece maior controle sobre a infraestrutura fisica.', 1),
  ('73000000-0000-4000-8000-000000000110', '62000000-0000-4000-8000-000000000028', 'Ambos os modelos oferecem exatamente o mesmo nivel de controle sobre a infraestrutura fisica.', false, 'Incorreta. O nivel de controle sobre a infraestrutura varia significativamente entre os dois modelos, nao sendo equivalente.', 2),
  ('73000000-0000-4000-8000-000000000111', '62000000-0000-4000-8000-000000000028', 'A nuvem privada nunca permite qualquer nivel de personalizacao de infraestrutura.', false, 'Incorreta. A nuvem privada permite maior personalizacao de infraestrutura justamente por ser dedicada a uma unica organizacao.', 3),
  ('73000000-0000-4000-8000-000000000112', '62000000-0000-4000-8000-000000000028', 'A nuvem privada geralmente oferece maior controle sobre a infraestrutura, enquanto a nuvem publica tem parte desse controle gerenciado pelo provedor terceirizado.', true, 'Correta. A nuvem privada oferece maior controle dedicado, enquanto na nuvem publica parte do controle e do provedor terceirizado.', 4),
  ('73000000-0000-4000-8000-000000000113', '62000000-0000-4000-8000-000000000029', 'Trata-se de uma estrategia de nuvem hibrida orientada por requisitos regulatorios, combinando isolamento onde necessario com flexibilidade e custo-beneficio onde possivel.', true, 'Correta. A combinacao estrategica de ambientes privados e publicos, conforme exigencias regulatorias, caracteriza uma abordagem de nuvem hibrida.', 1),
  ('73000000-0000-4000-8000-000000000114', '62000000-0000-4000-8000-000000000029', 'Essa estrategia e invalida, pois uma empresa nunca pode combinar diferentes modelos de nuvem em operacoes internacionais.', false, 'Incorreta. Combinar diferentes modelos de nuvem em operacoes internacionais e uma pratica comum e valida, especialmente por questoes regulatorias.', 2),
  ('73000000-0000-4000-8000-000000000115', '62000000-0000-4000-8000-000000000029', 'Essa abordagem representa exclusivamente um modelo de nuvem publica, ja que parte das cargas de trabalho esta na nuvem publica.', false, 'Incorreta. A existencia de um ambiente privado para dados sensiveis descarta a classificacao como nuvem publica pura.', 3),
  ('73000000-0000-4000-8000-000000000116', '62000000-0000-4000-8000-000000000029', 'Essa abordagem representa exclusivamente um modelo de nuvem privada, ja que parte dos dados esta isolada localmente.', false, 'Incorreta. A existencia de cargas de trabalho em nuvem publica descarta a classificacao como nuvem privada pura.', 4),
  ('73000000-0000-4000-8000-000000000117', '62000000-0000-4000-8000-000000000030', 'Nuvem privada, pois oferece isolamento total independentemente da ausencia de exigencias regulatorias.', false, 'Incorreta. Sem exigencias regulatorias de isolamento, o isolamento total da nuvem privada nao e um requisito essencial para esse cenario.', 1),
  ('73000000-0000-4000-8000-000000000118', '62000000-0000-4000-8000-000000000030', 'Manter toda a infraestrutura on-premises, mesmo diante de demanda extremamente variavel.', false, 'Incorreta. Manter toda a infraestrutura on-premises dificultaria lidar com demanda extremamente variavel e imprevisivel de forma economica.', 2),
  ('73000000-0000-4000-8000-000000000119', '62000000-0000-4000-8000-000000000030', 'Nuvem publica, pois oferece escalabilidade elastica e custo-beneficio adequados para demanda variavel sem exigencia de isolamento.', true, 'Correta. A nuvem publica oferece a escalabilidade elastica e o custo-beneficio necessarios para atender a demanda variavel do servico de streaming.', 3),
  ('73000000-0000-4000-8000-000000000120', '62000000-0000-4000-8000-000000000030', 'Um ambiente sem conexao a internet, dedicado exclusivamente ao streaming interno da empresa.', false, 'Incorreta. Um servico de streaming direcionado ao publico externo nao pode funcionar em um ambiente sem conexao a internet.', 4),
  ('73000000-0000-4000-8000-000000000121', '62000000-0000-4000-8000-000000000031', 'A cor da interface do painel de administracao do provedor.', false, 'Incorreta. Aspectos esteticos da interface nao influenciam a decisao estrategica sobre o modelo de implantacao de nuvem.', 1),
  ('73000000-0000-4000-8000-000000000122', '62000000-0000-4000-8000-000000000031', 'Os requisitos de seguranca, conformidade regulatoria e controle sobre a infraestrutura da organizacao.', true, 'Correta. Seguranca, conformidade e controle sobre a infraestrutura sao fatores centrais na escolha do modelo de nuvem.', 2),
  ('73000000-0000-4000-8000-000000000123', '62000000-0000-4000-8000-000000000031', 'O numero de funcionarios que trabalham no departamento de marketing.', false, 'Incorreta. O numero de funcionarios do marketing nao e um criterio tecnico relevante para essa decisao de infraestrutura.', 3),
  ('73000000-0000-4000-8000-000000000124', '62000000-0000-4000-8000-000000000031', 'A quantidade de impressoras disponiveis no escritorio da empresa.', false, 'Incorreta. A quantidade de impressoras do escritorio nao tem relacao com a escolha do modelo de implantacao de nuvem.', 4),
  ('73000000-0000-4000-8000-000000000125', '62000000-0000-4000-8000-000000000032', 'Nuvem publica.', true, 'Correta. A nuvem publica costuma oferecer o menor custo inicial e e adequada quando nao ha exigencia de infraestrutura exclusiva.', 1),
  ('73000000-0000-4000-8000-000000000126', '62000000-0000-4000-8000-000000000032', 'Nuvem privada.', false, 'Incorreta. A nuvem privada geralmente envolve custos maiores devido a infraestrutura dedicada, o que nao e prioridade nesse cenario.', 2),
  ('73000000-0000-4000-8000-000000000127', '62000000-0000-4000-8000-000000000032', 'Infraestrutura totalmente on-premises.', false, 'Incorreta. Manter infraestrutura totalmente on-premises normalmente exige maior investimento inicial em hardware.', 3),
  ('73000000-0000-4000-8000-000000000128', '62000000-0000-4000-8000-000000000032', 'Um datacenter fisico exclusivo construido do zero.', false, 'Incorreta. Construir um datacenter exclusivo do zero e uma das opcoes mais caras e demoradas, contrariando a prioridade de baixo custo.', 4),
  ('73000000-0000-4000-8000-000000000129', '62000000-0000-4000-8000-000000000033', 'A quantidade de cores disponiveis no logotipo da empresa.', false, 'Incorreta. Aspectos de identidade visual da empresa nao tem relacao com a escolha do modelo de implantacao de nuvem.', 1),
  ('73000000-0000-4000-8000-000000000130', '62000000-0000-4000-8000-000000000033', 'O numero de feriados nacionais no pais onde a empresa esta sediada.', false, 'Incorreta. O numero de feriados nacionais nao e um criterio tecnico relevante para decisoes de infraestrutura de TI.', 2),
  ('73000000-0000-4000-8000-000000000131', '62000000-0000-4000-8000-000000000033', 'A preferencia pessoal de um unico funcionario do departamento de TI, sem embasamento tecnico.', false, 'Incorreta. Decisoes de infraestrutura devem ser baseadas em criterios tecnicos e de negocio, nao apenas em preferencias pessoais sem embasamento.', 3),
  ('73000000-0000-4000-8000-000000000132', '62000000-0000-4000-8000-000000000033', 'O nivel de controle necessario sobre a infraestrutura e os requisitos de conformidade regulatoria do setor da empresa.', true, 'Correta. O nivel de controle necessario e os requisitos regulatorios sao criterios tecnicos fundamentais para essa escolha.', 4),
  ('73000000-0000-4000-8000-000000000133', '62000000-0000-4000-8000-000000000034', 'Nuvem publica pura, incluindo os dados de transacoes financeiras sujeitos a auditoria.', false, 'Incorreta. Dados de transacoes sujeitos a rigida auditoria geralmente exigem maior controle do que a nuvem publica pura oferece.', 1),
  ('73000000-0000-4000-8000-000000000134', '62000000-0000-4000-8000-000000000034', 'Infraestrutura totalmente on-premises, sem qualquer uso de recursos em nuvem.', false, 'Incorreta. Manter tudo on-premises nao aproveitaria a escalabilidade e o custo-beneficio da nuvem publica para o site institucional.', 2),
  ('73000000-0000-4000-8000-000000000135', '62000000-0000-4000-8000-000000000034', 'Nuvem hibrida, mantendo os dados de transacoes em ambiente privado controlado e o site institucional em nuvem publica.', true, 'Correta. A nuvem hibrida permite equilibrar controle rigoroso para dados criticos com escalabilidade para cargas de trabalho menos sensiveis.', 3),
  ('73000000-0000-4000-8000-000000000136', '62000000-0000-4000-8000-000000000034', 'Nuvem privada pura, incluindo o site institucional de baixa criticidade.', false, 'Incorreta. Manter o site institucional em nuvem privada pura pode gerar custos desnecessarios para uma carga de trabalho de baixa criticidade.', 4),
  ('73000000-0000-4000-8000-000000000137', '62000000-0000-4000-8000-000000000035', 'Nuvem privada, com contrato de longo prazo firmado antes mesmo da validacao da ideia.', false, 'Incorreta. Firmar contrato de longo prazo antes da validacao da ideia contraria a necessidade de flexibilidade e baixo compromisso inicial.', 1),
  ('73000000-0000-4000-8000-000000000138', '62000000-0000-4000-8000-000000000035', 'Nuvem publica, que permite testar rapidamente com baixo investimento inicial e sem compromissos de longo prazo.', true, 'Correta. A nuvem publica permite testar rapidamente e com baixo investimento inicial, sem compromissos de longo prazo.', 2),
  ('73000000-0000-4000-8000-000000000139', '62000000-0000-4000-8000-000000000035', 'Construcao de um datacenter fisico dedicado exclusivamente ao teste do novo produto.', false, 'Incorreta. Construir um datacenter fisico dedicado e um investimento alto e demorado, inadequado para uma fase inicial de testes.', 3),
  ('73000000-0000-4000-8000-000000000140', '62000000-0000-4000-8000-000000000035', 'Aguardar a aprovacao orcamentaria para infraestrutura fisica antes de iniciar qualquer teste.', false, 'Incorreta. Aguardar aprovacao orcamentaria para infraestrutura fisica atrasaria desnecessariamente a validacao rapida da ideia.', 4),
  ('73000000-0000-4000-8000-000000000141', '62000000-0000-4000-8000-000000000036', 'Nuvem publica pura, incluindo os sistemas de controle de producao com exigencia de baixa latencia.', false, 'Incorreta. Sistemas de controle de producao com exigencia de baixissima latencia e operacao offline nao sao adequados para nuvem publica pura.', 1),
  ('73000000-0000-4000-8000-000000000142', '62000000-0000-4000-8000-000000000036', 'Nenhum modelo de nuvem pode ser utilizado nesse cenario devido a exigencia de baixa latencia.', false, 'Incorreta. E possivel combinar sistemas locais com uso parcial de nuvem publica por meio de uma abordagem hibrida.', 2),
  ('73000000-0000-4000-8000-000000000143', '62000000-0000-4000-8000-000000000036', 'Nuvem privada pura, incluindo a analise de dados historicos que poderia se beneficiar da escalabilidade publica.', false, 'Incorreta. Manter a analise de dados historicos em nuvem privada pura pode gerar custos desnecessarios quando a nuvem publica ofereceria mais escalabilidade.', 3),
  ('73000000-0000-4000-8000-000000000144', '62000000-0000-4000-8000-000000000036', 'Nuvem hibrida, mantendo os sistemas de controle de producao localmente e utilizando a nuvem publica para analise de dados historicos.', true, 'Correta. A nuvem hibrida permite manter sistemas criticos localmente e aproveitar a nuvem publica para cargas de trabalho menos sensiveis, como analise de dados.', 4),
  ('73000000-0000-4000-8000-000000000145', '62000000-0000-4000-8000-000000000037', 'Nuvem publica, que costuma oferecer menor custo inicial e escalabilidade sem exigencia de infraestrutura dedicada.', true, 'Correta. A nuvem publica costuma ser a opcao mais economica para organizacoes com orcamento limitado e sem exigencias regulatorias especificas.', 1),
  ('73000000-0000-4000-8000-000000000146', '62000000-0000-4000-8000-000000000037', 'Nuvem privada, com investimento inicial elevado em infraestrutura dedicada.', false, 'Incorreta. A nuvem privada normalmente exige maior investimento inicial, o que nao e ideal para uma organizacao com orcamento limitado.', 2),
  ('73000000-0000-4000-8000-000000000147', '62000000-0000-4000-8000-000000000037', 'Construcao de um datacenter fisico proprio, mesmo com orcamento limitado.', false, 'Incorreta. Construir um datacenter fisico proprio exige investimento significativo, inadequado para uma organizacao com recursos limitados.', 3),
  ('73000000-0000-4000-8000-000000000148', '62000000-0000-4000-8000-000000000037', 'Contratacao exclusiva de servidores fisicos dedicados hospedados por um unico fornecedor local.', false, 'Incorreta. Servidores fisicos dedicados de um unico fornecedor local tendem a ter custo mais alto e menos flexibilidade do que a nuvem publica.', 4),
  ('73000000-0000-4000-8000-000000000149', '62000000-0000-4000-8000-000000000038', 'A nuvem privada e sempre mais barata que a nuvem publica, em qualquer cenario.', false, 'Incorreta. Nao e correto afirmar que a nuvem privada e sempre mais barata; isso depende do cenario e da escala de uso.', 1),
  ('73000000-0000-4000-8000-000000000150', '62000000-0000-4000-8000-000000000038', 'A nuvem publica e sempre mais cara que a nuvem privada, independentemente do uso.', false, 'Incorreta. Nao e correto afirmar que a nuvem publica e sempre mais cara; em muitos casos ela e mais economica.', 2),
  ('73000000-0000-4000-8000-000000000151', '62000000-0000-4000-8000-000000000038', 'A nuvem publica tende a ter menor custo inicial, enquanto a nuvem privada normalmente envolve maior investimento em infraestrutura dedicada.', true, 'Correta. A nuvem publica costuma ter menor custo inicial, enquanto a nuvem privada envolve maior investimento em infraestrutura dedicada.', 3),
  ('73000000-0000-4000-8000-000000000152', '62000000-0000-4000-8000-000000000038', 'O custo e sempre identico entre nuvem publica e privada, independentemente do modelo escolhido.', false, 'Incorreta. Os custos variam significativamente entre os modelos, dependendo de fatores como escala, uso e requisitos de dedicacao.', 4),
  ('73000000-0000-4000-8000-000000000153', '62000000-0000-4000-8000-000000000039', 'A nuvem publica deve ser escolhida automaticamente, pois sempre atende a qualquer exigencia regulatoria de qualquer setor.', false, 'Incorreta. Nem toda exigencia regulatoria de todos os setores e automaticamente atendida pela nuvem publica; isso depende de cada caso especifico.', 1),
  ('73000000-0000-4000-8000-000000000154', '62000000-0000-4000-8000-000000000039', 'A empresa deve avaliar se a nuvem publica, isoladamente, atende integralmente as exigencias regulatorias de dados de saude; caso nao atenda plenamente, um modelo hibrido pode oferecer o controle adicional necessario.', true, 'Correta. A analise deve considerar se a nuvem publica atende plenamente as exigencias regulatorias, recorrendo a um modelo hibrido quando necessario maior controle.', 2),
  ('73000000-0000-4000-8000-000000000155', '62000000-0000-4000-8000-000000000039', 'A decisao deve ser tomada exclusivamente com base no preco mais baixo, ignorando qualquer exigencia regulatoria do setor de saude.', false, 'Incorreta. Ignorar exigencias regulatorias do setor de saude ao decidir apenas pelo preco pode gerar serios riscos de conformidade.', 3),
  ('73000000-0000-4000-8000-000000000156', '62000000-0000-4000-8000-000000000039', 'Prontuarios eletronicos de pacientes nunca podem ser armazenados em qualquer ambiente de nuvem, independentemente do modelo escolhido.', false, 'Incorreta. Prontuarios eletronicos podem ser armazenados em ambientes de nuvem, desde que atendidos os requisitos regulatorios e de seguranca aplicaveis.', 4),
  ('73000000-0000-4000-8000-000000000157', '62000000-0000-4000-8000-000000000040', 'Migrar imediatamente e por completo para a nuvem publica, incluindo os sistemas legados incompativeis, sem qualquer planejamento gradual.', false, 'Incorreta. Migrar imediatamente sistemas legados incompativeis, sem planejamento, pode causar falhas operacionais e riscos significativos.', 1),
  ('73000000-0000-4000-8000-000000000158', '62000000-0000-4000-8000-000000000040', 'Manter toda a infraestrutura on-premises indefinidamente, ignorando qualquer possibilidade de modernizacao futura.', false, 'Incorreta. Manter toda a infraestrutura on-premises indefinidamente impede a empresa de aproveitar os beneficios de escalabilidade da nuvem.', 2),
  ('73000000-0000-4000-8000-000000000159', '62000000-0000-4000-8000-000000000040', 'Adotar exclusivamente a nuvem privada para absolutamente todos os sistemas, incluindo aqueles sem exigencia de isolamento especifico.', false, 'Incorreta. Adotar nuvem privada para todos os sistemas, mesmo os sem exigencia de isolamento, pode gerar custos desnecessarios.', 3),
  ('73000000-0000-4000-8000-000000000160', '62000000-0000-4000-8000-000000000040', 'Adotar uma estrategia de nuvem hibrida, migrando gradualmente as cargas de trabalho compativeis para a nuvem publica, mantendo sistemas legados on-premises ate que possam ser modernizados.', true, 'Correta. A estrategia hibrida permite modernizacao gradual, migrando o que e compativel e mantendo sistemas legados ate que possam ser adaptados.', 4),
  ('73000000-0000-4000-8000-000000000161', '62000000-0000-4000-8000-000000000041', 'O cliente paga apenas pelos recursos computacionais que efetivamente utiliza, sem necessidade de investimento inicial em hardware.', true, 'Correta. No modelo de consumo baseado no uso, o pagamento e proporcional aos recursos efetivamente utilizados pelo cliente.', 1),
  ('73000000-0000-4000-8000-000000000162', '62000000-0000-4000-8000-000000000041', 'O cliente deve pagar um valor fixo mensal, independentemente da quantidade de recursos utilizados.', false, 'Incorreta. Um valor fixo mensal, independentemente do uso, nao representa o modelo de consumo baseado no uso da nuvem.', 2),
  ('73000000-0000-4000-8000-000000000163', '62000000-0000-4000-8000-000000000041', 'O cliente e obrigado a comprar hardware fisico antes de poder utilizar qualquer servico de nuvem.', false, 'Incorreta. Esse modelo elimina, e nao exige, a compra de hardware fisico antes da utilizacao dos servicos.', 3),
  ('73000000-0000-4000-8000-000000000164', '62000000-0000-4000-8000-000000000041', 'O cliente paga uma taxa unica anual, sem qualquer relacao com o volume de uso dos recursos.', false, 'Incorreta. Uma taxa unica anual sem relacao com o volume de uso nao caracteriza o modelo baseado em consumo.', 4),
  ('73000000-0000-4000-8000-000000000165', '62000000-0000-4000-8000-000000000042', 'A obrigatoriedade de pagar pela capacidade maxima o ano todo, mesmo fora dos periodos de pico.', false, 'Incorreta. O modelo de consumo baseado no uso justamente evita pagar pela capacidade maxima o tempo todo, ajustando o custo a demanda real.', 1),
  ('73000000-0000-4000-8000-000000000166', '62000000-0000-4000-8000-000000000042', 'A possibilidade de reduzir custos durante periodos de baixa demanda, pagando menos quando utiliza menos recursos.', true, 'Correta. O modelo de consumo baseado no uso permite reduzir custos durante periodos de baixa demanda, pagando proporcionalmente ao uso.', 2),
  ('73000000-0000-4000-8000-000000000167', '62000000-0000-4000-8000-000000000042', 'A necessidade de firmar contratos rigidos de capacidade fixa por varios anos.', false, 'Incorreta. Contratos rigidos de capacidade fixa por varios anos contrariam a flexibilidade caracteristica desse modelo.', 3),
  ('73000000-0000-4000-8000-000000000168', '62000000-0000-4000-8000-000000000042', 'A exigencia de comprar hardware fisico adicional antes de cada periodo de pico.', false, 'Incorreta. Nao e necessario comprar hardware fisico adicional, ja que os recursos sao provisionados sob demanda na nuvem.', 4),
  ('73000000-0000-4000-8000-000000000169', '62000000-0000-4000-8000-000000000043', 'O numero de funcionarios que a empresa possui, independentemente do uso de recursos.', false, 'Incorreta. O numero de funcionarios da empresa nao determina diretamente o valor cobrado pelo consumo de recursos de nuvem.', 1),
  ('73000000-0000-4000-8000-000000000170', '62000000-0000-4000-8000-000000000043', 'A quantidade de escritorios fisicos que a empresa mantem.', false, 'Incorreta. A quantidade de escritorios fisicos nao tem relacao com a cobranca baseada no consumo de recursos de nuvem.', 2),
  ('73000000-0000-4000-8000-000000000171', '62000000-0000-4000-8000-000000000043', 'A quantidade de recursos computacionais efetivamente consumidos, como processamento, armazenamento e trafego de rede.', true, 'Correta. A cobranca no modelo de consumo baseado no uso e determinada pela quantidade de recursos computacionais efetivamente utilizados.', 3),
  ('73000000-0000-4000-8000-000000000172', '62000000-0000-4000-8000-000000000043', 'O ano de fundacao da empresa que contrata o servico de nuvem.', false, 'Incorreta. O ano de fundacao da empresa e uma informacao irrelevante para o calculo do valor cobrado por consumo de recursos.', 4),
  ('73000000-0000-4000-8000-000000000173', '62000000-0000-4000-8000-000000000044', 'A obrigatoriedade de manter a mesma capacidade computacional ligada 24 horas por dia, independentemente do uso.', false, 'Incorreta. Manter a mesma capacidade ligada 24 horas por dia geraria custos desnecessarios durante os periodos de ociosidade da empresa.', 1),
  ('73000000-0000-4000-8000-000000000174', '62000000-0000-4000-8000-000000000044', 'A necessidade de comprar servidores fisicos dedicados exclusivamente para o processamento noturno.', false, 'Incorreta. Comprar servidores fisicos dedicados contraria o principio de flexibilidade e economia do modelo baseado em consumo.', 2),
  ('73000000-0000-4000-8000-000000000175', '62000000-0000-4000-8000-000000000044', 'A exigencia de um contrato anual fixo que nao permite variacao de custos conforme o uso.', false, 'Incorreta. Um contrato anual fixo sem variacao de custos nao aproveitaria a economia gerada pelos periodos de baixa utilizacao.', 3),
  ('73000000-0000-4000-8000-000000000176', '62000000-0000-4000-8000-000000000044', 'A possibilidade de pagar apenas pelos recursos utilizados durante o processamento noturno, reduzindo custos nos periodos de ociosidade.', true, 'Correta. O modelo de consumo baseado no uso permite economia significativa ao pagar apenas pelos recursos usados durante o processamento noturno.', 4),
  ('73000000-0000-4000-8000-000000000177', '62000000-0000-4000-8000-000000000045', 'A ausencia de investimento inicial obrigatorio, permitindo comecar com poucos recursos e aumentar o consumo apenas se o aplicativo crescer.', true, 'Correta. A ausencia de investimento inicial obrigatorio permite comecar pequeno e escalar o consumo conforme o crescimento real do aplicativo.', 1),
  ('73000000-0000-4000-8000-000000000178', '62000000-0000-4000-8000-000000000045', 'A exigencia de comprar toda a capacidade de servidores necessaria para um cenario de sucesso maximo, desde o primeiro dia.', false, 'Incorreta. Comprar capacidade maxima desde o inicio contraria a logica de pagar apenas pelo que e efetivamente utilizado.', 2),
  ('73000000-0000-4000-8000-000000000179', '62000000-0000-4000-8000-000000000045', 'A obrigatoriedade de firmar um contrato de exclusividade com um unico provedor por cinco anos.', false, 'Incorreta. Nao ha exigencia de contratos de exclusividade de longo prazo para utilizar o modelo de consumo baseado no uso.', 3),
  ('73000000-0000-4000-8000-000000000180', '62000000-0000-4000-8000-000000000045', 'A necessidade de adquirir hardware fisico redundante antes mesmo do lancamento do aplicativo.', false, 'Incorreta. O modelo de consumo baseado no uso elimina, e nao exige, a compra antecipada de hardware fisico redundante.', 4),
  ('73000000-0000-4000-8000-000000000181', '62000000-0000-4000-8000-000000000046', 'Nenhum efeito, pois o modelo de consumo baseado no uso sempre cobra o mesmo valor, independentemente do tempo de uso.', false, 'Incorreta. O modelo de consumo baseado no uso varia conforme o tempo e a quantidade de recursos utilizados, nao sendo um valor fixo.', 1),
  ('73000000-0000-4000-8000-000000000182', '62000000-0000-4000-8000-000000000046', 'Um aumento de custos, ja que desligar recursos aumenta o valor cobrado pelo provedor de nuvem.', false, 'Incorreta. Desligar recursos reduz, e nao aumenta, o custo no modelo de consumo baseado no uso, ja que menos recursos sao consumidos.', 2),
  ('73000000-0000-4000-8000-000000000183', '62000000-0000-4000-8000-000000000046', 'Uma reducao de custos, ja que o cliente paga apenas pelo tempo em que os recursos ficam efetivamente ativos e em uso.', true, 'Correta. Desligar os recursos fora do horario de uso reduz o consumo e, consequentemente, o custo cobrado pelo provedor de nuvem.', 3),
  ('73000000-0000-4000-8000-000000000184', '62000000-0000-4000-8000-000000000046', 'A obrigatoriedade de pagar uma multa contratual por nao utilizar os recursos continuamente.', false, 'Incorreta. Nao ha, em geral, multas contratuais por reduzir o uso de recursos; essa e justamente uma vantagem do modelo baseado em consumo.', 4),
  ('73000000-0000-4000-8000-000000000185', '62000000-0000-4000-8000-000000000047', 'Manter a capacidade maxima de recursos ativa continuamente durante todo o ano, mesmo sem eventos em andamento.', false, 'Incorreta. Manter a capacidade maxima ativa o ano todo geraria custos desnecessarios durante os longos periodos sem eventos.', 1),
  ('73000000-0000-4000-8000-000000000186', '62000000-0000-4000-8000-000000000047', 'Provisionar recursos adicionais apenas durante o periodo de organizacao de cada evento e reduzi-los logo apos seu encerramento.', true, 'Correta. Provisionar recursos apenas durante os eventos e reduzi-los depois e a abordagem mais alinhada ao modelo de consumo baseado no uso.', 2),
  ('73000000-0000-4000-8000-000000000187', '62000000-0000-4000-8000-000000000047', 'Comprar servidores fisicos dedicados exclusivamente para cada evento realizado pela empresa.', false, 'Incorreta. Comprar servidores fisicos dedicados para cada evento contraria a flexibilidade e economia do modelo de consumo baseado no uso.', 3),
  ('73000000-0000-4000-8000-000000000188', '62000000-0000-4000-8000-000000000047', 'Firmar um contrato de capacidade fixa e imutavel, independentemente da ocorrencia ou nao de eventos.', false, 'Incorreta. Um contrato de capacidade fixa e imutavel nao aproveitaria a flexibilidade de custos proporcionada pelo modelo baseado em consumo.', 4),
  ('73000000-0000-4000-8000-000000000189', '62000000-0000-4000-8000-000000000048', 'Os dois modelos apresentam exatamente o mesmo nivel de risco financeiro para a empresa.', false, 'Incorreta. Os niveis de risco financeiro entre os dois modelos sao significativamente diferentes, nao sendo equivalentes.', 1),
  ('73000000-0000-4000-8000-000000000190', '62000000-0000-4000-8000-000000000048', 'O modelo de consumo baseado no uso sempre representa maior risco financeiro do que a compra antecipada de hardware.', false, 'Incorreta. E a compra antecipada de hardware, e nao o modelo de consumo baseado no uso, que geralmente representa maior risco financeiro.', 2),
  ('73000000-0000-4000-8000-000000000191', '62000000-0000-4000-8000-000000000048', 'A compra antecipada de hardware elimina totalmente qualquer risco financeiro relacionado a capacidade computacional.', false, 'Incorreta. A compra antecipada de hardware nao elimina o risco financeiro; pelo contrario, aumenta o risco de investir em capacidade nao utilizada.', 3),
  ('73000000-0000-4000-8000-000000000192', '62000000-0000-4000-8000-000000000048', 'O modelo de consumo baseado no uso reduz o risco de investir em capacidade que pode nao ser totalmente utilizada, diferente da compra antecipada de hardware.', true, 'Correta. O modelo de consumo baseado no uso reduz o risco de investir em capacidade ociosa, ao contrario da compra antecipada de hardware.', 4),
  ('73000000-0000-4000-8000-000000000193', '62000000-0000-4000-8000-000000000049', 'O segundo cenario tende a ser financeiramente mais eficiente, pois evita capacidade ociosa ao ajustar o consumo a demanda real, enquanto o primeiro pode gerar desperdicio em periodos de baixa demanda.', true, 'Correta. O modelo de consumo baseado no uso tende a ser mais eficiente financeiramente ao evitar capacidade ociosa em periodos de baixa demanda.', 1),
  ('73000000-0000-4000-8000-000000000194', '62000000-0000-4000-8000-000000000049', 'O primeiro cenario e sempre financeiramente mais eficiente, independentemente da variacao real da demanda ao longo do tempo.', false, 'Incorreta. Comprar hardware para o pico maximo pode gerar desperdicio financeiro significativo durante periodos de baixa demanda.', 2),
  ('73000000-0000-4000-8000-000000000195', '62000000-0000-4000-8000-000000000049', 'Nao ha qualquer diferenca de eficiencia financeira entre comprar hardware para o pico maximo e utilizar consumo sob demanda.', false, 'Incorreta. Ha diferencas relevantes de eficiencia financeira entre os dois cenarios, especialmente diante de demanda variavel.', 3),
  ('73000000-0000-4000-8000-000000000196', '62000000-0000-4000-8000-000000000049', 'O modelo de consumo baseado no uso e sempre mais caro do que comprar hardware fisico, independentemente do padrao de demanda.', false, 'Incorreta. O modelo de consumo baseado no uso nao e sempre mais caro; em cenarios de demanda variavel, tende a ser mais economico.', 4),
  ('73000000-0000-4000-8000-000000000197', '62000000-0000-4000-8000-000000000050', 'Migrar todos os ambientes de teste para servidores fisicos dedicados, eliminando totalmente o uso da nuvem.', false, 'Incorreta. Migrar para servidores fisicos dedicados eliminaria a flexibilidade de custo proporcionada pelo modelo de consumo baseado no uso.', 1),
  ('73000000-0000-4000-8000-000000000198', '62000000-0000-4000-8000-000000000050', 'Ignorar o aumento de custos, ja que o modelo de consumo baseado no uso nao permite qualquer tipo de otimizacao.', false, 'Incorreta. O modelo de consumo baseado no uso permite, sim, diversas formas de otimizacao de custos, como desligar recursos ociosos.', 2),
  ('73000000-0000-4000-8000-000000000199', '62000000-0000-4000-8000-000000000050', 'Implementar rotinas para desligar ou reduzir automaticamente os ambientes de teste fora do horario de uso, pagando apenas pelo tempo efetivamente necessario.', true, 'Correta. Desligar ou reduzir automaticamente os ambientes de teste fora do horario de uso reduz custos ao pagar apenas pelo necessario.', 3),
  ('73000000-0000-4000-8000-000000000200', '62000000-0000-4000-8000-000000000050', 'Aumentar ainda mais a capacidade dos ambientes de teste, independentemente do horario de utilizacao real.', false, 'Incorreta. Aumentar a capacidade dos ambientes de teste sem necessidade real elevaria ainda mais os custos, agravando o problema.', 4),
  ('73000000-0000-4000-8000-000000000201', '62000000-0000-4000-8000-000000000051', 'Um modelo de despesa operacional recorrente, paga mensalmente conforme o uso.', false, 'Incorreta. Uma despesa operacional recorrente paga conforme o uso e caracteristica do OpEx, nao do CapEx.', 1),
  ('73000000-0000-4000-8000-000000000202', '62000000-0000-4000-8000-000000000051', 'Despesa de capital (Capital Expenditure), representando investimento inicial significativo em ativos fisicos, como servidores.', true, 'Correta. CapEx representa investimento inicial em ativos fisicos, como servidores, geralmente depreciados ao longo do tempo.', 2),
  ('73000000-0000-4000-8000-000000000203', '62000000-0000-4000-8000-000000000051', 'Um tipo de licenca de software gratuita oferecida por provedores de nuvem.', false, 'Incorreta. CapEx nao esta relacionado a licencas de software gratuitas oferecidas por provedores de nuvem.', 3),
  ('73000000-0000-4000-8000-000000000204', '62000000-0000-4000-8000-000000000051', 'Um imposto cobrado exclusivamente sobre servicos de armazenamento em nuvem.', false, 'Incorreta. CapEx nao e um imposto; e uma categoria contabil relacionada a investimentos em ativos de capital.', 4),
  ('73000000-0000-4000-8000-000000000205', '62000000-0000-4000-8000-000000000052', 'Despesa operacional (Operational Expenditure), referente a custos recorrentes pagos conforme o consumo dos servicos, como assinaturas de nuvem.', true, 'Correta. OpEx representa despesas operacionais recorrentes, como pagamentos por consumo de servicos de nuvem.', 1),
  ('73000000-0000-4000-8000-000000000206', '62000000-0000-4000-8000-000000000052', 'Um tipo especifico de hardware fisico utilizado exclusivamente em datacenters privados.', false, 'Incorreta. OpEx nao se refere a um tipo especifico de hardware fisico, mas sim a uma categoria de despesa financeira.', 2),
  ('73000000-0000-4000-8000-000000000207', '62000000-0000-4000-8000-000000000052', 'Um investimento unico e nao recorrente em infraestrutura fisica de longo prazo.', false, 'Incorreta. Um investimento unico de longo prazo em infraestrutura fisica e caracteristico do CapEx, nao do OpEx.', 3),
  ('73000000-0000-4000-8000-000000000208', '62000000-0000-4000-8000-000000000052', 'Um certificado de conformidade regulatoria exigido para uso de servicos em nuvem.', false, 'Incorreta. OpEx nao e um certificado de conformidade regulatoria; e uma classificacao de despesa operacional.', 4),
  ('73000000-0000-4000-8000-000000000209', '62000000-0000-4000-8000-000000000053', 'O pagamento mensal de uma assinatura de servico de armazenamento em nuvem.', false, 'Incorreta. O pagamento mensal de uma assinatura de nuvem e um exemplo de despesa operacional recorrente (OpEx), nao CapEx.', 1),
  ('73000000-0000-4000-8000-000000000210', '62000000-0000-4000-8000-000000000053', 'A cobranca variavel de uma maquina virtual utilizada por poucas horas.', false, 'Incorreta. Uma cobranca variavel baseada em horas de uso e caracteristica do modelo de consumo (OpEx), nao do CapEx.', 2),
  ('73000000-0000-4000-8000-000000000211', '62000000-0000-4000-8000-000000000053', 'A taxa de consumo de dados transferidos entre regioes de um provedor de nuvem.', false, 'Incorreta. Taxas de consumo de dados sao despesas operacionais recorrentes, classificadas como OpEx.', 3),
  ('73000000-0000-4000-8000-000000000212', '62000000-0000-4000-8000-000000000053', 'A compra de servidores fisicos para instalacao em um datacenter proprio da empresa.', true, 'Correta. A compra de servidores fisicos e um investimento inicial em ativo de longo prazo, caracteristica classica do CapEx.', 4),
  ('73000000-0000-4000-8000-000000000213', '62000000-0000-4000-8000-000000000054', 'CapEx, pois exige um grande investimento inicial concentrado, o que se encaixa melhor em fluxo de caixa limitado.', false, 'Incorreta. O CapEx exige justamente um grande investimento inicial, o que nao se encaixa bem em um cenario de fluxo de caixa limitado.', 1),
  ('73000000-0000-4000-8000-000000000214', '62000000-0000-4000-8000-000000000054', 'Nenhum dos dois modelos e viavel quando o fluxo de caixa e limitado.', false, 'Incorreta. O modelo OpEx e viavel mesmo com fluxo de caixa limitado, pois distribui os custos ao longo do tempo.', 2),
  ('73000000-0000-4000-8000-000000000215', '62000000-0000-4000-8000-000000000054', 'OpEx, pois permite distribuir os custos ao longo do tempo, conforme o uso, sem exigir grande desembolso inicial.', true, 'Correta. O modelo OpEx distribui os custos conforme o uso, evitando grandes desembolsos iniciais, o que e ideal para fluxo de caixa limitado.', 3),
  ('73000000-0000-4000-8000-000000000216', '62000000-0000-4000-8000-000000000054', 'CapEx combinado obrigatoriamente com um emprestimo bancario de longo prazo.', false, 'Incorreta. Combinar CapEx com um emprestimo bancario nao resolve o problema de fluxo de caixa limitado no curto prazo.', 4),
  ('73000000-0000-4000-8000-000000000217', '62000000-0000-4000-8000-000000000055', 'Como CapEx, ja que qualquer gasto com tecnologia e sempre classificado como investimento de capital.', false, 'Incorreta. Nem todo gasto com tecnologia e CapEx; despesas recorrentes de consumo, sem compra de ativos, sao classificadas como OpEx.', 1),
  ('73000000-0000-4000-8000-000000000218', '62000000-0000-4000-8000-000000000055', 'Como OpEx, ja que se trata de despesas operacionais recorrentes baseadas no consumo mensal dos servicos.', true, 'Correta. Despesas recorrentes baseadas no consumo mensal de servicos de nuvem sao classificadas como OpEx.', 2),
  ('73000000-0000-4000-8000-000000000219', '62000000-0000-4000-8000-000000000055', 'Como um tipo de imposto sobre servicos digitais cobrado pelo governo.', false, 'Incorreta. Essas despesas nao sao um imposto governamental, mas sim uma classificacao contabil de despesa operacional.', 3),
  ('73000000-0000-4000-8000-000000000220', '62000000-0000-4000-8000-000000000055', 'Como uma doacao, ja que nao ha transferencia de propriedade de ativos fisicos.', false, 'Incorreta. Pagamentos por servicos de nuvem nao sao doacoes; sao despesas contratuais pela utilizacao de recursos.', 4),
  ('73000000-0000-4000-8000-000000000221', '62000000-0000-4000-8000-000000000056', 'CapEx, pois concentra o investimento em um unico momento, facilitando o planejamento anual.', false, 'Incorreta. O CapEx concentra o investimento em um momento especifico, o que pode gerar picos orcamentarios, nao distribuicao uniforme.', 1),
  ('73000000-0000-4000-8000-000000000222', '62000000-0000-4000-8000-000000000056', 'Nenhum modelo de despesa pode ser ajustado para melhorar a previsibilidade orcamentaria.', false, 'Incorreta. E possivel melhorar a previsibilidade orcamentaria escolhendo um modelo de despesa mais alinhado a esse objetivo, como o OpEx.', 2),
  ('73000000-0000-4000-8000-000000000223', '62000000-0000-4000-8000-000000000056', 'Um modelo misto exclusivamente baseado em compras avulsas de hardware sem qualquer padrao.', false, 'Incorreta. Compras avulsas de hardware sem padrao nao contribuem para maior previsibilidade orcamentaria.', 3),
  ('73000000-0000-4000-8000-000000000224', '62000000-0000-4000-8000-000000000056', 'OpEx, pois distribui os custos de forma recorrente ao longo do tempo, conforme o consumo dos servicos.', true, 'Correta. O modelo OpEx distribui os custos de forma recorrente, favorecendo maior previsibilidade orcamentaria ao longo do tempo.', 4),
  ('73000000-0000-4000-8000-000000000225', '62000000-0000-4000-8000-000000000057', 'Uma transicao de despesas predominantemente CapEx para despesas predominantemente OpEx.', true, 'Correta. A migracao de servidores fisicos para nuvem por consumo normalmente desloca despesas de CapEx para OpEx.', 1),
  ('73000000-0000-4000-8000-000000000226', '62000000-0000-4000-8000-000000000057', 'Uma transicao de despesas predominantemente OpEx para despesas predominantemente CapEx.', false, 'Incorreta. A transicao ocorre no sentido oposto: de CapEx, caracteristico da compra de hardware, para OpEx, caracteristico do consumo recorrente.', 2),
  ('73000000-0000-4000-8000-000000000227', '62000000-0000-4000-8000-000000000057', 'Nao ha qualquer reclassificacao contabil ao migrar de servidores fisicos para servicos de nuvem.', false, 'Incorreta. Ha, sim, uma reclassificacao contabil relevante ao mudar o modelo de aquisicao de recursos de TI.', 3),
  ('73000000-0000-4000-8000-000000000228', '62000000-0000-4000-8000-000000000057', 'Uma transformacao automatica de todas as despesas em doacoes para fins fiscais.', false, 'Incorreta. Despesas com servicos de nuvem nao se tornam doacoes; continuam sendo despesas operacionais contratuais.', 4),
  ('73000000-0000-4000-8000-000000000229', '62000000-0000-4000-8000-000000000058', 'CapEx e sempre mais flexivel que OpEx para ajustar gastos conforme a demanda variavel.', false, 'Incorreta. E o OpEx, e nao o CapEx, que costuma oferecer maior flexibilidade para ajustar gastos conforme a demanda.', 1),
  ('73000000-0000-4000-8000-000000000230', '62000000-0000-4000-8000-000000000058', 'Ambos os modelos oferecem exatamente o mesmo nivel de flexibilidade para ajuste de gastos.', false, 'Incorreta. Os dois modelos apresentam niveis de flexibilidade diferentes; nao sao equivalentes nesse aspecto.', 2),
  ('73000000-0000-4000-8000-000000000231', '62000000-0000-4000-8000-000000000058', 'OpEx costuma ser mais flexivel, pois os custos podem ser ajustados conforme o consumo real, enquanto o CapEx representa um investimento fixo ja realizado.', true, 'Correta. O OpEx permite ajustar os gastos conforme o consumo real, enquanto o CapEx representa um investimento fixo ja realizado.', 3),
  ('73000000-0000-4000-8000-000000000232', '62000000-0000-4000-8000-000000000058', 'Nenhum dos dois modelos permite qualquer tipo de ajuste apos a decisao inicial de investimento.', false, 'Incorreta. O modelo OpEx permite ajustes continuos conforme a demanda, ao contrario do que a afirmacao sugere.', 4),
  ('73000000-0000-4000-8000-000000000233', '62000000-0000-4000-8000-000000000059', 'Considerar apenas o valor total pago no primeiro mes de cada modelo, ignorando qualquer projecao de longo prazo.', false, 'Incorreta. Considerar apenas o custo do primeiro mes ignora fatores de longo prazo essenciais, como depreciacao e manutencao.', 1),
  ('73000000-0000-4000-8000-000000000234', '62000000-0000-4000-8000-000000000059', 'Comparar o custo total de propriedade (TCO) ao longo do tempo, considerando depreciacao, manutencao e obsolescencia do CapEx frente aos custos recorrentes e flexiveis do OpEx.', true, 'Correta. Comparar o custo total de propriedade ao longo do tempo e a abordagem mais adequada para essa decisao financeira.', 2),
  ('73000000-0000-4000-8000-000000000235', '62000000-0000-4000-8000-000000000059', 'Escolher aleatoriamente entre os dois modelos, ja que o resultado financeiro de longo prazo e sempre identico.', false, 'Incorreta. O resultado financeiro de longo prazo varia significativamente entre os modelos, dependendo de diversos fatores.', 3),
  ('73000000-0000-4000-8000-000000000236', '62000000-0000-4000-8000-000000000059', 'Considerar exclusivamente o numero de servidores fisicamente instalados, sem qualquer outra variavel financeira.', false, 'Incorreta. O numero de servidores fisicamente instalados e apenas um dos muitos fatores relevantes, nao o unico a considerar.', 4),
  ('73000000-0000-4000-8000-000000000237', '62000000-0000-4000-8000-000000000060', 'Investir todo o caixa disponivel imediatamente na compra de servidores fisicos, priorizando exclusivamente o CapEx.', false, 'Incorreta. Investir todo o caixa disponivel em CapEx comprometeria os recursos necessarios para a expansao do negocio.', 1),
  ('73000000-0000-4000-8000-000000000238', '62000000-0000-4000-8000-000000000060', 'Ignorar completamente qualquer planejamento financeiro relacionado a TI durante o periodo de crescimento acelerado.', false, 'Incorreta. Ignorar o planejamento financeiro de TI durante o crescimento acelerado pode gerar riscos financeiros significativos.', 2),
  ('73000000-0000-4000-8000-000000000239', '62000000-0000-4000-8000-000000000060', 'Contrair um grande emprestimo bancario para financiar a compra antecipada de toda a infraestrutura fisica necessaria para os proximos dez anos.', false, 'Incorreta. Contrair um grande emprestimo para infraestrutura fisica de longo prazo aumenta o risco financeiro e reduz a flexibilidade da empresa.', 3),
  ('73000000-0000-4000-8000-000000000240', '62000000-0000-4000-8000-000000000060', 'Priorizar o modelo OpEx por meio de servicos de nuvem, preservando caixa para expansao do negocio e obtendo maior previsibilidade de custos operacionais recorrentes.', true, 'Correta. Priorizar o modelo OpEx preserva caixa para expansao e oferece maior previsibilidade de custos operacionais recorrentes.', 4),
  ('73000000-0000-4000-8000-000000000241', '62000000-0000-4000-8000-000000000061', 'Um modelo em que o provedor de nuvem gerencia toda a infraestrutura subjacente, permitindo que o desenvolvedor foque apenas no codigo da aplicacao.', true, 'Correta. No modelo serverless, o provedor gerencia a infraestrutura subjacente, permitindo que o desenvolvedor foque no codigo.', 1),
  ('73000000-0000-4000-8000-000000000242', '62000000-0000-4000-8000-000000000061', 'Um modelo em que nao existe absolutamente nenhum servidor fisico envolvido em qualquer parte do processo.', false, 'Incorreta. Servidores fisicos continuam existindo por tras do servico; o termo ''sem servidor'' refere-se a ausencia de gerenciamento pelo cliente.', 2),
  ('73000000-0000-4000-8000-000000000243', '62000000-0000-4000-8000-000000000061', 'Um modelo em que o cliente deve gerenciar manualmente todos os servidores fisicos utilizados pela aplicacao.', false, 'Incorreta. No modelo serverless, o cliente nao gerencia manualmente os servidores; essa responsabilidade e do provedor de nuvem.', 3),
  ('73000000-0000-4000-8000-000000000244', '62000000-0000-4000-8000-000000000061', 'Um modelo exclusivo para hospedagem de sites estaticos, sem suporte a execucao de codigo.', false, 'Incorreta. Serverless computing suporta execucao de codigo sob demanda, nao sendo exclusivo para sites estaticos.', 4),
  ('73000000-0000-4000-8000-000000000245', '62000000-0000-4000-8000-000000000062', 'A obrigatoriedade de gerenciar manualmente a capacidade de todos os servidores subjacentes.', false, 'Incorreta. O modelo serverless justamente elimina, e nao exige, o gerenciamento manual da capacidade dos servidores subjacentes.', 1),
  ('73000000-0000-4000-8000-000000000246', '62000000-0000-4000-8000-000000000062', 'A eliminacao da necessidade de provisionar e gerenciar servidores, permitindo foco total no desenvolvimento da aplicacao.', true, 'Correta. O serverless computing elimina a necessidade de provisionar e gerenciar servidores, permitindo foco no desenvolvimento.', 2),
  ('73000000-0000-4000-8000-000000000247', '62000000-0000-4000-8000-000000000062', 'A exigencia de manter servidores fisicos ligados continuamente, mesmo sem execucao de codigo.', false, 'Incorreta. Servidores serverless nao precisam ficar ligados continuamente sem execucao; eles sao acionados sob demanda.', 3),
  ('73000000-0000-4000-8000-000000000248', '62000000-0000-4000-8000-000000000062', 'A necessidade de pagar um valor fixo mensal, independentemente da quantidade de execucoes de codigo.', false, 'Incorreta. O modelo serverless geralmente cobra com base na execucao real do codigo, nao um valor fixo independente do uso.', 4),
  ('73000000-0000-4000-8000-000000000249', '62000000-0000-4000-8000-000000000063', 'Com base no numero de funcionarios que a empresa possui.', false, 'Incorreta. O numero de funcionarios da empresa nao tem relacao com a cobranca de recursos em um modelo serverless.', 1),
  ('73000000-0000-4000-8000-000000000250', '62000000-0000-4000-8000-000000000063', 'Com uma taxa fixa mensal, independentemente de o codigo ser executado ou nao.', false, 'Incorreta. Uma taxa fixa mensal, independentemente da execucao do codigo, nao e caracteristica do modelo serverless, que cobra por uso.', 2),
  ('73000000-0000-4000-8000-000000000251', '62000000-0000-4000-8000-000000000063', 'Com base na execucao real do codigo, geralmente considerando tempo de execucao e recursos consumidos durante cada chamada.', true, 'Correta. A cobranca em serverless e baseada na execucao real do codigo, considerando tempo e recursos consumidos em cada chamada.', 3),
  ('73000000-0000-4000-8000-000000000252', '62000000-0000-4000-8000-000000000063', 'Com base exclusivamente no tamanho fisico do datacenter do provedor de nuvem.', false, 'Incorreta. O tamanho fisico do datacenter do provedor nao e um fator relevante para a cobranca do cliente em serverless.', 4),
  ('73000000-0000-4000-8000-000000000253', '62000000-0000-4000-8000-000000000064', 'Um servidor fisico dedicado, ligado continuamente, mesmo sem uploads acontecendo.', false, 'Incorreta. Manter um servidor fisico ligado continuamente geraria custo desnecessario durante os longos periodos sem uploads.', 1),
  ('73000000-0000-4000-8000-000000000254', '62000000-0000-4000-8000-000000000064', 'Uma maquina virtual reservada por contrato anual, independentemente da frequencia de uploads.', false, 'Incorreta. Reservar uma maquina virtual por contrato anual nao e eficiente para uma funcao esporadica e imprevisivel como essa.', 2),
  ('73000000-0000-4000-8000-000000000255', '62000000-0000-4000-8000-000000000064', 'Um datacenter proprio construido exclusivamente para essa funcao especifica.', false, 'Incorreta. Construir um datacenter proprio para uma funcao especifica e esporadica seria um investimento desproporcional.', 3),
  ('73000000-0000-4000-8000-000000000256', '62000000-0000-4000-8000-000000000064', 'Uma funcao serverless, que e acionada automaticamente apenas quando um upload ocorre, sem necessidade de manter recursos ativos continuamente.', true, 'Correta. Uma funcao serverless e acionada apenas quando necessario, evitando custos durante os periodos sem uploads.', 4),
  ('73000000-0000-4000-8000-000000000257', '62000000-0000-4000-8000-000000000065', 'O escalonamento automatico gerenciado pelo provedor, que ajusta a capacidade de execucao conforme o volume de requisicoes, sem intervencao manual.', true, 'Correta. O escalonamento automatico gerenciado pelo provedor permite que a API atenda picos de requisicoes sem intervencao manual.', 1),
  ('73000000-0000-4000-8000-000000000258', '62000000-0000-4000-8000-000000000065', 'A necessidade de a equipe configurar manualmente novos servidores a cada pico de requisicoes.', false, 'Incorreta. No modelo serverless, o escalonamento e automatico e gerenciado pelo provedor, sem necessidade de configuracao manual a cada pico.', 2),
  ('73000000-0000-4000-8000-000000000259', '62000000-0000-4000-8000-000000000065', 'A obrigatoriedade de contratar capacidade fixa suficiente para o maior pico ja registrado historicamente.', false, 'Incorreta. Nao e necessario contratar capacidade fixa para o maior pico historico, ja que o escalonamento e automatico e sob demanda.', 3),
  ('73000000-0000-4000-8000-000000000260', '62000000-0000-4000-8000-000000000065', 'A exigencia de desligar a API durante os periodos de baixa demanda para evitar cobrancas.', false, 'Incorreta. Nao e necessario desligar manualmente a API; ela simplesmente nao gera custos significativos durante periodos de baixa demanda.', 4),
  ('73000000-0000-4000-8000-000000000261', '62000000-0000-4000-8000-000000000066', 'Manter uma maquina virtual dedicada e sempre ligada, monitorando continuamente o armazenamento.', false, 'Incorreta. Manter uma maquina virtual sempre ligada para monitorar continuamente geraria custo desnecessario para uma rotina esporadica.', 1),
  ('73000000-0000-4000-8000-000000000262', '62000000-0000-4000-8000-000000000066', 'Contratar uma equipe para verificar manualmente, a cada hora, se novos arquivos foram adicionados.', false, 'Incorreta. Verificacao manual a cada hora e ineficiente, sujeita a atrasos e nao escalavel, alem de nao ser uma solucao de serverless computing.', 2),
  ('73000000-0000-4000-8000-000000000263', '62000000-0000-4000-8000-000000000066', 'Configurar uma funcao serverless acionada automaticamente por um evento de novo arquivo no armazenamento, executando a validacao apenas quando necessario.', true, 'Correta. Uma funcao serverless acionada por eventos executa a validacao apenas quando necessario, sendo a abordagem mais eficiente.', 3),
  ('73000000-0000-4000-8000-000000000264', '62000000-0000-4000-8000-000000000066', 'Construir um servidor fisico dedicado exclusivamente a essa rotina de validacao.', false, 'Incorreta. Construir um servidor fisico dedicado para uma rotina esporadica seria um investimento desnecessario e ineficiente.', 4),
  ('73000000-0000-4000-8000-000000000265', '62000000-0000-4000-8000-000000000067', 'Um cluster de servidores fisicos dedicados, reservado com capacidade fixa desde o inicio do projeto.', false, 'Incorreta. Um cluster de servidores dedicados com capacidade fixa geraria custos mesmo durante periodos sem uso, o que nao e ideal na fase inicial.', 1),
  ('73000000-0000-4000-8000-000000000266', '62000000-0000-4000-8000-000000000067', 'Serverless computing, que cobra com base na execucao real do codigo, evitando custos durante periodos de inatividade.', true, 'Correta. O modelo serverless cobra com base na execucao real, evitando custos com capacidade ociosa, adequado para uma fase inicial de testes.', 2),
  ('73000000-0000-4000-8000-000000000267', '62000000-0000-4000-8000-000000000067', 'Uma infraestrutura on-premises construida especificamente para o prototipo.', false, 'Incorreta. Construir uma infraestrutura on-premises especifica para um prototipo representa um investimento desproporcional na fase inicial.', 3),
  ('73000000-0000-4000-8000-000000000268', '62000000-0000-4000-8000-000000000067', 'Um contrato de capacidade reservada de longo prazo com um provedor de nuvem.', false, 'Incorreta. Um contrato de capacidade reservada de longo prazo nao oferece a flexibilidade de custo necessaria para uma fase de testes.', 4),
  ('73000000-0000-4000-8000-000000000269', '62000000-0000-4000-8000-000000000068', 'Em ambos os modelos, o cliente e sempre responsavel por gerenciar toda a infraestrutura subjacente.', false, 'Incorreta. No serverless, o cliente nao gerencia a infraestrutura subjacente; essa responsabilidade e do provedor de nuvem.', 1),
  ('73000000-0000-4000-8000-000000000270', '62000000-0000-4000-8000-000000000068', 'Em maquinas virtuais tradicionais, o provedor gerencia totalmente o sistema operacional e a aplicacao, assim como no serverless.', false, 'Incorreta. Em maquinas virtuais tradicionais (IaaS), o cliente ainda gerencia o sistema operacional, diferente do modelo serverless.', 2),
  ('73000000-0000-4000-8000-000000000271', '62000000-0000-4000-8000-000000000068', 'Serverless computing exige mais gerenciamento de infraestrutura do cliente do que maquinas virtuais tradicionais.', false, 'Incorreta. E o contrario: o serverless exige menos gerenciamento de infraestrutura do cliente em comparacao a maquinas virtuais tradicionais.', 3),
  ('73000000-0000-4000-8000-000000000272', '62000000-0000-4000-8000-000000000068', 'No serverless computing, o provedor gerencia toda a infraestrutura, incluindo o escalonamento automatico, enquanto em maquinas virtuais tradicionais o cliente ainda precisa gerenciar o sistema operacional.', true, 'Correta. No serverless, o provedor gerencia toda a infraestrutura e o escalonamento, enquanto em VMs tradicionais o cliente gerencia o sistema operacional.', 4),
  ('73000000-0000-4000-8000-000000000273', '62000000-0000-4000-8000-000000000069', 'Para cargas de trabalho constantes e previsiveis, o custo do modelo serverless pode ser proporcionalmente maior do que o de maquinas virtuais reservadas, tornando essencial comparar o custo total de cada abordagem antes de decidir.', true, 'Correta. Para cargas de trabalho constantes, e essencial comparar o custo total entre serverless e maquinas virtuais reservadas antes de decidir.', 1),
  ('73000000-0000-4000-8000-000000000274', '62000000-0000-4000-8000-000000000069', 'Serverless computing e sempre a opcao mais barata, independentemente do padrao de uso da carga de trabalho.', false, 'Incorreta. O serverless nao e sempre a opcao mais barata; para cargas constantes, maquinas virtuais reservadas podem ser mais economicas.', 2),
  ('73000000-0000-4000-8000-000000000275', '62000000-0000-4000-8000-000000000069', 'Maquinas virtuais tradicionais nunca podem ser utilizadas para cargas de trabalho constantes e previsiveis.', false, 'Incorreta. Maquinas virtuais tradicionais sao frequentemente a escolha mais adequada justamente para cargas de trabalho constantes e previsiveis.', 3),
  ('73000000-0000-4000-8000-000000000276', '62000000-0000-4000-8000-000000000069', 'A escolha entre os dois modelos nao tem qualquer impacto financeiro, sendo irrelevante para a decisao da empresa.', false, 'Incorreta. A escolha entre os dois modelos tem impacto financeiro significativo, especialmente para cargas de trabalho constantes.', 4),
  ('73000000-0000-4000-8000-000000000277', '62000000-0000-4000-8000-000000000070', 'Manter a arquitetura monolitica original em um unico servidor fisico dedicado, sem qualquer divisao em funcoes.', false, 'Incorreta. Manter a arquitetura monolitica original contraria o objetivo da equipe de migrar para funcoes independentes orientadas a eventos.', 1),
  ('73000000-0000-4000-8000-000000000278', '62000000-0000-4000-8000-000000000070', 'Migrar cada funcao independente para uma maquina virtual dedicada, sempre ligada, independentemente da frequencia dos eventos.', false, 'Incorreta. Manter maquinas virtuais sempre ligadas para funcoes esporadicas geraria custo desnecessario e nao aproveitaria o modelo orientado a eventos.', 2),
  ('73000000-0000-4000-8000-000000000279', '62000000-0000-4000-8000-000000000070', 'Adotar serverless computing para cada funcao independente, aproveitando o acionamento automatico por eventos e o escalonamento sob demanda.', true, 'Correta. O serverless computing e ideal para funcoes independentes acionadas por eventos, com escalonamento automatico sob demanda.', 3),
  ('73000000-0000-4000-8000-000000000280', '62000000-0000-4000-8000-000000000070', 'Construir um novo datacenter fisico exclusivamente para hospedar as novas funcoes independentes.', false, 'Incorreta. Construir um novo datacenter fisico para hospedar funcoes orientadas a eventos seria um investimento desproporcional e ineficiente.', 4),
  ('73000000-0000-4000-8000-000000000281', '62000000-0000-4000-8000-000000000071', 'A capacidade de um sistema processar grandes volumes de dados em pouco tempo.', false, 'Incorreta. Processar grandes volumes de dados rapidamente esta mais relacionado a desempenho e escalabilidade do que a alta disponibilidade.', 1),
  ('73000000-0000-4000-8000-000000000282', '62000000-0000-4000-8000-000000000071', 'A capacidade de um sistema permanecer operacional e acessivel por um periodo maximo de tempo, minimizando interrupcoes.', true, 'Correta. Alta disponibilidade significa manter o sistema operacional e acessivel pelo maior tempo possivel, minimizando interrupcoes.', 2),
  ('73000000-0000-4000-8000-000000000283', '62000000-0000-4000-8000-000000000071', 'A capacidade de reduzir o custo de operacao de uma aplicacao na nuvem.', false, 'Incorreta. Reducao de custo operacional nao e o conceito central de alta disponibilidade, embora possa ser um efeito colateral de um bom design.', 3),
  ('73000000-0000-4000-8000-000000000284', '62000000-0000-4000-8000-000000000071', 'A capacidade de um sistema ser acessado exclusivamente por administradores autorizados.', false, 'Incorreta. Restringir o acesso apenas a administradores esta relacionado a seguranca e controle de acesso, nao a disponibilidade.', 4),
  ('73000000-0000-4000-8000-000000000285', '62000000-0000-4000-8000-000000000072', 'Por meio de um Acordo de Nivel de Servico (SLA), que estabelece um percentual minimo garantido de tempo de atividade.', true, 'Correta. O SLA estabelece contratualmente o percentual minimo garantido de tempo de atividade de um servico em nuvem.', 1),
  ('73000000-0000-4000-8000-000000000286', '62000000-0000-4000-8000-000000000072', 'Por meio de um manual de instalacao de hardware fornecido junto ao contrato.', false, 'Incorreta. Um manual de instalacao de hardware nao expressa garantias contratuais de disponibilidade de um servico.', 2),
  ('73000000-0000-4000-8000-000000000287', '62000000-0000-4000-8000-000000000072', 'Por meio da quantidade de funcionarios alocados no suporte tecnico do provedor.', false, 'Incorreta. A quantidade de funcionarios do suporte tecnico nao e a forma pela qual a disponibilidade e expressa contratualmente.', 3),
  ('73000000-0000-4000-8000-000000000288', '62000000-0000-4000-8000-000000000072', 'Por meio de uma garantia de que o servico nunca sofrera qualquer tipo de manutencao.', false, 'Incorreta. Nenhum provedor garante ausencia total de manutencao; SLAs geralmente preveem janelas de manutencao planejada.', 4),
  ('73000000-0000-4000-8000-000000000289', '62000000-0000-4000-8000-000000000073', 'Concentrar todos os recursos em um unico servidor fisico, sem qualquer redundancia.', false, 'Incorreta. Concentrar tudo em um unico servidor fisico, sem redundancia, cria um ponto unico de falha, reduzindo a disponibilidade.', 1),
  ('73000000-0000-4000-8000-000000000290', '62000000-0000-4000-8000-000000000073', 'Reduzir o numero de replicas da aplicacao para simplificar a arquitetura.', false, 'Incorreta. Reduzir o numero de replicas normalmente diminui, e nao aumenta, a resiliencia e a disponibilidade da aplicacao.', 2),
  ('73000000-0000-4000-8000-000000000291', '62000000-0000-4000-8000-000000000073', 'Desativar mecanismos automaticos de failover para evitar custos adicionais.', false, 'Incorreta. Desativar mecanismos de failover reduz a capacidade do sistema de se recuperar automaticamente de falhas, prejudicando a disponibilidade.', 3),
  ('73000000-0000-4000-8000-000000000292', '62000000-0000-4000-8000-000000000073', 'Distribuir a aplicacao em multiplas instancias redundantes, muitas vezes em diferentes zonas ou regioes, para reduzir pontos unicos de falha.', true, 'Correta. Distribuir a aplicacao em multiplas instancias redundantes, em diferentes zonas ou regioes, aumenta a alta disponibilidade.', 4),
  ('73000000-0000-4000-8000-000000000293', '62000000-0000-4000-8000-000000000074', 'Elasticidade, pois o sistema aumentou automaticamente sua capacidade de processamento.', false, 'Incorreta. Elasticidade esta relacionada ao ajuste automatico de capacidade conforme a demanda, nao ao redirecionamento de trafego apos uma falha.', 1),
  ('73000000-0000-4000-8000-000000000294', '62000000-0000-4000-8000-000000000074', 'Consumo baseado no uso, pois o cliente paga apenas pelo servidor que continuou funcionando.', false, 'Incorreta. O cenario nao trata de cobranca por consumo, mas sim de continuidade do servico diante de uma falha.', 2),
  ('73000000-0000-4000-8000-000000000295', '62000000-0000-4000-8000-000000000074', 'Redundancia com failover automatico, permitindo que o trafego seja redirecionado para outro servidor saudavel sem interrupcao perceptivel.', true, 'Correta. O redirecionamento automatico de trafego para um servidor saudavel apos uma falha e um exemplo de redundancia com failover.', 3),
  ('73000000-0000-4000-8000-000000000296', '62000000-0000-4000-8000-000000000074', 'Responsabilidade compartilhada, pois o cliente e o provedor dividiram a tarefa de corrigir o servidor com falha.', false, 'Incorreta. O modelo de responsabilidade compartilhada trata da divisao de tarefas de seguranca, nao do redirecionamento de trafego durante falhas.', 4),
  ('73000000-0000-4000-8000-000000000297', '62000000-0000-4000-8000-000000000075', 'Hospedar a aplicacao em uma unica zona de disponibilidade, mas com um servidor de backup fisico guardado localmente.', false, 'Incorreta. Depender de um servidor de backup fisico local nao garante continuidade automatica do servico em caso de falha completa da zona.', 1),
  ('73000000-0000-4000-8000-000000000298', '62000000-0000-4000-8000-000000000075', 'Distribuir a aplicacao entre multiplas zonas de disponibilidade dentro da mesma regiao, garantindo que a falha de uma zona nao interrompa o servico.', true, 'Correta. Distribuir a aplicacao entre multiplas zonas de disponibilidade protege contra a falha completa de uma unica zona.', 2),
  ('73000000-0000-4000-8000-000000000299', '62000000-0000-4000-8000-000000000075', 'Reduzir o numero de instancias da aplicacao para simplificar o monitoramento durante falhas.', false, 'Incorreta. Reduzir o numero de instancias diminui a resiliencia do sistema, o oposto do que se busca para alta disponibilidade.', 3),
  ('73000000-0000-4000-8000-000000000300', '62000000-0000-4000-8000-000000000075', 'Depender exclusivamente de backups manuais realizados uma vez por semana.', false, 'Incorreta. Backups manuais semanais nao garantem disponibilidade continua durante uma falha, pois nao oferecem failover automatico.', 4),
  ('73000000-0000-4000-8000-000000000301', '62000000-0000-4000-8000-000000000076', 'Realizar todas as atualizacoes simultaneamente em todas as instancias, mesmo que isso derrube o servico por completo temporariamente.', false, 'Incorreta. Atualizar todas as instancias simultaneamente aumenta o risco de indisponibilidade total do servico durante o processo.', 1),
  ('73000000-0000-4000-8000-000000000302', '62000000-0000-4000-8000-000000000076', 'Parar de realizar atualizacoes de software para evitar qualquer risco de indisponibilidade.', false, 'Incorreta. Parar de realizar atualizacoes de software nao e uma solucao viavel, pois compromete a seguranca e a evolucao do sistema.', 2),
  ('73000000-0000-4000-8000-000000000303', '62000000-0000-4000-8000-000000000076', 'Notificar os usuarios por e-mail sobre a indisponibilidade, sem alterar o processo tecnico de atualizacao.', false, 'Incorreta. Apenas notificar os usuarios nao resolve o problema tecnico de indisponibilidade durante as atualizacoes.', 3),
  ('73000000-0000-4000-8000-000000000304', '62000000-0000-4000-8000-000000000076', 'Adotar implantacoes graduais (rolling updates), atualizando instancias por partes, mantendo outras instancias ativas para continuar atendendo aos usuarios.', true, 'Correta. Implantacoes graduais permitem atualizar o sistema mantendo parte das instancias ativas, reduzindo a indisponibilidade percebida pelos usuarios.', 4),
  ('73000000-0000-4000-8000-000000000305', '62000000-0000-4000-8000-000000000077', 'Uso de redundancia em multiplas instancias, monitoramento continuo de saude do sistema e failover automatico em caso de falha.', true, 'Correta. A combinacao de redundancia, monitoramento continuo e failover automatico e essencial para garantir alta disponibilidade em aplicacoes criticas.', 1),
  ('73000000-0000-4000-8000-000000000306', '62000000-0000-4000-8000-000000000077', 'Hospedagem em uma unica maquina virtual robusta, sem qualquer redundancia adicional.', false, 'Incorreta. Uma unica maquina virtual, sem redundancia, representa um ponto unico de falha, incompativel com o objetivo de alta disponibilidade.', 2),
  ('73000000-0000-4000-8000-000000000307', '62000000-0000-4000-8000-000000000077', 'Realizacao de backups manuais semanais como unica medida de protecao contra falhas.', false, 'Incorreta. Backups manuais semanais nao garantem continuidade imediata do servico em caso de falha, apenas recuperacao posterior de dados.', 3),
  ('73000000-0000-4000-8000-000000000308', '62000000-0000-4000-8000-000000000077', 'Dependencia exclusiva de um unico data center, sem qualquer distribuicao geografica.', false, 'Incorreta. Depender de um unico datacenter, sem distribuicao geografica, aumenta o risco de indisponibilidade em caso de falha regional.', 4),
  ('73000000-0000-4000-8000-000000000309', '62000000-0000-4000-8000-000000000078', 'Ambas as arquiteturas oferecem exatamente o mesmo nivel de disponibilidade, independentemente do numero de instancias.', false, 'Incorreta. O nivel de disponibilidade varia significativamente conforme a presenca ou ausencia de redundancia na arquitetura.', 1),
  ('73000000-0000-4000-8000-000000000310', '62000000-0000-4000-8000-000000000078', 'Uma unica instancia de servidor sempre oferece maior disponibilidade do que multiplas instancias redundantes.', false, 'Incorreta. E o contrario: multiplas instancias redundantes tendem a oferecer maior disponibilidade do que uma unica instancia.', 2),
  ('73000000-0000-4000-8000-000000000311', '62000000-0000-4000-8000-000000000078', 'Multiplas instancias redundantes tendem a oferecer maior disponibilidade, pois a falha de uma instancia nao necessariamente interrompe o servico.', true, 'Correta. Multiplas instancias redundantes reduzem o impacto da falha de uma unica instancia, aumentando a disponibilidade geral do servico.', 3),
  ('73000000-0000-4000-8000-000000000312', '62000000-0000-4000-8000-000000000078', 'O numero de instancias nao tem qualquer relacao com o nivel de disponibilidade de uma aplicacao.', false, 'Incorreta. O numero de instancias tem relacao direta com o nivel de disponibilidade, pois afeta a resiliencia a falhas.', 4),
  ('73000000-0000-4000-8000-000000000313', '62000000-0000-4000-8000-000000000079', 'Os dois designs apresentam exatamente a mesma resiliencia diante de qualquer tipo de falha, incluindo falhas regionais completas.', false, 'Incorreta. Os dois designs apresentam niveis de resiliencia muito diferentes diante de falhas localizadas, embora ambos sejam vulneraveis a falhas regionais completas.', 1),
  ('73000000-0000-4000-8000-000000000314', '62000000-0000-4000-8000-000000000079', 'Nenhum dos dois designs, isoladamente, protege totalmente contra uma falha que afete a regiao inteira; para esse cenario, seria necessario considerar redundancia entre regioes diferentes.', true, 'Correta. Nenhum dos dois designs protege totalmente contra uma falha regional completa; isso exigiria redundancia entre regioes diferentes.', 2),
  ('73000000-0000-4000-8000-000000000315', '62000000-0000-4000-8000-000000000079', 'O primeiro design, com uma unica instancia, e mais resiliente do que o segundo, com multiplas zonas de disponibilidade.', false, 'Incorreta. O design com multiplas zonas de disponibilidade e geralmente mais resiliente do que uma unica instancia em uma unica zona.', 3),
  ('73000000-0000-4000-8000-000000000316', '62000000-0000-4000-8000-000000000079', 'Distribuir a aplicacao em multiplas zonas de disponibilidade elimina totalmente qualquer risco de indisponibilidade, incluindo falhas regionais.', false, 'Incorreta. Distribuir a aplicacao em multiplas zonas nao elimina totalmente o risco de falhas regionais completas, apenas reduz riscos localizados.', 4),
  ('73000000-0000-4000-8000-000000000317', '62000000-0000-4000-8000-000000000080', 'Manter a aplicacao em uma unica zona de disponibilidade, confiando exclusivamente na redundancia interna dessa zona.', false, 'Incorreta. Uma unica zona de disponibilidade nao protege contra uma falha que afete a regiao inteira onde essa zona esta localizada.', 1),
  ('73000000-0000-4000-8000-000000000318', '62000000-0000-4000-8000-000000000080', 'Realizar backups mensais dos dados, sem qualquer redundancia ativa da aplicacao em execucao.', false, 'Incorreta. Backups mensais sem redundancia ativa nao garantem continuidade imediata do servico durante uma falha regional completa.', 2),
  ('73000000-0000-4000-8000-000000000319', '62000000-0000-4000-8000-000000000080', 'Distribuir a aplicacao apenas entre multiplas zonas de disponibilidade dentro da mesma regiao, sem considerar outras regioes.', false, 'Incorreta. Multiplas zonas dentro da mesma regiao nao protegem contra uma falha que afete toda a regiao simultaneamente.', 3),
  ('73000000-0000-4000-8000-000000000320', '62000000-0000-4000-8000-000000000080', 'Implementar uma arquitetura com redundancia entre multiplas regioes geograficamente distantes, permitindo que a aplicacao continue operando mesmo que uma regiao inteira fique indisponivel.', true, 'Correta. A redundancia entre multiplas regioes geograficamente distantes protege contra a indisponibilidade completa de uma unica regiao.', 4),
  ('73000000-0000-4000-8000-000000000321', '62000000-0000-4000-8000-000000000081', 'A capacidade de um sistema aumentar ou diminuir sua capacidade de processamento para atender as variacoes de demanda.', true, 'Correta. Escalabilidade refere-se a capacidade do sistema de ajustar sua capacidade de processamento conforme a demanda.', 1),
  ('73000000-0000-4000-8000-000000000322', '62000000-0000-4000-8000-000000000081', 'A capacidade de um sistema nunca sofrer qualquer tipo de falha ou interrupcao.', false, 'Incorreta. Nunca sofrer falhas esta mais relacionado ao conceito de confiabilidade e disponibilidade do que ao de escalabilidade.', 2),
  ('73000000-0000-4000-8000-000000000323', '62000000-0000-4000-8000-000000000081', 'A capacidade de um sistema ser acessado exclusivamente por meio de dispositivos moveis.', false, 'Incorreta. Escalabilidade nao esta relacionada ao tipo de dispositivo utilizado para acessar o sistema.', 3),
  ('73000000-0000-4000-8000-000000000324', '62000000-0000-4000-8000-000000000081', 'A capacidade de reduzir permanentemente o custo de um servico, independentemente da demanda.', false, 'Incorreta. Escalabilidade nao garante reducao permanente de custo; ela permite ajustar recursos conforme a demanda, o que pode aumentar ou reduzir custos.', 4),
  ('73000000-0000-4000-8000-000000000325', '62000000-0000-4000-8000-000000000082', 'A adicao de novas instancias identicas para dividir a carga de trabalho entre elas.', false, 'Incorreta. Adicionar novas instancias para dividir a carga descreve a escalabilidade horizontal (scale out), nao a vertical.', 1),
  ('73000000-0000-4000-8000-000000000326', '62000000-0000-4000-8000-000000000082', 'O aumento da capacidade de uma unica instancia existente, como adicionar mais memoria ou poder de processamento a um servidor.', true, 'Correta. Escalabilidade vertical envolve aumentar a capacidade de uma instancia existente, como adicionar mais recursos a um servidor.', 2),
  ('73000000-0000-4000-8000-000000000327', '62000000-0000-4000-8000-000000000082', 'A remocao completa de todos os recursos computacionais de um sistema.', false, 'Incorreta. Remover completamente os recursos computacionais nao e uma forma de escalabilidade, mas sim de desligamento do sistema.', 3),
  ('73000000-0000-4000-8000-000000000328', '62000000-0000-4000-8000-000000000082', 'A distribuicao geografica de uma aplicacao entre diferentes regioes do mundo.', false, 'Incorreta. A distribuicao geografica esta mais relacionada a disponibilidade e resiliencia do que a escalabilidade vertical especificamente.', 4),
  ('73000000-0000-4000-8000-000000000329', '62000000-0000-4000-8000-000000000083', 'O aumento da capacidade de processamento de uma unica instancia, adicionando mais memoria a ela.', false, 'Incorreta. Aumentar a capacidade de uma unica instancia adicionando mais memoria descreve a escalabilidade vertical, nao a horizontal.', 1),
  ('73000000-0000-4000-8000-000000000330', '62000000-0000-4000-8000-000000000083', 'A reducao do numero de instancias de um sistema para simplificar sua arquitetura.', false, 'Incorreta. Reduzir o numero de instancias nao caracteriza escalabilidade horizontal, que se refere a adicao de novas instancias.', 2),
  ('73000000-0000-4000-8000-000000000331', '62000000-0000-4000-8000-000000000083', 'A adicao de novas instancias identicas para distribuir a carga de trabalho entre multiplos servidores.', true, 'Correta. Escalabilidade horizontal envolve adicionar novas instancias identicas para distribuir a carga entre multiplos servidores.', 3),
  ('73000000-0000-4000-8000-000000000332', '62000000-0000-4000-8000-000000000083', 'A substituicao completa de um sistema por outro totalmente diferente.', false, 'Incorreta. Substituir completamente um sistema por outro diferente nao e o conceito de escalabilidade horizontal.', 4),
  ('73000000-0000-4000-8000-000000000333', '62000000-0000-4000-8000-000000000084', 'Escalabilidade vertical, pois a capacidade de um unico servidor esta sendo aumentada.', false, 'Incorreta. Escalabilidade vertical envolveria aumentar a capacidade de um unico servidor existente, e nao adicionar novos servidores.', 1),
  ('73000000-0000-4000-8000-000000000334', '62000000-0000-4000-8000-000000000084', 'Elasticidade automatica, pois os recursos estao sendo reduzidos automaticamente apos o pico.', false, 'Incorreta. O cenario descreve a adicao de recursos, nao a reducao automatica, o que nao caracteriza especificamente elasticidade nesse contexto.', 2),
  ('73000000-0000-4000-8000-000000000335', '62000000-0000-4000-8000-000000000084', 'Alta disponibilidade, pois o objetivo principal e evitar qualquer interrupcao do servico.', false, 'Incorreta. Embora relacionado, o cenario descreve especificamente uma acao de escalabilidade, e nao diretamente o conceito de alta disponibilidade.', 3),
  ('73000000-0000-4000-8000-000000000336', '62000000-0000-4000-8000-000000000084', 'Escalabilidade horizontal, pois novos servidores identicos estao sendo adicionados para distribuir a carga de trabalho.', true, 'Correta. Adicionar novos servidores identicos para distribuir a carga de trabalho e um exemplo classico de escalabilidade horizontal.', 4),
  ('73000000-0000-4000-8000-000000000337', '62000000-0000-4000-8000-000000000085', 'Escalabilidade vertical, pois a capacidade de um unico servidor existente esta sendo aumentada.', true, 'Correta. Aumentar a capacidade de processamento e memoria de um servidor existente caracteriza a escalabilidade vertical.', 1),
  ('73000000-0000-4000-8000-000000000338', '62000000-0000-4000-8000-000000000085', 'Escalabilidade horizontal, pois novos servidores estao sendo adicionados ao ambiente.', false, 'Incorreta. Escalabilidade horizontal envolveria adicionar novos servidores, o que nao e o caso descrito no cenario.', 2),
  ('73000000-0000-4000-8000-000000000339', '62000000-0000-4000-8000-000000000085', 'Redundancia geografica, pois os dados estao sendo replicados entre diferentes regioes.', false, 'Incorreta. O cenario nao menciona replicacao de dados entre regioes diferentes, apenas o aumento de capacidade de um servidor.', 3),
  ('73000000-0000-4000-8000-000000000340', '62000000-0000-4000-8000-000000000085', 'Consumo baseado no uso, pois o pagamento passa a ser feito exclusivamente por hora de uso.', false, 'Incorreta. O cenario trata de uma decisao de arquitetura de escalabilidade, nao especificamente do modelo de cobranca por consumo.', 4),
  ('73000000-0000-4000-8000-000000000341', '62000000-0000-4000-8000-000000000086', 'A cor do painel de controle utilizado para gerenciar os servidores.', false, 'Incorreta. Aspectos esteticos do painel de controle nao tem relacao com a decisao tecnica entre escalabilidade vertical e horizontal.', 1),
  ('73000000-0000-4000-8000-000000000342', '62000000-0000-4000-8000-000000000086', 'O numero de feriados no calendario da empresa durante o ano corrente.', false, 'Incorreta. O numero de feriados no calendario da empresa nao e um fator tecnico relevante para essa decisao de arquitetura.', 2),
  ('73000000-0000-4000-8000-000000000343', '62000000-0000-4000-8000-000000000086', 'Os limites tecnicos de capacidade de uma unica maquina e a necessidade de crescimento futuro alem desses limites.', true, 'Correta. Avaliar os limites tecnicos de uma unica maquina frente a necessidade de crescimento futuro e essencial para essa decisao.', 3),
  ('73000000-0000-4000-8000-000000000344', '62000000-0000-4000-8000-000000000086', 'A quantidade de vagas de estacionamento disponiveis no escritorio da empresa.', false, 'Incorreta. A quantidade de vagas de estacionamento nao tem qualquer relacao com decisoes tecnicas de escalabilidade de sistemas.', 4),
  ('73000000-0000-4000-8000-000000000345', '62000000-0000-4000-8000-000000000087', 'Escalabilidade vertical exclusivamente, aumentando indefinidamente a capacidade de um unico servidor.', false, 'Incorreta. A escalabilidade vertical exclusiva e limitada pela capacidade maxima que uma unica maquina pode atingir, o que restringe o crescimento no longo prazo.', 1),
  ('73000000-0000-4000-8000-000000000346', '62000000-0000-4000-8000-000000000087', 'Escalabilidade horizontal, adicionando novas instancias conforme necessario, sem depender dos limites fisicos de uma unica maquina.', true, 'Correta. A escalabilidade horizontal permite adicionar novas instancias conforme necessario, sem os limites fisicos de uma unica maquina.', 2),
  ('73000000-0000-4000-8000-000000000347', '62000000-0000-4000-8000-000000000087', 'Manter a capacidade fixa do servidor original, independentemente do crescimento do numero de usuarios.', false, 'Incorreta. Manter a capacidade fixa nao permitiria que a aplicacao suportasse o crescimento continuo esperado no numero de usuarios.', 3),
  ('73000000-0000-4000-8000-000000000348', '62000000-0000-4000-8000-000000000087', 'Reduzir a capacidade do servidor gradualmente a medida que o numero de usuarios aumenta.', false, 'Incorreta. Reduzir a capacidade do servidor a medida que o numero de usuarios aumenta seria o oposto do que a aplicacao precisa para crescer.', 4),
  ('73000000-0000-4000-8000-000000000349', '62000000-0000-4000-8000-000000000088', 'A escalabilidade vertical nao possui qualquer limite tecnico de capacidade, podendo crescer indefinidamente em uma unica maquina.', false, 'Incorreta. A escalabilidade vertical e sim limitada pela capacidade maxima que uma unica maquina fisica ou virtual pode atingir.', 1),
  ('73000000-0000-4000-8000-000000000350', '62000000-0000-4000-8000-000000000088', 'A escalabilidade horizontal e sempre mais simples de implementar do que a escalabilidade vertical, sem excecoes.', false, 'Incorreta. A escalabilidade horizontal pode exigir ajustes de arquitetura, como balanceamento de carga, nao sendo sempre mais simples de implementar.', 2),
  ('73000000-0000-4000-8000-000000000351', '62000000-0000-4000-8000-000000000088', 'Ambas as abordagens possuem exatamente os mesmos limites tecnicos de crescimento.', false, 'Incorreta. Os limites tecnicos de crescimento sao diferentes entre as duas abordagens, nao sendo equivalentes.', 3),
  ('73000000-0000-4000-8000-000000000352', '62000000-0000-4000-8000-000000000088', 'A escalabilidade vertical e limitada pela capacidade maxima de uma unica maquina, enquanto a escalabilidade horizontal pode, em teoria, continuar adicionando novas instancias.', true, 'Correta. A escalabilidade vertical e limitada pela capacidade de uma unica maquina, enquanto a horizontal pode continuar adicionando novas instancias.', 4),
  ('73000000-0000-4000-8000-000000000353', '62000000-0000-4000-8000-000000000089', 'A empresa deve migrar para uma estrategia de escalabilidade horizontal, distribuindo a carga entre multiplas instancias, ja que os limites da escalabilidade vertical estao sendo constantemente atingidos.', true, 'Correta. Migrar para escalabilidade horizontal e a estrategia mais adequada quando os limites da escalabilidade vertical sao constantemente atingidos.', 1),
  ('73000000-0000-4000-8000-000000000354', '62000000-0000-4000-8000-000000000089', 'A empresa deve continuar investindo exclusivamente em upgrades de hardware para o mesmo servidor, independentemente dos limites tecnicos ja observados.', false, 'Incorreta. Continuar investindo exclusivamente em upgrades de hardware nao resolve o problema, ja que ha um limite fisico para a escalabilidade vertical.', 2),
  ('73000000-0000-4000-8000-000000000355', '62000000-0000-4000-8000-000000000089', 'A empresa deve reduzir o numero de usuarios ativos para se adequar a capacidade atual do servidor principal.', false, 'Incorreta. Reduzir o numero de usuarios ativos limitaria artificialmente o crescimento do negocio, o que nao e uma solucao tecnica adequada.', 3),
  ('73000000-0000-4000-8000-000000000356', '62000000-0000-4000-8000-000000000089', 'A empresa deve abandonar completamente o uso de cloud computing e migrar para uma solucao totalmente on-premises.', false, 'Incorreta. Abandonar completamente a cloud computing nao resolve o problema de escalabilidade e eliminaria diversos outros beneficios da nuvem.', 4),
  ('73000000-0000-4000-8000-000000000357', '62000000-0000-4000-8000-000000000090', 'Utilizar exclusivamente escalabilidade vertical, aumentando a capacidade de um unico servidor sempre que necessario.', false, 'Incorreta. A escalabilidade vertical exclusiva e limitada pela capacidade maxima de uma unica maquina, o que nao atende a um crescimento sem limite claro.', 1),
  ('73000000-0000-4000-8000-000000000358', '62000000-0000-4000-8000-000000000090', 'Manter a capacidade fixa desde o inicio do projeto, sem qualquer possibilidade de ajuste futuro.', false, 'Incorreta. Manter a capacidade fixa desde o inicio impediria o sistema de suportar tanto os picos subitos quanto o crescimento constante esperado.', 2),
  ('73000000-0000-4000-8000-000000000359', '62000000-0000-4000-8000-000000000090', 'Projetar o sistema com escalabilidade horizontal desde o inicio, permitindo adicionar novas instancias tanto para picos subitos quanto para o crescimento constante ao longo do tempo.', true, 'Correta. Projetar o sistema com escalabilidade horizontal desde o inicio permite atender tanto a picos subitos quanto ao crescimento constante ao longo do tempo.', 3),
  ('73000000-0000-4000-8000-000000000360', '62000000-0000-4000-8000-000000000090', 'Reduzir a capacidade do sistema gradualmente para evitar custos com crescimento futuro.', false, 'Incorreta. Reduzir a capacidade do sistema gradualmente e o oposto do necessario para suportar um crescimento constante de usuarios.', 4),
  ('73000000-0000-4000-8000-000000000361', '62000000-0000-4000-8000-000000000091', 'A capacidade de um sistema nunca sofrer qualquer tipo de falha de hardware.', false, 'Incorreta. Nunca sofrer falhas de hardware esta mais relacionado a confiabilidade do que ao conceito de elasticidade.', 1),
  ('73000000-0000-4000-8000-000000000362', '62000000-0000-4000-8000-000000000091', 'A capacidade de um sistema ajustar automaticamente sua capacidade de recursos, aumentando ou reduzindo conforme a demanda em tempo real.', true, 'Correta. Elasticidade e o ajuste automatico da capacidade de recursos conforme a demanda em tempo real.', 2),
  ('73000000-0000-4000-8000-000000000363', '62000000-0000-4000-8000-000000000091', 'A capacidade de armazenar dados indefinidamente sem qualquer custo adicional.', false, 'Incorreta. Elasticidade nao esta relacionada ao armazenamento indefinido de dados sem custo, mas sim ao ajuste automatico de recursos.', 3),
  ('73000000-0000-4000-8000-000000000364', '62000000-0000-4000-8000-000000000091', 'A capacidade de um sistema ser acessado exclusivamente durante o horario comercial.', false, 'Incorreta. Elasticidade nao se refere a restricoes de horario de acesso ao sistema.', 4),
  ('73000000-0000-4000-8000-000000000365', '62000000-0000-4000-8000-000000000092', 'A elasticidade envolve o ajuste automatico e frequente dos recursos conforme a demanda muda em tempo real, enquanto a escalabilidade se refere a capacidade geral do sistema de crescer para suportar mais carga.', true, 'Correta. A elasticidade foca no ajuste automatico e dinamico conforme a demanda muda, enquanto a escalabilidade trata da capacidade geral de crescimento do sistema.', 1),
  ('73000000-0000-4000-8000-000000000366', '62000000-0000-4000-8000-000000000092', 'Nao existe qualquer diferenca entre os dois conceitos; eles sao exatamente sinonimos.', false, 'Incorreta. Embora relacionados, os dois conceitos possuem nuances diferentes e nao sao exatamente sinonimos.', 2),
  ('73000000-0000-4000-8000-000000000367', '62000000-0000-4000-8000-000000000092', 'A elasticidade se refere exclusivamente a seguranca dos dados, enquanto a escalabilidade se refere ao custo do servico.', false, 'Incorreta. Nenhum dos dois conceitos se refere exclusivamente a seguranca dos dados ou ao custo do servico.', 3),
  ('73000000-0000-4000-8000-000000000368', '62000000-0000-4000-8000-000000000092', 'A elasticidade so pode ser aplicada em ambientes on-premises, enquanto a escalabilidade e exclusiva da nuvem publica.', false, 'Incorreta. A elasticidade e uma caracteristica amplamente associada a cloud computing, incluindo ambientes de nuvem publica, e nao exclusiva de ambientes on-premises.', 4),
  ('73000000-0000-4000-8000-000000000369', '62000000-0000-4000-8000-000000000093', 'A contratacao manual de um novo servidor fisico a cada aumento de demanda.', false, 'Incorreta. A contratacao manual de um novo servidor fisico a cada aumento de demanda nao e uma implementacao de elasticidade, que exige automacao.', 1),
  ('73000000-0000-4000-8000-000000000370', '62000000-0000-4000-8000-000000000093', 'A assinatura de um contrato fixo de capacidade, sem qualquer possibilidade de ajuste automatico.', false, 'Incorreta. Um contrato fixo de capacidade, sem ajuste automatico, contraria justamente o conceito de elasticidade.', 2),
  ('73000000-0000-4000-8000-000000000371', '62000000-0000-4000-8000-000000000093', 'A desativacao permanente de recursos apos o primeiro pico de demanda registrado.', false, 'Incorreta. Desativar recursos permanentemente apos um unico pico nao permite o ajuste continuo caracteristico da elasticidade.', 3),
  ('73000000-0000-4000-8000-000000000372', '62000000-0000-4000-8000-000000000093', 'O escalonamento automatico (auto-scaling), que adiciona ou remove recursos automaticamente com base em metricas de uso predefinidas.', true, 'Correta. O escalonamento automatico ajusta os recursos com base em metricas de uso, sendo o mecanismo tipico de implementacao da elasticidade.', 4),
  ('73000000-0000-4000-8000-000000000373', '62000000-0000-4000-8000-000000000094', 'Manter uma capacidade fixa dimensionada para o pico maximo esperado durante todo o ano, mesmo fora dos periodos de venda.', false, 'Incorreta. Manter capacidade fixa dimensionada para o pico maximo durante todo o ano geraria custo desnecessario fora dos periodos de venda.', 1),
  ('73000000-0000-4000-8000-000000000374', '62000000-0000-4000-8000-000000000094', 'Desligar completamente a plataforma durante os periodos de baixa demanda, impedindo qualquer acesso dos usuarios.', false, 'Incorreta. Desligar completamente a plataforma impediria o acesso legitimo dos usuarios, o que nao e o objetivo do cenario.', 2),
  ('73000000-0000-4000-8000-000000000375', '62000000-0000-4000-8000-000000000094', 'Configurar regras de escalonamento automatico que aumentem rapidamente a capacidade durante o pico de vendas e a reduzam automaticamente logo depois.', true, 'Correta. O escalonamento automatico permite aumentar e reduzir a capacidade rapidamente, conforme o padrao de pico e queda do trafego.', 3),
  ('73000000-0000-4000-8000-000000000376', '62000000-0000-4000-8000-000000000094', 'Contratar um numero fixo de servidores fisicos dedicados exclusivamente a essa plataforma, sem qualquer possibilidade de ajuste.', false, 'Incorreta. Um numero fixo de servidores fisicos dedicados nao permite o ajuste dinamico necessario para lidar com picos extremos e breves.', 4),
  ('73000000-0000-4000-8000-000000000377', '62000000-0000-4000-8000-000000000095', 'A eliminacao total de qualquer custo relacionado ao uso de recursos de nuvem, independentemente do trafego.', false, 'Incorreta. O uso de recursos de nuvem continua gerando custos proporcionais ao consumo; a elasticidade otimiza, mas nao elimina totalmente os custos.', 1),
  ('73000000-0000-4000-8000-000000000378', '62000000-0000-4000-8000-000000000095', 'A otimizacao de custos, pois os recursos aumentam durante os horarios de pico e diminuem automaticamente durante periodos de baixo trafego, como a madrugada.', true, 'Correta. O auto-scaling otimiza custos ao ajustar automaticamente os recursos conforme os horarios de pico e baixa demanda ao longo do dia.', 2),
  ('73000000-0000-4000-8000-000000000379', '62000000-0000-4000-8000-000000000095', 'A garantia de que nunca ocorrera qualquer tipo de falha de seguranca na aplicacao.', false, 'Incorreta. A elasticidade nao esta diretamente relacionada a garantia de ausencia de falhas de seguranca na aplicacao.', 3),
  ('73000000-0000-4000-8000-000000000380', '62000000-0000-4000-8000-000000000095', 'A obrigatoriedade de manter sempre a mesma quantidade de recursos, independentemente do horario do dia.', false, 'Incorreta. Manter sempre a mesma quantidade de recursos, independentemente do horario, contraria justamente o objetivo do auto-scaling configurado.', 4),
  ('73000000-0000-4000-8000-000000000381', '62000000-0000-4000-8000-000000000096', 'Remover completamente as regras de escalonamento automatico, retornando a capacidade fixa manual.', false, 'Incorreta. Remover completamente o escalonamento automatico eliminaria os beneficios da elasticidade, retornando a uma capacidade fixa menos eficiente.', 1),
  ('73000000-0000-4000-8000-000000000382', '62000000-0000-4000-8000-000000000096', 'Aumentar o intervalo de tempo entre as verificacoes de metricas de uso, tornando o sistema menos responsivo.', false, 'Incorreta. Aumentar o intervalo entre verificacoes tornaria o sistema ainda menos responsivo a mudancas de demanda, piorando o problema.', 2),
  ('73000000-0000-4000-8000-000000000383', '62000000-0000-4000-8000-000000000096', 'Ignorar o problema, ja que a velocidade de resposta do escalonamento automatico nao pode ser ajustada de forma alguma.', false, 'Incorreta. E possivel, sim, ajustar diversos parametros do escalonamento automatico para melhorar sua capacidade de resposta.', 3),
  ('73000000-0000-4000-8000-000000000384', '62000000-0000-4000-8000-000000000096', 'Revisar e ajustar os limites (thresholds) das metricas que disparam o escalonamento, antecipando a adicao de recursos antes que o pico afete significativamente o desempenho.', true, 'Correta. Ajustar os limites das metricas que disparam o escalonamento pode antecipar a adicao de recursos, melhorando a resposta elastica do sistema.', 4),
  ('73000000-0000-4000-8000-000000000385', '62000000-0000-4000-8000-000000000097', 'A capacidade de aumentar rapidamente os recursos durante o evento e reduzi-los automaticamente logo depois, evitando custos desnecessarios fora das transmissoes.', true, 'Correta. Aumentar rapidamente os recursos durante o evento e reduzi-los depois evita custos desnecessarios fora dos periodos de transmissao.', 1),
  ('73000000-0000-4000-8000-000000000386', '62000000-0000-4000-8000-000000000097', 'A obrigatoriedade de manter a mesma capacidade maxima 24 horas por dia, mesmo sem transmissoes ao vivo em andamento.', false, 'Incorreta. Manter a capacidade maxima 24 horas por dia geraria custo elevado e desnecessario durante os periodos sem transmissoes ao vivo.', 2),
  ('73000000-0000-4000-8000-000000000387', '62000000-0000-4000-8000-000000000097', 'A necessidade de comprar servidores fisicos adicionais antes de cada evento esportivo transmitido.', false, 'Incorreta. Comprar servidores fisicos adicionais antes de cada evento nao e uma abordagem elastica nem eficiente para picos esporadicos.', 3),
  ('73000000-0000-4000-8000-000000000388', '62000000-0000-4000-8000-000000000097', 'A exigencia de reduzir permanentemente a qualidade do video para economizar recursos durante os eventos.', false, 'Incorreta. Reduzir permanentemente a qualidade do video prejudicaria a experiencia do usuario e nao e uma solucao relacionada a elasticidade.', 4),
  ('73000000-0000-4000-8000-000000000389', '62000000-0000-4000-8000-000000000098', 'Um sistema com capacidade fixa reduz automaticamente seus custos assim que o trafego cai, assim como um sistema elastico.', false, 'Incorreta. Um sistema com capacidade fixa nao ajusta automaticamente os custos diante de mudancas no trafego, ao contrario de um sistema elastico.', 1),
  ('73000000-0000-4000-8000-000000000390', '62000000-0000-4000-8000-000000000098', 'Um sistema com elasticidade automatica mantem sempre a mesma quantidade de recursos, independentemente da queda no trafego.', false, 'Incorreta. Um sistema com elasticidade automatica ajusta seus recursos conforme a demanda, nao mantendo sempre a mesma quantidade fixa.', 2),
  ('73000000-0000-4000-8000-000000000391', '62000000-0000-4000-8000-000000000098', 'Um sistema com elasticidade automatica tende a reduzir os recursos utilizados apos a queda no trafego, reduzindo custos, enquanto um sistema com capacidade fixa continua com os mesmos recursos e custos.', true, 'Correta. Sistemas elasticos reduzem recursos e custos diante de quedas no trafego, enquanto sistemas de capacidade fixa mantem os mesmos custos.', 3),
  ('73000000-0000-4000-8000-000000000392', '62000000-0000-4000-8000-000000000098', 'Nao ha qualquer diferenca de comportamento entre os dois sistemas diante de uma queda no trafego.', false, 'Incorreta. Ha uma diferenca significativa de comportamento entre os dois sistemas diante de mudancas no volume de trafego.', 4),
  ('73000000-0000-4000-8000-000000000393', '62000000-0000-4000-8000-000000000099', 'Concluir imediatamente que a elasticidade automatica e sempre uma ma escolha e deve ser removida sem qualquer investigacao adicional.', false, 'Incorreta. Remover a elasticidade automatica sem investigar a causa do problema pode eliminar beneficios legitimos que ela oferece em outros cenarios.', 1),
  ('73000000-0000-4000-8000-000000000394', '62000000-0000-4000-8000-000000000099', 'Revisar as metricas e os limites configurados para o escalonamento automatico, verificando se estao causando adicao excessiva de recursos mesmo sem necessidade real, o que pode indicar uma configuracao inadequada.', true, 'Correta. Revisar as metricas e limites configurados ajuda a identificar se ha adicao excessiva de recursos por uma configuracao inadequada.', 2),
  ('73000000-0000-4000-8000-000000000395', '62000000-0000-4000-8000-000000000099', 'Assumir que o aumento de custo e inevitavel e nao pode ser investigado ou corrigido de forma alguma.', false, 'Incorreta. O aumento de custo pode, sim, ser investigado e corrigido por meio da revisao das configuracoes de escalonamento automatico.', 3),
  ('73000000-0000-4000-8000-000000000396', '62000000-0000-4000-8000-000000000099', 'Migrar imediatamente para uma capacidade totalmente fixa, sem qualquer analise previa das causas do aumento de custo.', false, 'Incorreta. Migrar para capacidade fixa sem investigar a causa do problema pode eliminar a flexibilidade de custos que a elasticidade oferece em outros momentos.', 4),
  ('73000000-0000-4000-8000-000000000397', '62000000-0000-4000-8000-000000000100', 'Configurar apenas uma capacidade fixa baseada exclusivamente no padrao de trafego previsivel do horario comercial.', false, 'Incorreta. Uma capacidade fixa baseada apenas no padrao previsivel nao seria suficiente para lidar com os picos imprevisiveis causados por campanhas virais.', 1),
  ('73000000-0000-4000-8000-000000000398', '62000000-0000-4000-8000-000000000100', 'Ignorar completamente os picos imprevisiveis causados por campanhas de marketing, tratando-os como eventos irrelevantes.', false, 'Incorreta. Ignorar picos imprevisiveis de trafego pode causar indisponibilidade ou lentidao significativa durante campanhas de marketing bem-sucedidas.', 2),
  ('73000000-0000-4000-8000-000000000399', '62000000-0000-4000-8000-000000000100', 'Utilizar exclusivamente escalabilidade vertical manual, ajustada uma vez por semana, para lidar com ambos os padroes de trafego.', false, 'Incorreta. Ajustes manuais realizados apenas uma vez por semana sao muito lentos para responder a picos imprevisiveis de trafego em tempo real.', 3),
  ('73000000-0000-4000-8000-000000000400', '62000000-0000-4000-8000-000000000100', 'Combinar uma arquitetura escalavel horizontalmente com regras de escalonamento automatico (elasticidade), permitindo ajustes tanto para variacoes previsiveis quanto para picos imprevisiveis de trafego.', true, 'Correta. Combinar escalabilidade horizontal com escalonamento automatico permite responder tanto a variacoes previsiveis quanto a picos imprevisiveis de trafego.', 4),
  ('73000000-0000-4000-8000-000000000401', '62000000-0000-4000-8000-000000000101', 'A capacidade de um sistema se recuperar de falhas e continuar funcionando conforme o esperado ao longo do tempo.', true, 'Correta. Confiabilidade e a capacidade de um sistema se recuperar de falhas e continuar funcionando conforme esperado.', 1),
  ('73000000-0000-4000-8000-000000000402', '62000000-0000-4000-8000-000000000101', 'A capacidade de um sistema reduzir permanentemente seus custos operacionais, independentemente de falhas.', false, 'Incorreta. Reducao permanente de custos nao e o conceito central de confiabilidade, embora sistemas confiaveis possam trazer beneficios financeiros indiretos.', 2),
  ('73000000-0000-4000-8000-000000000403', '62000000-0000-4000-8000-000000000101', 'A capacidade de um sistema ser acessado exclusivamente por administradores de rede.', false, 'Incorreta. Confiabilidade nao esta relacionada a restricao de acesso exclusivo a administradores de rede.', 3),
  ('73000000-0000-4000-8000-000000000404', '62000000-0000-4000-8000-000000000101', 'A capacidade de um sistema aumentar automaticamente sua capacidade de processamento durante picos de demanda.', false, 'Incorreta. Aumentar automaticamente a capacidade durante picos de demanda esta mais relacionado ao conceito de elasticidade do que ao de confiabilidade.', 4),
  ('73000000-0000-4000-8000-000000000405', '62000000-0000-4000-8000-000000000102', 'A eliminacao completa de qualquer tipo de backup ou plano de recuperacao de dados.', false, 'Incorreta. Eliminar backups e planos de recuperacao reduziria significativamente a confiabilidade do sistema diante de falhas graves.', 1),
  ('73000000-0000-4000-8000-000000000406', '62000000-0000-4000-8000-000000000102', 'A implementacao de planos de recuperacao de desastres (disaster recovery), garantindo que o sistema possa ser restaurado apos falhas graves.', true, 'Correta. Planos de recuperacao de desastres garantem que o sistema possa ser restaurado apos falhas graves, aumentando sua confiabilidade.', 2),
  ('73000000-0000-4000-8000-000000000407', '62000000-0000-4000-8000-000000000102', 'A reducao do numero de monitoramentos realizados sobre a infraestrutura utilizada.', false, 'Incorreta. Reduzir o monitoramento da infraestrutura dificulta a identificacao precoce de problemas, prejudicando a confiabilidade do sistema.', 3),
  ('73000000-0000-4000-8000-000000000408', '62000000-0000-4000-8000-000000000102', 'A concentracao de todos os dados e processos em um unico ponto, sem qualquer redundancia.', false, 'Incorreta. Concentrar tudo em um unico ponto, sem redundancia, aumenta o risco de falha total do sistema, reduzindo sua confiabilidade.', 4),
  ('73000000-0000-4000-8000-000000000409', '62000000-0000-4000-8000-000000000103', 'Pela quantidade de funcionarios alocados no departamento de marketing da empresa.', false, 'Incorreta. A quantidade de funcionarios do marketing nao tem relacao com a avaliacao tecnica da confiabilidade de um sistema.', 1),
  ('73000000-0000-4000-8000-000000000410', '62000000-0000-4000-8000-000000000103', 'Pelo numero de cores disponiveis na interface grafica da aplicacao.', false, 'Incorreta. Aspectos esteticos da interface grafica nao influenciam a avaliacao de confiabilidade de um sistema.', 2),
  ('73000000-0000-4000-8000-000000000411', '62000000-0000-4000-8000-000000000103', 'Pela analise de metricas como tempo medio entre falhas e tempo medio de recuperacao apos uma interrupcao.', true, 'Correta. Metricas como tempo medio entre falhas e tempo medio de recuperacao sao utilizadas para avaliar a confiabilidade de um sistema.', 3),
  ('73000000-0000-4000-8000-000000000412', '62000000-0000-4000-8000-000000000103', 'Pela quantidade de dispositivos moveis compativeis com o sistema.', false, 'Incorreta. A quantidade de dispositivos moveis compativeis nao e um indicador direto de confiabilidade do sistema.', 4),
  ('73000000-0000-4000-8000-000000000413', '62000000-0000-4000-8000-000000000104', 'Aumentar exclusivamente a velocidade da internet utilizada pelos funcionarios da seguradora.', false, 'Incorreta. A velocidade da internet dos funcionarios nao tem relacao direta com a prevencao de perda de dados por falta de backups.', 1),
  ('73000000-0000-4000-8000-000000000414', '62000000-0000-4000-8000-000000000104', 'Reduzir o numero de usuarios que tem acesso a aplicacao, sem qualquer relacao com backups.', false, 'Incorreta. Reduzir o numero de usuarios com acesso nao previne a perda de dados relacionada a ausencia de rotinas de backup.', 2),
  ('73000000-0000-4000-8000-000000000415', '62000000-0000-4000-8000-000000000104', 'Trocar a cor do painel administrativo da aplicacao para facilitar a navegacao dos usuarios.', false, 'Incorreta. Alteracoes esteticas no painel administrativo nao tem qualquer relacao com a prevencao de perda de dados em caso de falhas.', 3),
  ('73000000-0000-4000-8000-000000000416', '62000000-0000-4000-8000-000000000104', 'Implementar uma rotina de backups regulares e testados, garantindo a possibilidade de restauracao dos dados em caso de falhas graves.', true, 'Correta. Rotinas de backup regulares e testadas sao essenciais para garantir a restauracao de dados em caso de falhas graves, melhorando a confiabilidade.', 4),
  ('73000000-0000-4000-8000-000000000417', '62000000-0000-4000-8000-000000000105', 'A identificacao e correcao mais rapida de problemas antes que eles causem interrupcoes graves no servico.', true, 'Correta. O monitoramento continuo com alertas automaticos permite identificar e corrigir problemas rapidamente, antes de causarem interrupcoes graves.', 1),
  ('73000000-0000-4000-8000-000000000418', '62000000-0000-4000-8000-000000000105', 'A eliminacao completa e permanente de qualquer possibilidade de falha futura no sistema.', false, 'Incorreta. Nenhuma pratica elimina completamente a possibilidade de falhas futuras; o monitoramento apenas ajuda a identifica-las e corrigi-las mais rapidamente.', 2),
  ('73000000-0000-4000-8000-000000000419', '62000000-0000-4000-8000-000000000105', 'A reducao automatica do custo de infraestrutura utilizada pela aplicacao de rastreamento.', false, 'Incorreta. O monitoramento continuo nao esta diretamente relacionado a reducao automatica de custos de infraestrutura.', 3),
  ('73000000-0000-4000-8000-000000000420', '62000000-0000-4000-8000-000000000105', 'O aumento automatico da capacidade de processamento do sistema durante qualquer horario do dia.', false, 'Incorreta. O aumento automatico de capacidade esta mais relacionado ao conceito de elasticidade do que ao monitoramento voltado a confiabilidade.', 4),
  ('73000000-0000-4000-8000-000000000421', '62000000-0000-4000-8000-000000000106', 'A elasticidade do sistema diante de picos inesperados de trafego de usuarios.', false, 'Incorreta. Elasticidade esta relacionada ao ajuste automatico de capacidade conforme a demanda, nao a simulacao de falhas de componentes.', 1),
  ('73000000-0000-4000-8000-000000000422', '62000000-0000-4000-8000-000000000106', 'O modelo de consumo baseado no uso adotado pela equipe financeira da empresa.', false, 'Incorreta. O modelo de consumo baseado no uso nao esta relacionado a simulacao de falhas de componentes criticos do sistema.', 2),
  ('73000000-0000-4000-8000-000000000423', '62000000-0000-4000-8000-000000000106', 'A confiabilidade do sistema, verificando se os mecanismos de recuperacao funcionam corretamente diante de falhas simuladas.', true, 'Correta. Simular falhas em componentes criticos ajuda a validar se os mecanismos de recuperacao do sistema funcionam corretamente, testando sua confiabilidade.', 3),
  ('73000000-0000-4000-8000-000000000424', '62000000-0000-4000-8000-000000000106', 'A previsibilidade de custos mensais associados a infraestrutura de nuvem utilizada.', false, 'Incorreta. A previsibilidade de custos mensais nao esta diretamente relacionada a simulacao de falhas para testar mecanismos de recuperacao.', 4),
  ('73000000-0000-4000-8000-000000000425', '62000000-0000-4000-8000-000000000107', 'Reduzir a frequencia de testes de recuperacao de desastres para economizar tempo da equipe tecnica.', false, 'Incorreta. Reduzir a frequencia de testes de recuperacao de desastres pode comprometer ainda mais a confiabilidade do sistema, nao melhora-la.', 1),
  ('73000000-0000-4000-8000-000000000426', '62000000-0000-4000-8000-000000000107', 'Implementar monitoramento automatizado com alertas em tempo real, reduzindo o tempo entre a ocorrencia da falha e sua deteccao pela equipe.', true, 'Correta. Monitoramento automatizado com alertas em tempo real reduz o tempo de deteccao de falhas, melhorando a confiabilidade do sistema.', 2),
  ('73000000-0000-4000-8000-000000000427', '62000000-0000-4000-8000-000000000107', 'Aumentar o numero de funcionarios no departamento de vendas da empresa.', false, 'Incorreta. Aumentar o numero de funcionarios no departamento de vendas nao tem relacao com a melhoria da confiabilidade tecnica do sistema.', 3),
  ('73000000-0000-4000-8000-000000000428', '62000000-0000-4000-8000-000000000107', 'Eliminar completamente os backups regulares para simplificar a infraestrutura.', false, 'Incorreta. Eliminar backups regulares aumentaria o risco de perda de dados em caso de falhas, prejudicando ainda mais a confiabilidade.', 4),
  ('73000000-0000-4000-8000-000000000429', '62000000-0000-4000-8000-000000000108', 'Ambos os sistemas apresentam exatamente o mesmo nivel de confiabilidade diante de falhas.', false, 'Incorreta. Os dois sistemas apresentam niveis de confiabilidade significativamente diferentes diante de falhas.', 1),
  ('73000000-0000-4000-8000-000000000430', '62000000-0000-4000-8000-000000000108', 'Um sistema sem mecanismos de recuperacao automatica e sempre mais confiavel do que um sistema com failover automatico.', false, 'Incorreta. E o contrario: um sistema com failover automatico tende a ser mais confiavel do que um sistema sem esse mecanismo.', 2),
  ('73000000-0000-4000-8000-000000000431', '62000000-0000-4000-8000-000000000108', 'O failover automatico nao tem qualquer relacao com o conceito de confiabilidade de um sistema.', false, 'Incorreta. O failover automatico esta diretamente relacionado a confiabilidade, pois contribui para a recuperacao rapida do sistema apos falhas.', 3),
  ('73000000-0000-4000-8000-000000000432', '62000000-0000-4000-8000-000000000108', 'Um sistema com failover automatico tende a ser mais confiavel, pois pode se recuperar rapidamente de falhas sem intervencao manual imediata.', true, 'Correta. O failover automatico permite recuperacao rapida de falhas sem intervencao manual imediata, aumentando a confiabilidade do sistema.', 4),
  ('73000000-0000-4000-8000-000000000433', '62000000-0000-4000-8000-000000000109', 'Apenas ter redundancia nao garante confiabilidade completa; testes regulares de recuperacao de desastres sao essenciais para validar que os mecanismos de recuperacao realmente funcionam quando necessario.', true, 'Correta. Testes regulares de recuperacao de desastres sao essenciais para validar se os mecanismos de recuperacao realmente funcionam, complementando a redundancia.', 1),
  ('73000000-0000-4000-8000-000000000434', '62000000-0000-4000-8000-000000000109', 'O primeiro sistema e automaticamente mais confiavel apenas por possuir mais redundancia, independentemente de testes de recuperacao.', false, 'Incorreta. Ter mais redundancia nao garante automaticamente maior confiabilidade se os mecanismos de recuperacao nunca foram testados.', 2),
  ('73000000-0000-4000-8000-000000000435', '62000000-0000-4000-8000-000000000109', 'Testes de recuperacao de desastres sao irrelevantes para a confiabilidade real de um sistema, desde que haja redundancia suficiente.', false, 'Incorreta. Testes de recuperacao de desastres sao fundamentais para validar a confiabilidade real de um sistema, mesmo com redundancia presente.', 3),
  ('73000000-0000-4000-8000-000000000436', '62000000-0000-4000-8000-000000000109', 'Nao e possivel comparar a confiabilidade de dois sistemas com caracteristicas tao diferentes entre si.', false, 'Incorreta. E possivel, sim, comparar a confiabilidade de sistemas diferentes analisando fatores como redundancia e testes de recuperacao.', 4),
  ('73000000-0000-4000-8000-000000000437', '62000000-0000-4000-8000-000000000110', 'Depender exclusivamente de backups manuais realizados uma vez por mes, sem qualquer outro mecanismo de protecao.', false, 'Incorreta. Backups manuais mensais, sem outros mecanismos de protecao, nao sao suficientes para garantir indisponibilidade minima em um sistema critico.', 1),
  ('73000000-0000-4000-8000-000000000438', '62000000-0000-4000-8000-000000000110', 'Ignorar completamente a necessidade de testes de recuperacao, confiando apenas na experiencia da equipe tecnica.', false, 'Incorreta. Ignorar testes de recuperacao de desastres compromete a validacao dos mecanismos de protecao, mesmo com uma equipe tecnica experiente.', 2),
  ('73000000-0000-4000-8000-000000000439', '62000000-0000-4000-8000-000000000110', 'Combinar redundancia entre multiplas instancias e regioes, monitoramento continuo com alertas automaticos e testes regulares de recuperacao de desastres.', true, 'Correta. A combinacao de redundancia, monitoramento continuo e testes regulares de recuperacao e essencial para garantir alta confiabilidade em sistemas criticos.', 3),
  ('73000000-0000-4000-8000-000000000440', '62000000-0000-4000-8000-000000000110', 'Concentrar todos os dados e processos em um unico servidor altamente potente, sem qualquer redundancia adicional.', false, 'Incorreta. Concentrar tudo em um unico servidor, sem redundancia, cria um ponto unico de falha, incompativel com o nivel de confiabilidade exigido.', 4),
  ('73000000-0000-4000-8000-000000000441', '62000000-0000-4000-8000-000000000111', 'A capacidade de um sistema nunca sofrer qualquer variacao de desempenho, independentemente da carga.', false, 'Incorreta. Previsibilidade nao significa ausencia total de variacao de desempenho, mas sim a capacidade de prever e planejar diante dessas variacoes.', 1),
  ('73000000-0000-4000-8000-000000000442', '62000000-0000-4000-8000-000000000111', 'A capacidade de prever o comportamento de desempenho e os custos de um sistema em nuvem, permitindo planejamento adequado de recursos e orcamento.', true, 'Correta. Previsibilidade envolve a capacidade de prever desempenho e custos, permitindo planejamento adequado de recursos e orcamento.', 2),
  ('73000000-0000-4000-8000-000000000443', '62000000-0000-4000-8000-000000000111', 'A capacidade de armazenar dados indefinidamente sem qualquer custo adicional.', false, 'Incorreta. Previsibilidade nao esta relacionada ao armazenamento indefinido de dados sem custo.', 3),
  ('73000000-0000-4000-8000-000000000444', '62000000-0000-4000-8000-000000000111', 'A capacidade de um sistema ser acessado exclusivamente por meio de uma unica regiao geografica.', false, 'Incorreta. Previsibilidade nao se refere a restricao de acesso a uma unica regiao geografica.', 4),
  ('73000000-0000-4000-8000-000000000445', '62000000-0000-4000-8000-000000000112', 'Previsibilidade de desempenho e previsibilidade de custos.', true, 'Correta. As duas dimensoes principais da previsibilidade em cloud computing sao desempenho e custos.', 1),
  ('73000000-0000-4000-8000-000000000446', '62000000-0000-4000-8000-000000000112', 'Previsibilidade de cores de interface e previsibilidade de idiomas suportados.', false, 'Incorreta. Cores de interface e idiomas suportados nao sao dimensoes relevantes do conceito de previsibilidade em cloud computing.', 2),
  ('73000000-0000-4000-8000-000000000447', '62000000-0000-4000-8000-000000000112', 'Previsibilidade de numero de funcionarios e previsibilidade de horarios de reuniao.', false, 'Incorreta. Numero de funcionarios e horarios de reuniao nao sao dimensoes relacionadas ao conceito tecnico de previsibilidade.', 3),
  ('73000000-0000-4000-8000-000000000448', '62000000-0000-4000-8000-000000000112', 'Previsibilidade de logotipos e previsibilidade de fontes tipograficas utilizadas.', false, 'Incorreta. Logotipos e fontes tipograficas nao tem relacao com as dimensoes de previsibilidade discutidas em cloud computing.', 4),
  ('73000000-0000-4000-8000-000000000449', '62000000-0000-4000-8000-000000000113', 'Um editor de imagens integrado ao painel administrativo do provedor.', false, 'Incorreta. Um editor de imagens nao tem relacao com a previsao ou o monitoramento de custos de servicos de nuvem.', 1),
  ('73000000-0000-4000-8000-000000000450', '62000000-0000-4000-8000-000000000113', 'Um aplicativo de mensagens instantaneas fornecido pelo provedor de nuvem.', false, 'Incorreta. Um aplicativo de mensagens instantaneas nao e uma ferramenta relacionada a previsao de custos de nuvem.', 2),
  ('73000000-0000-4000-8000-000000000451', '62000000-0000-4000-8000-000000000113', 'Um servico de streaming de video disponibilizado gratuitamente pelo provedor.', false, 'Incorreta. Um servico de streaming de video nao esta relacionado a estimativa ou ao monitoramento de custos de nuvem.', 3),
  ('73000000-0000-4000-8000-000000000452', '62000000-0000-4000-8000-000000000113', 'Uma calculadora de precos e ferramentas de orcamento e alertas de custo, que ajudam a estimar e monitorar os gastos com os servicos de nuvem utilizados.', true, 'Correta. Calculadoras de precos e ferramentas de orcamento e alertas de custo ajudam a estimar e monitorar os gastos com servicos de nuvem.', 4),
  ('73000000-0000-4000-8000-000000000453', '62000000-0000-4000-8000-000000000114', 'Previsibilidade de desempenho, ja que os alertas estao relacionados a velocidade de processamento do sistema.', false, 'Incorreta. Alertas de orcamento estao relacionados a custos, nao diretamente a velocidade de processamento ou desempenho do sistema.', 1),
  ('73000000-0000-4000-8000-000000000454', '62000000-0000-4000-8000-000000000114', 'Elasticidade automatica, pois os alertas ajustam diretamente a capacidade computacional utilizada.', false, 'Incorreta. Alertas de orcamento nao ajustam automaticamente a capacidade computacional; eles apenas notificam sobre gastos.', 2),
  ('73000000-0000-4000-8000-000000000455', '62000000-0000-4000-8000-000000000114', 'Previsibilidade de custos, pois os alertas ajudam a monitorar e controlar os gastos antes que ultrapassem o orcamento planejado.', true, 'Correta. Alertas de orcamento ajudam a monitorar e controlar os gastos, reforcando diretamente a previsibilidade de custos da organizacao.', 3),
  ('73000000-0000-4000-8000-000000000456', '62000000-0000-4000-8000-000000000114', 'Alta disponibilidade, ja que os alertas evitam qualquer tipo de interrupcao do servico.', false, 'Incorreta. Alertas de orcamento nao estao diretamente relacionados a prevencao de interrupcoes do servico, mas sim ao controle financeiro.', 4),
  ('73000000-0000-4000-8000-000000000457', '62000000-0000-4000-8000-000000000115', 'Ignorar completamente a variacao de desempenho, ja que ela nao pode ser investigada ou corrigida.', false, 'Incorreta. A variacao de desempenho pode, sim, ser investigada e corrigida por meio de testes de carga e monitoramento continuo.', 1),
  ('73000000-0000-4000-8000-000000000458', '62000000-0000-4000-8000-000000000115', 'Realizar testes de carga consistentes e monitorar metricas de desempenho ao longo do tempo, identificando e corrigindo gargalos que causam variacoes inesperadas.', true, 'Correta. Testes de carga consistentes e monitoramento continuo ajudam a identificar e corrigir gargalos, melhorando a previsibilidade de desempenho.', 2),
  ('73000000-0000-4000-8000-000000000459', '62000000-0000-4000-8000-000000000115', 'Reduzir permanentemente a quantidade de usuarios que podem acessar a aplicacao simultaneamente.', false, 'Incorreta. Reduzir permanentemente o numero de usuarios simultaneos nao resolve a causa raiz da variacao imprevisivel de desempenho.', 3),
  ('73000000-0000-4000-8000-000000000460', '62000000-0000-4000-8000-000000000115', 'Eliminar completamente qualquer tipo de monitoramento da aplicacao para simplificar sua operacao.', false, 'Incorreta. Eliminar o monitoramento dificultaria ainda mais a identificacao das causas da variacao de desempenho, piorando a previsibilidade.', 4),
  ('73000000-0000-4000-8000-000000000461', '62000000-0000-4000-8000-000000000116', 'Escolher aleatoriamente um valor de custo mensal, sem qualquer analise previa do historico de consumo de recursos.', false, 'Incorreta. Escolher um valor aleatorio, sem analise previa, nao oferece a precisao necessaria para uma previsao confiavel de custos.', 1),
  ('73000000-0000-4000-8000-000000000462', '62000000-0000-4000-8000-000000000116', 'Evitar completamente o uso de qualquer ferramenta de estimativa de custos oferecida pelo provedor de nuvem.', false, 'Incorreta. Ferramentas de estimativa de custos sao justamente recursos uteis para melhorar a previsibilidade financeira, nao devendo ser evitadas.', 2),
  ('73000000-0000-4000-8000-000000000463', '62000000-0000-4000-8000-000000000116', 'Aumentar a quantidade de recursos utilizados sem qualquer criterio, apenas para simplificar o calculo do orcamento.', false, 'Incorreta. Aumentar recursos sem criterio nao simplifica o orcamento de forma confiavel; pelo contrario, pode gerar gastos desnecessarios.', 3),
  ('73000000-0000-4000-8000-000000000464', '62000000-0000-4000-8000-000000000116', 'Utilizar ferramentas de estimativa e calculadoras de precos do provedor de nuvem, combinadas com a analise do historico de consumo, para projetar os custos futuros com maior precisao.', true, 'Correta. Utilizar ferramentas de estimativa combinadas com a analise do historico de consumo permite projetar custos futuros com maior precisao.', 4),
  ('73000000-0000-4000-8000-000000000465', '62000000-0000-4000-8000-000000000117', 'Previsibilidade de desempenho, pois ha uma variacao inesperada e inconsistente no comportamento do sistema durante certos horarios.', true, 'Correta. A variacao inesperada e inconsistente no comportamento do sistema durante certos horarios indica um problema de previsibilidade de desempenho.', 1),
  ('73000000-0000-4000-8000-000000000466', '62000000-0000-4000-8000-000000000117', 'Previsibilidade de custos, ja que o problema descrito esta diretamente relacionado aos valores cobrados mensalmente.', false, 'Incorreta. O cenario descreve especificamente variacao de desempenho, e o texto indica que o custo mensal permanece relativamente estavel.', 2),
  ('73000000-0000-4000-8000-000000000467', '62000000-0000-4000-8000-000000000117', 'Elasticidade automatica, pois o problema esta relacionado exclusivamente ao ajuste manual de servidores.', false, 'Incorreta. O problema descrito nao esta relacionado especificamente ao ajuste manual de servidores, mas sim a consistencia do desempenho do sistema.', 3),
  ('73000000-0000-4000-8000-000000000468', '62000000-0000-4000-8000-000000000117', 'Responsabilidade compartilhada, ja que o problema envolve exclusivamente a divisao de tarefas entre cliente e provedor.', false, 'Incorreta. O cenario nao trata da divisao de responsabilidades entre cliente e provedor, mas sim da consistencia do desempenho da aplicacao.', 4),
  ('73000000-0000-4000-8000-000000000469', '62000000-0000-4000-8000-000000000118', 'Os dois conceitos sao exatamente identicos e podem ser tratados como sinonimos em qualquer contexto.', false, 'Incorreta. Embora relacionados, os dois conceitos possuem focos diferentes e nao devem ser tratados como sinonimos.', 1),
  ('73000000-0000-4000-8000-000000000470', '62000000-0000-4000-8000-000000000118', 'Previsibilidade de desempenho esta relacionada exclusivamente ao valor cobrado pelos servicos de nuvem utilizados.', false, 'Incorreta. Previsibilidade de desempenho esta relacionada ao comportamento tecnico do sistema, nao diretamente ao valor cobrado pelos servicos.', 2),
  ('73000000-0000-4000-8000-000000000471', '62000000-0000-4000-8000-000000000118', 'Previsibilidade de desempenho trata da consistencia do comportamento tecnico do sistema, enquanto previsibilidade de custos trata da capacidade de estimar e controlar os gastos financeiros.', true, 'Correta. Previsibilidade de desempenho trata da consistencia tecnica do sistema, enquanto previsibilidade de custos trata da estimativa de gastos financeiros.', 3),
  ('73000000-0000-4000-8000-000000000472', '62000000-0000-4000-8000-000000000118', 'Previsibilidade de custos esta relacionada exclusivamente a velocidade de processamento do sistema em diferentes horarios.', false, 'Incorreta. Previsibilidade de custos esta relacionada aos gastos financeiros, nao diretamente a velocidade de processamento do sistema.', 4),
  ('73000000-0000-4000-8000-000000000473', '62000000-0000-4000-8000-000000000119', 'Concluir que a previsibilidade de custos garante automaticamente a previsibilidade de desempenho, eliminando qualquer necessidade de analise adicional.', false, 'Incorreta. Previsibilidade de custos e de desempenho sao dimensoes distintas; uma nao garante automaticamente a outra.', 1),
  ('73000000-0000-4000-8000-000000000474', '62000000-0000-4000-8000-000000000119', 'Revisar os Acordos de Nivel de Servico (SLAs) do provedor quanto a janelas de manutencao e comunicacao previa, e considerar arquiteturas mais resilientes a essas variacoes, ja que previsibilidade de custos e de desempenho sao dimensoes distintas.', true, 'Correta. Revisar os SLAs quanto a manutencoes e considerar arquiteturas mais resilientes e a analise mais adequada, ja que as duas dimensoes sao distintas.', 2),
  ('73000000-0000-4000-8000-000000000475', '62000000-0000-4000-8000-000000000119', 'Ignorar completamente o impacto das manutencoes nao anunciadas, ja que elas nunca afetam o desempenho de aplicacoes em nuvem.', false, 'Incorreta. Manutencoes nao anunciadas podem, sim, afetar o desempenho de aplicacoes em nuvem, sendo um fator relevante a considerar.', 3),
  ('73000000-0000-4000-8000-000000000476', '62000000-0000-4000-8000-000000000119', 'Migrar imediatamente para outro provedor de nuvem, sem qualquer analise previa dos SLAs ou da arquitetura da aplicacao.', false, 'Incorreta. Migrar de provedor sem qualquer analise previa e uma decisao precipitada que ignora possiveis solucoes arquiteturais e contratuais.', 4),
  ('73000000-0000-4000-8000-000000000477', '62000000-0000-4000-8000-000000000120', 'Focar exclusivamente na previsibilidade de custos, ignorando completamente qualquer variacao possivel no desempenho do sistema.', false, 'Incorreta. Ignorar completamente o desempenho do sistema pode comprometer a experiencia dos usuarios durante o horario comercial.', 1),
  ('73000000-0000-4000-8000-000000000478', '62000000-0000-4000-8000-000000000120', 'Focar exclusivamente na previsibilidade de desempenho, sem qualquer preocupacao com o controle ou a estimativa dos custos envolvidos.', false, 'Incorreta. Ignorar o controle de custos pode comprometer o planejamento orcamentario anual exigido pelo sistema financeiro.', 2),
  ('73000000-0000-4000-8000-000000000479', '62000000-0000-4000-8000-000000000120', 'Utilizar uma capacidade totalmente fixa e superdimensionada, sem qualquer mecanismo de monitoramento de custos ou desempenho.', false, 'Incorreta. Uma capacidade fixa e superdimensionada, sem monitoramento, nao garante nem previsibilidade real de custos nem otimizacao de desempenho.', 3),
  ('73000000-0000-4000-8000-000000000480', '62000000-0000-4000-8000-000000000120', 'Combinar o uso de calculadoras de custo e alertas de orcamento para previsibilidade financeira com testes de carga regulares e monitoramento continuo de desempenho, ajustando a arquitetura conforme necessario.', true, 'Correta. Combinar ferramentas de estimativa de custos com testes de carga e monitoramento continuo de desempenho atende as duas dimensoes de previsibilidade.', 4);

do $$
declare
  invalid_slugs text;
begin
  select string_agg(invalid.lesson_slug, ', ' order by invalid.lesson_slug)
  into invalid_slugs
  from (
    select seed.lesson_slug
    from imported_question_batch1_seed seed
    left join public.lessons lesson on lesson.slug = seed.lesson_slug
    group by seed.lesson_slug
    having count(distinct lesson.id) <> 1
  ) invalid;

  if invalid_slugs is not null then
    raise exception 'A importação contém lesson_slug ausente ou ambíguo: %', invalid_slugs;
  end if;
end
$$;

with resolved_seed as (
  select
    seed.*,
    lesson.id as lesson_id,
    topic.id as topic_id,
    domain.id as domain_id,
    domain.certification_id
  from imported_question_batch1_seed seed
  join public.lessons lesson on lesson.slug = seed.lesson_slug
  join public.topics topic on topic.id = lesson.topic_id
  join public.domains domain on domain.id = topic.domain_id
),
new_seed as (
  select resolved.*
  from resolved_seed resolved
  where not exists (
    select 1
    from public.questions existing
    where existing.id = resolved.id
       or (
         existing.lesson_id = resolved.lesson_id
         and lower(trim(existing.question_text)) = lower(trim(resolved.question_text))
       )
  )
),
ordered_seed as (
  select
    new_seed.*,
    row_number() over (partition by new_seed.lesson_id order by new_seed.source_order)::integer as lesson_offset
  from new_seed
),
existing_order as (
  select
    lesson.id as lesson_id,
    coalesce(max(question.display_order), 0) as max_display_order
  from (select distinct lesson_id as id from ordered_seed) lesson
  left join public.questions question on question.lesson_id = lesson.id
  group by lesson.id
)
insert into public.questions (
  id, certification_id, domain_id, topic_id, lesson_id, question_text,
  question_type, difficulty, explanation, is_published, display_order
)
select
  ordered.id,
  ordered.certification_id,
  ordered.domain_id,
  ordered.topic_id,
  ordered.lesson_id,
  ordered.question_text,
  ordered.question_type,
  ordered.difficulty,
  ordered.explanation,
  ordered.is_published,
  existing.max_display_order + ordered.lesson_offset
from ordered_seed ordered
join existing_order existing on existing.lesson_id = ordered.lesson_id
order by ordered.source_order
on conflict (id) do nothing;

insert into public.question_options (
  id, question_id, option_text, is_correct, explanation, display_order
)
select
  option_seed.id,
  option_seed.question_id,
  option_seed.option_text,
  option_seed.is_correct,
  option_seed.explanation,
  option_seed.display_order
from imported_question_option_batch1_seed option_seed
join public.questions question on question.id = option_seed.question_id
on conflict (id) do nothing;

do $$
declare
  imported_questions integer;
  imported_options integer;
  imported_lessons integer;
  published_questions integer;
  invalid_option_groups integer;
begin
  select count(*), count(distinct lesson_id), count(*) filter (where is_published)
  into imported_questions, imported_lessons, published_questions
  from public.questions
  where id::text like '62000000-0000-4000-8000-%';

  select count(*) into imported_options
  from public.question_options
  where id::text like '73000000-0000-4000-8000-%';

  select count(*) into invalid_option_groups
  from (
    select question.id
    from public.questions question
    join public.question_options option on option.question_id = question.id
    where question.id::text like '62000000-0000-4000-8000-%'
    group by question.id
    having count(*) <> 4 or count(*) filter (where option.is_correct) <> 1
  ) invalid;

  if imported_questions <> 120 then
    raise exception 'Validação do lote falhou: esperadas 120 questões, encontradas %.', imported_questions;
  end if;
  if imported_options <> 480 then
    raise exception 'Validação do lote falhou: esperadas 480 alternativas, encontradas %.', imported_options;
  end if;
  if imported_lessons <> 12 then
    raise exception 'Validação do lote falhou: esperadas 12 lições, encontradas %.', imported_lessons;
  end if;
  if published_questions <> 120 then
    raise exception 'Validação do lote falhou: esperadas 120 questões publicadas, encontradas %.', published_questions;
  end if;
  if invalid_option_groups <> 0 then
    raise exception 'Validação do lote falhou: % questões não possuem quatro alternativas e uma resposta correta.', invalid_option_groups;
  end if;
end
$$;

commit;
